  ui_story_5038_50380001_3_dialog_content = "はぁ、はぁ…遅れてへんどすな！？",
  ui_story_5038_50380001_4_dialog_content = "タタ、息を切らせてどうしたのです？\nここまで急いで来たのですか？",
  ui_story_5038_50380001_5_dialog_content = "さっきの手紙を届けた時、言うてること分からへん言われて、\nなかなか受け取ってもらえへんかったんどす。",
  ui_story_5038_50380001_6_dialog_content = "どうしてこうなりますのやろ？\nタタはずっと公用語の練習しとりますのに…",
