  ui_story_5038_50380001_8_dialog_content = "大したこっちゃあらしまへん！\nうちはへっちゃらどす！",
  ui_story_5038_50380001_9_dialog_content = "それより、タタのせいでナルセール姐さんの用事に、\n支障は出てへんですやろか？",
  ui_story_5038_50380001_10_dialog_content = "いいえ、大丈夫ですよ。\n私は急いでいませんから…",
  ui_story_5038_50380001_11_dialog_content = "むしろ、今日はあなたの時間の方が貴重かもしれません。",
  ui_story_5038_50380001_12_dialog_content = "あれ、どないなこっとすか？",
  ui_story_5038_50380001_13_dialog_content = "あなたにお願いしたい手紙と小包があります。\nこちらがリストです。確認してください。",
  ui_story_5038_50380001_14_dialog_content = "<size=50>うひゃ！？30件！？</size>",
  ui_story_5038_50380001_15_dialog_content = "表のそれは速達のみですね。\n裏面の通常配達50件も確認してください。",
  ui_story_5038_50380001_16_dialog_content = "まだあるんどすか！？",
  ui_story_5038_50380001_17_dialog_content = "な、なんで突然こないな量…",
  ui_story_5038_50380001_18_dialog_content = "手元にあるんも、まだ届け終わってへんのに…",
  ui_story_5038_50380001_19_dialog_content = "配達の仕事には閑散期と繁忙期がありますからね。\n今はちょうど繁忙期ですし…",
  ui_story_5038_50380001_20_dialog_content = "おまけに、影ノ街で急に何かがあったようで…",
  ui_story_5038_50380001_21_dialog_content = "タタ、荷物の届け先を見てください。",
  ui_story_5038_50380001_22_dialog_content = "届け先どすか…",
  ui_story_5038_50380001_23_dialog_content = "この荷物、ぜんぶ影ノ街から――\n<color=#FFB400>双閣港</color>宛てになってますなぁ？",
  ui_story_5038_50380001_24_dialog_content = "その通りです。かなりの量の緊急配達依頼が\n影ノ街から双閣港宛てに出されています。",
  ui_story_5038_50380001_25_dialog_content = "どれも大至急と催促されていますから、\nここ2日ほどは大変なことになるでしょう。",
  ui_story_5038_50380001_26_dialog_content = "双閣港っちゅうのんはどないな場所どすか？\nどこにあるんどすやろ？うちは行ったことありませんなぁ。",
  ui_story_5038_50380001_27_dialog_content = "フフ、それでしたら、ちょうどいい機会ですね。",
  ui_story_5038_50380001_28_dialog_content = "双閣港の見物にはいい時期ですから。",
  ui_story_5038_50380001_29_dialog_content = "分かりました！\nほな、やる気満々で行ってきますぅ！",
  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>5日後</color>",
  ui_story_5038_50380001_31_dialog_content = "<size=50>うわあああああん！！！</size>",
  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerNameはん！\n助けておくれやすうぅぅぅ！</size>",
  ui_story_5038_50380001_33_dialog_content = "タタ！？どうしたの！？",
