  ui_story_5038_50380001_36_dialog_content = "落ち着いて。\n座ってゆっくり話してもらえる？",
  ui_story_5038_50380001_37_dialog_content = "ここんとこ影ノ街からの依頼で、うちらクーリエ隊は、\n大量の<color=#FFB400>紅色の画仙紙</color>を届けとるんどす…",
  ui_story_5038_50380001_38_dialog_content = "量が多いわ、急ぐわで、\nここ数日は残業続きなんどす…",
