  ui_story_5038_50380001_43_dialog_content = "…お、遅れてもうたら、みんなの足を引っ張った言われて、\nクビになってまいます…",
  ui_story_5038_50380001_44_dialog_content = "そないなことになったら、お金がのうなって、\nご飯も食べられへんし、住むところもなくなってまうし…",
  ui_story_5038_50380001_45_dialog_content = "雲山に帰って薪割りして\n暮らさなあかんようになってまいます！",
  ui_story_5038_50380001_46_dialog_content = "そんなに大ごとなの！？",
  ui_story_5038_50380001_47_dialog_content = "せやからPlayerNameはん、タタを助けとぉくれやす！",
  ui_story_5038_50380001_48_dialog_content = "ソラヴァンでタタを送ってもらえへんどっしゃろか！？",
  ui_story_5038_50380001_49_dialog_content = "お代はちゃんと払いますえ！\n今月のお給金が出たら、全部渡します！",
  ui_story_5038_50380001_50_dialog_content = "お金のことは気にしないで。\n助けになれるなら、僕もうれしいよ。",
  ui_story_5038_50380001_51_dialog_content = "急いでるなら、今すぐ出発しよう！",
  ui_story_5038_50380001_52_dialog_content = "で、目的地はどこ？",
  ui_story_5038_50380001_53_dialog_content = "「双閣港」っちゅう港町どす。",
  ui_story_5038_50380001_54_dialog_content = "それなら、ソラヴァンはちょうど\nゴールド・リバーの上空にいるから――",
  ui_story_5038_50380001_55_dialog_content = "川に沿って下流へ向かえば、\n海が見えるあたりにあるはずね。",
  ui_story_5038_50380001_56_dialog_content = "え？カレン、行ったことあるの？",
  ui_story_5038_50380001_57_dialog_content = "いいえ、ないわ。\n白夜城の蔵書で資料を見たことがあるだけよ。",
  ui_story_5038_50380001_58_dialog_content = "双閣港はゴールド・リバーの河口にあって、\n文化や風土が他の場所と大きく異なるから、いろいろな本に書かれているの。",
  ui_story_5038_50380001_59_dialog_content = "そういえば、あの町の起源を聞けば、\nあなたも興味を持つかもしれないわね。",
  ui_story_5038_50380001_60_dialog_content = "え？",
  ui_story_5038_50380001_61_dialog_content = "双閣港の建設には<color=#FFB400>リン家商会</color>が関わっているもの。",
  ui_story_5038_50380001_62_dialog_content = "リン家商会？\n影ノ街が本拠地じゃなかったの？",
  ui_story_5038_50380001_63_dialog_content = "影ノ街はリン家商会の取引の中継所にすぎないわ。\n双閣港こそがアストラ大陸における商会の本拠地よ。",
  ui_story_5038_50380001_64_dialog_content = "覚えているかしら？\nリン家商会は、はるか東にある別の大陸から来たということ。",
  ui_story_5038_50380001_65_dialog_content = "ゴールド・リバーの河口付近にはもともと、\n貧しい漁村しか無かったの。",
  ui_story_5038_50380001_66_dialog_content = "そこへある日、商会の巨大な船が到着して、\nアストラでの拠点になったという話よ。",
  ui_story_5038_50380001_67_dialog_content = "はるか東方から運び込まれた船荷をそこで下ろし、\nそれを今度はゴールド・リバーに沿って影ノ街へ運ぶ――",
  ui_story_5038_50380001_68_dialog_content = "そうした作業には人手が必要になるわ。人が集まれば、寝床や食事も必要になる。\nもともと漁をして暮らしていた人たちが、次々と新しい仕事に就くようになって…",
  ui_story_5038_50380001_69_dialog_content = "商会の成功に従って、\n港町も発展していったそうね。",
  ui_story_5038_50380001_70_dialog_content = "地元の住民たちも東方の文化を受け入れるようになり、\n龍州大陸の様式にならって、町が作られた。",
  ui_story_5038_50380001_71_dialog_content = "それで、徐々に新しい住民であるリン家と\n元からの住民たちが共存するようになったの。",
  ui_story_5038_50380001_72_dialog_content = "これから向かう先――双閣港は、そういう場所よ。",
  ui_story_5038_50380001_73_dialog_content = "一から商人が立ちあげた町なんて初めて聞いたわ。",
  ui_story_5038_50380001_74_dialog_content = "や、やっぱり物価が高かったりするのかしら…？\nそんなに予算の余裕がないんだけど…",
  ui_story_5038_50380001_75_dialog_content = "お金持ちの住む町だと、車を止めるのもお金がかかるって聞いたことがあるし…\nもしそうなら、ソラヴァンなんて…",
  ui_story_5038_50380001_76_dialog_content = "その心配はないと思うわ。\nただ、不必要な面倒は起こさない方がいい――",
  ui_story_5038_50380001_77_dialog_content = "PlayerName、ソラヴァンは町の外に停めておきましょう。",
  ui_story_5038_50380001_78_dialog_content = "そうだね。",
  ui_story_5038_50380001_79_dialog_content = "見て、もうすぐよ！",
  ui_story_5038_50380001_80_dialog_content = "わぁ…きれいな街並みね！",
  ui_story_5038_50380001_81_dialog_content = "町中真っ赤で、見ごたえありますやろ！",
  ui_story_5038_50380001_82_dialog_content = "本当だね。何かお祝いしてる雰囲気だ。",
  ui_story_5038_50380001_83_dialog_content = "本に書いてあった話によると、\nこれが別大陸の様式らしいわ。",
  ui_story_5038_50380001_84_dialog_content = "リン家の本国では、こうした建物や街並みが普通だそうね。",
  ui_story_5038_50380001_85_dialog_content = "アストラ大陸にいながら、\n海の向こう側の別世界に来たような気分ね。",
  ui_story_5038_50380001_86_dialog_content = "おまけに、祝日も全然ちゃうんどすえ！",
  ui_story_5038_50380001_87_dialog_content = "うちがここんとこ配達してた画仙紙っちゅうのも、\n向こうの伝統的な祝日に欠かせんものらしいんどす。",
  ui_story_5038_50380001_88_dialog_content = "その祝日っちゅうのが…ええと、確か…",
  ui_story_5038_50380001_89_dialog_content = "新年おめでとうございます。\n春新節を過ごしに来られたんですか？",
  ui_story_5038_50380001_90_dialog_content = "せや！「春新節」！",
  ui_story_5038_50380001_91_dialog_content = "皆さんはよそからお越しですね？\n双閣港にはこの半年、土地の者以外の出入りがありませんから…",
  ui_story_5038_50380001_92_dialog_content = "服を見てすぐに分かりました。",
  ui_story_5038_50380001_93_dialog_content = "ちょうどええとこに来てくれはったわ。\nご注文の画仙紙どす！受け取りのサインをお願いしますぅ！",
  ui_story_5038_50380001_94_dialog_content = "おや、ありがとうございます！\n年内に受け取れないかと思っていましたよ。",
  ui_story_5038_50380001_95_dialog_content = "ひとつ聞いてもいいですか？\nどうしてこんなにたくさん真っ赤な紙が要るんですか？",
  ui_story_5038_50380001_96_dialog_content = "なぜって、新年には欠かせないものだからですよ。",
  ui_story_5038_50380001_97_dialog_content = "龍州の春新節の伝統では、こういう画仙紙に\n對聯（ついれん）という詩や「福」という字を書いて、門や扉に貼るんです。",
  ui_story_5038_50380001_98_dialog_content = "それで新年もいいことがたくさんあるように願うんですよ。",
  ui_story_5038_50380001_99_dialog_content = "「龍州」というのは――東の大陸のことですか？",
  ui_story_5038_50380001_100_dialog_content = "その通りです。春新節のことは初めてお聞きになったようですね？",
  ui_story_5038_50380001_101_dialog_content = "まぁ、双閣港の人々はずっと自給自足で暮らしているので、\n内陸との往来はごくわずかですからね。",
  ui_story_5038_50380001_102_dialog_content = "こういう紅色の画仙紙も、\n今までなら、双閣港の店で買えていたのですが…",
  ui_story_5038_50380001_103_dialog_content = "今年は少々…問題がありまして…",
  ui_story_5038_50380001_104_dialog_content = "問題？何か異変でも？",
  ui_story_5038_50380001_105_dialog_content = "地元の店にほとんど商品が並ばなくなってしまったんです。\n画仙紙どころか、年越しに必要な物がほぼ買えないありさまで…",
  ui_story_5038_50380001_106_dialog_content = "そんなことが…物流が止まってるのかしら？",
  ui_story_5038_50380001_107_dialog_content = "いつもなら季節ごとに、\n龍州からリン家の<color=#FFB400>遠洋商船</color>が入港するのですが…",
  ui_story_5038_50380001_108_dialog_content = "どういうわけかこの半年間、\nまったく船が来ないんですよ。",
  ui_story_5038_50380001_109_dialog_content = "商船が運んでくる荷を仕入れていた店は、\nそろそろ限界ということでしょうね。",
  ui_story_5038_50380001_110_dialog_content = "そういった商品の中にはこの画仙紙も入っていましてね。\nやむなく、影ノ街から購入したというわけです。",
  ui_story_5038_50380001_111_dialog_content = "（何があったんだろう。心配だな…）",
  ui_story_5038_50380001_112_dialog_content = "（リン家商会には天空ノ谷にお墓を建ててもらっていた恩があるし、\n何があったのか気になる…）",
  ui_story_5038_50380001_113_dialog_content = "うーん…うちもその気持ち、よう分かります。\n故郷の味がなつかしくなりますやろ？",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>ボーッ、ボーッ…</color>",
  ui_story_5038_50380001_115_dialog_content = "ありゃ？なんの音やろ？",
  ui_story_5038_50380001_116_dialog_content = "港の方から、ラッパみたいな音ね…",
  ui_story_5038_50380001_117_dialog_content = "こ、これは…汽笛です！",
  ui_story_5038_50380001_118_dialog_content = "間違いありません！港から汽笛が聞こえてきます！",
  ui_story_5038_50380001_119_dialog_content = "港に船だ！リン家の船か！？",
  ui_story_5038_50380001_120_dialog_content = "リン家の商船が？",
  ui_story_5038_50380001_121_dialog_content = "PlayerName、ちょうどいい時に来たようね。",
  ui_story_5038_50380001_122_dialog_content = "商船だ！本当にリン家の船だ！",
  ui_story_5038_50380001_123_dialog_content = "よかった。今年の年越しは何もナシかと思ったよ！",
  ui_story_5038_50380001_124_dialog_content = "あ、開いた！誰か下りてくるぞ！",
  ui_story_5038_50380001_125_dialog_content = "…",
  ui_story_5038_50380001_126_dialog_content = "（風変わりな男の人だ…それに、表情が険しい）",
  ui_story_5038_50380001_127_dialog_content = "さあ、どいたどいた！お年寄りには道を譲ってあげてね！",
  ui_story_5038_50380001_128_dialog_content = "ほら、そこのお兄さん。\nキミがいたら、シュウさんの車いすが通れないでしょ。",
  ui_story_5038_50380001_129_dialog_content = "あ、そ、それって…車いすだったんですか！？",
  ui_story_5038_50380001_130_dialog_content = "す、すみません、失礼しました！",
  ui_story_5038_50380001_131_dialog_content = "構わんさ…リンセイ、何度言ったら分かる？\n年寄り扱いは止めろと言っておるだろう…",
  ui_story_5038_50380001_132_dialog_content = "それに、己のことは己でできる。",
  ui_story_5038_50380001_133_dialog_content = "あははは…ボクがただ、早く通りたかっただけだよ！",
  ui_story_5038_50380001_134_dialog_content = "龍州特産の上等な薬草を早く買いたくて仕方ないんだ！",
  ui_story_5038_50380001_135_dialog_content = "どいてくれ、先に通してくれ！\n金なら持ってるぞ！",
  ui_story_5038_50380001_136_dialog_content = "おい、前のヤツ！さっさと進んでくれ！",
  ui_story_5038_50380001_137_dialog_content = "うわぁ！？お、押さないで！",
  ui_story_5038_50380001_138_dialog_content = "皆様、お静かに。",
  ui_story_5038_50380001_139_dialog_content = "…",
  ui_story_5038_50380001_140_dialog_content = "蜃風号は新しくなったようだな。\n船長まで知らぬ顔になっているとは思わなかったが。",
  ui_story_5038_50380001_141_dialog_content = "リン家より、「蜃風号」を預かる新しい船長、ユエと申します。",
  ui_story_5038_50380001_142_dialog_content = "…確かに、この船とリン家の者を知る方々が多いようですね。",
  ui_story_5038_50380001_143_dialog_content = "半年ほど前、龍州の本家に少々変事があり、\n船を出せなくなっていました。",
  ui_story_5038_50380001_144_dialog_content = "長きにわたって龍州とアストラ大陸を結ぶ船が途絶えてしまい、\n皆様はきっと望郷の念に駆られたことでしょう。",
  ui_story_5038_50380001_145_dialog_content = "しかし、それも過去のこととなりました。\n私がこの地に立ったこの時をもって――",
  ui_story_5038_50380001_146_dialog_content = "龍州とアストラ大陸間の航路は、\n<color=#FFB400>無事再開</color>したことをお伝えいたします。",
  ui_story_5038_50380001_147_dialog_content = "…シュウさん、リン家の船が本当に来たよ！",
  ui_story_5038_50380001_148_dialog_content = "ボクたち、帰れるんだ！",
  ui_story_5038_50380001_149_dialog_content = "…",
  ui_story_5038_50380001_150_dialog_content = "龍州に帰れる？\n急に言われても、こっちにも予定ってもんが…",
  ui_story_5038_50380001_151_dialog_content = "そうだよな…商売仲間と酒を飲む約束もしちまってるし…\nなかなかすぐに離れるってわけには…",
  ui_story_5038_50380001_152_dialog_content = "この船で龍州に帰りたい方は\n切符さえ買っていただければ結構でございます。",
  ui_story_5038_50380001_153_dialog_content = "ただし、航路に変更がありますので、\n今回の航海には<color=#FFB400>危険</color>が伴うことをご了承くださいませ。",
  ui_story_5038_50380001_154_dialog_content = "かまわないさ！リン家の船は信用できる！\n3人分くれ！",
  ui_story_5038_50380001_155_dialog_content = "こっちにも1枚くれ！\nいざ帰りたいって時に売り切れじゃ困るからな…",
  ui_story_5038_50380001_156_dialog_content = "まあまあ皆さん、落ち着きなすって。",
  ui_story_5038_50380001_157_dialog_content = "蜃風号の出航まで、まだ時間はありますから。",
  ui_story_5038_50380001_158_dialog_content = "僕は蜃風号から下船したばかりですけど、\nこちらの人ってのは、あか抜けてらっしゃいますねぇ。",
  ui_story_5038_50380001_159_dialog_content = "どこかに僕の占いが必要な貴人さんでもいませんか？\nついでに道を教えてもらえると、助かりますねぇ。",
  ui_story_5038_50380001_160_dialog_content = "テンカンめ、さっそく人様をたばかろうとしておるわ…",
  ui_story_5038_50380001_161_dialog_content = "いやだなぁタンドウ殿下、僕はそんなことしませんって。",
  ui_story_5038_50380001_162_dialog_content = "…殿下、お気を付けを。",
  ui_story_5038_50380001_163_dialog_content = "うおおおおお――",
  ui_story_5038_50380001_164_dialog_content = "蜃風号、前よりも豪華になったな！",
  ui_story_5038_50380001_165_dialog_content = "しかも、広くなってるぞ…",
  ui_story_5038_50380001_166_dialog_content = "ゲホゲホ…相変わらずキュウさんは身のこなしが速いですねぇ…",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>ガヤガヤ…ガヤガヤ…</color>",
  ui_story_5038_50380001_168_dialog_content = "うぅ…う…",
  ui_story_5038_50380001_169_dialog_content = "タタ、どうしたの？",
  ui_story_5038_50380001_170_dialog_content = "う、うちも蜃風号の中、見てみたいどす…",
  ui_story_5038_50380001_171_dialog_content = "気になっとるものがあるんどす…",
  ui_story_5038_50380001_172_dialog_content = "あなたの探し物はこれかしら、配達人さん？",
  ui_story_5038_50380001_173_dialog_content = "あぁ――紅色の画仙紙がぎょうさん！",
  ui_story_5038_50380001_174_dialog_content = "そうどす！タタが見たかったもんは、これどす！",
  ui_story_5038_50380001_175_dialog_content = "出発前に聞いていたのよ。\n年越しが近いのに双閣港は何もかも品薄で、画仙紙もない…",
  ui_story_5038_50380001_176_dialog_content = "それで内陸の商会から仕入れるしかなくて、\n配達人が大わらわしてるってね。",
  ui_story_5038_50380001_177_dialog_content = "龍州の画仙紙が届いた以上、\nもう忙しく駆け回る必要もなくなるわ。",
  ui_story_5038_50380001_178_dialog_content = "<size=50>そりゃよかったです――これでうちも休めます！！</size>",
  ui_story_5038_50380001_179_dialog_content = "これでやっとタタが仕事から解放されたみたいね。",
  ui_story_5038_50380001_180_dialog_content = "あなたたち、アストラの内陸から来てるのでしょう？",
  ui_story_5038_50380001_181_dialog_content = "――やっぱり服装で分かるの？",
  ui_story_5038_50380001_182_dialog_content = "ふふ…それなら、あいさつしておかないとね。",
  ui_story_5038_50380001_183_dialog_content = "蜃風号はもうしばらくアストラ大陸に停泊するわ。",
  ui_story_5038_50380001_184_dialog_content = "その間、どうぞよろしく。",
  ui_story_5038_50380001_185_dialog_content = "（落ち着いて見えるし、カッコいい人ね！）",
  ui_story_5038_50380001_186_dialog_content = "あ、う、うん。僕はPlayerName…",
  ui_story_5038_50380001_187_dialog_content = "アストラ大陸へようこそ！",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>双閣港の街角</color>",
  ui_story_5038_50380101_2_dialog_content = "（ここ数日、ずいぶんのんびりできてる…）",
  ui_story_5038_50380101_3_dialog_content = "（春新節が近いせいもあるんだろうけど、\n双閣港は本当に落ち着ける場所だ）",
  ui_story_5038_50380101_4_dialog_content = "PlayerName、ぼーっとしてるみたいね？",
  ui_story_5038_50380101_5_dialog_content = "うん、ここに来て何日経ったんだっけって思ってたんだ。\nずいぶん長いこといる気がするよ。",
  ui_story_5038_50380101_6_dialog_content = "それなら記録をつけているから、\n正確な日数を教えてあげるわ。",
  ui_story_5038_50380101_7_dialog_content = "まず…最初の3日間、\nPlayerNameはテンカンと屋台巡りをして…",
  ui_story_5038_50380101_8_dialog_content = "4日目から6日目は、\n私たちと一緒に双閣港に伝わる伝統の遊びで対局して…",
  ui_story_5038_50380101_9_dialog_content = "6日目から10日目は、\nタンドウ主催の新春書道大会で惨敗…",
  ui_story_5038_50380101_10_dialog_content = "10日目から15日目は…",
  ui_story_5038_50380101_11_dialog_content = "わ、分かった…思い出したよ！",
  ui_story_5038_50380101_12_dialog_content = "とにかく、そろそろ帰りの準備をしなくちゃね。",
  ui_story_5038_50380101_13_dialog_content = "私は明日啓光に戻らなきゃいけないから、\n帰りのことは一人でゆっくり考えればいいと思うわ。",
  ui_story_5038_50380101_14_dialog_content = "え？そんな急に！？",
  ui_story_5038_50380101_15_dialog_content = "今はちょうど啓光でも、\n冬の特別補給路を開通させなきゃいけない時期なの。",
  ui_story_5038_50380101_16_dialog_content = "戻って物資配給の手伝いをしなきゃいけないのよ。",
  ui_story_5038_50380101_17_dialog_content = "私も例年通り、そろそろ帰らないとならないわね。\nベツレヘム陛下と北境で新年を過ごすから。",
  ui_story_5038_50380101_18_dialog_content = "早ければ、北境の馬車が今夜にも到着するはず。",
  ui_story_5038_50380101_19_dialog_content = "カレンも帰っちゃうの？",
  ui_story_5038_50380101_20_dialog_content = "仕方ないね。じゃあ僕は僕で…",
  ui_story_5038_50380101_21_dialog_content = "ありゃ！？誰かと思ったら！",
  ui_story_5038_50380101_22_dialog_content = "PlayerNameはん、バイスはん、カレンはん、\nおはようさんどす！",
  ui_story_5038_50380101_23_dialog_content = "あ、タタ！おはよう！",
  ui_story_5038_50380101_24_dialog_content = "仕事はどう？まだ忙しいの？",
  ui_story_5038_50380101_25_dialog_content = "心配はあらしまへん、\nうちのお仕事もいつもどおりに戻りましたえ！",
  ui_story_5038_50380101_26_dialog_content = "配達せなあかん手紙も、あと1通だけどす！",
  ui_story_5038_50380101_27_dialog_content = "何か手伝うことはあるかしら？\n今日はまだ時間があるわ。",
  ui_story_5038_50380101_28_dialog_content = "おおきに、バイスはん！\nでも、もうタタ一人で大丈夫どす。それに…",
  ui_story_5038_50380101_29_dialog_content = "うち、蜃風号の<color=#FFB400>切符</color>を買いましてん！",
  ui_story_5038_50380101_30_dialog_content = "今回の手紙っちゅうのが、海の向こう側宛てなんどす。\n目指すは龍州大陸ですえ！",
  ui_story_5038_50380101_31_dialog_content = "ほかの手紙はもう先に配達してあります。\n船に遅れたらあきまへんさかいに！",
  ui_story_5038_50380101_32_dialog_content = "旅行の機会としても悪くないわね。",
  ui_story_5038_50380101_33_dialog_content = "えへへ、楽しみでたまらんのです～。",
  ui_story_5038_50380101_34_dialog_content = "ここ数日、町の人たちも蜃風号の出発がどうのという話で\nもちきりのようだったわ。",
  ui_story_5038_50380101_35_dialog_content = "ま、みんなが心配するのも当然だよ。",
  ui_story_5038_50380101_36_dialog_content = "ボクはリン家の船が半年も来なかった<color=#FFB400>内情</color>を知ってるけどね！",
  ui_story_5038_50380101_37_dialog_content = "あ、あんさん…どなたどす？",
  ui_story_5038_50380101_38_dialog_content = "あ、そういえば…\n車いすにのったおっちゃんを助けとった兄さんどすな！",
  ui_story_5038_50380101_39_dialog_content = "アハハ！あれぐらい、助けるなんて言わないよ。\nシュウさんは友だちで、ボクの患者でもあるんだ。",
  ui_story_5038_50380101_40_dialog_content = "一緒にリン家の船に乗って、龍州大陸からきたんだけど…",
  ui_story_5038_50380101_41_dialog_content = "そうそう、ボクはリンセイ。\nあちこちを回って病を治して人を助ける、「流れの薬師」だよ。",
  ui_story_5038_50380101_42_dialog_content = "ニャ～オ――",
  ui_story_5038_50380101_43_dialog_content = "あれ！？",
  ui_story_5038_50380101_44_dialog_content = "ねねねねね…ネコや！",
  ui_story_5038_50380101_45_dialog_content = "シーッ…チビシッポ、おいたはだめだよ。\nご、ごめんね、わざとじゃないんだ！",
  ui_story_5038_50380101_46_dialog_content = "ほれ、それがしのところへ来るがよい。",
  ui_story_5038_50380101_47_dialog_content = "よしよし、やはりそれがしが好きか。",
  ui_story_5038_50380101_48_dialog_content = "シュウの周りのネコたちと仲良しなだけだよ…",
  ui_story_5038_50380101_49_dialog_content = "少しいいかしら？\n乗船客に確認しておくことがあるの。",
  ui_story_5038_50380101_50_dialog_content = "今ここにいるのが、タタさん、シュウさん、リンセイさん？\n龍州への復路に乗船希望で間違いないかしら？",
  ui_story_5038_50380101_51_dialog_content = "さいです！/さようだ/うん。",
  ui_story_5038_50380101_52_dialog_content = "分かったわ。\n出発前に確認してもらうことがあるの。",
  ui_story_5038_50380101_53_dialog_content = "龍州からの二人は、リン家に伝わる「航海の秘宝」のこと、\n聞いたことがあるでしょう？",
  ui_story_5038_50380101_54_dialog_content = "リン家の人々は実際にその秘宝の力で、\n幾度もの航海を無事に果たしてきたの。",
  ui_story_5038_50380101_55_dialog_content = "でも、秘宝の行方が分からなくなったまま、\n今でも見つかっていないのよ。",
  ui_story_5038_50380101_56_dialog_content = "この前の口上でも言ったことだけど、\n航海の危険性については、よく理解しておいてもらえるかしら。",
  ui_story_5038_50380101_57_dialog_content = "秘宝がないということは、今まで頼っていた経験がないに等しい…\nつまり、今回の航海は航路探索でもあるわ。",
  ui_story_5038_50380101_58_dialog_content = "行きは天候に恵まれて、\n無事に到着することができたけど…",
  ui_story_5038_50380101_59_dialog_content = "帰りも同じように無事とは限らないわ。\n船に乗るなら、このことを承知しておいて。",
  ui_story_5038_50380101_60_dialog_content = "急ぎの用でないなら、\n蜃風号への乗船は<color=#FFB400>お勧めしないわ</color>。",
  ui_story_5038_50380101_61_dialog_content = "（それがリン家の異変ってことだったのか…）",
  ui_story_5038_50380101_62_dialog_content = "う、うちは怖なんてあらしまへん！\n船長はんの力を信じとります！",
  ui_story_5038_50380101_63_dialog_content = "ふふ…なかなかの度胸ね。",
  ui_story_5038_50380101_64_dialog_content = "たまたまかどうかは知らないけど、\n乗客一人ひとりに今の話をして回ったら…",
  ui_story_5038_50380101_65_dialog_content = "今のところ、他の人は例外なく払い戻しを希望したわ。",
  ui_story_5038_50380101_66_dialog_content = "家族の面倒を見なければいけないから、とか\n急な用事が出来たとか言い出す人もいたわね。",
  ui_story_5038_50380101_67_dialog_content = "それも当然の話だけど。命を賭けてまで\n龍州に渡ろうとする人なんて、そういるわけもないし。",
  ui_story_5038_50380101_68_dialog_content = "せやけど、船長はんだって「命を賭けて」はりますやろ！",
  ui_story_5038_50380101_69_dialog_content = "何か起こっても、十分対処できるとは思ってるわ。\nそれが私の務めだし…",
  ui_story_5038_50380101_70_dialog_content = "なるほど、船長殿もそう自信があるわけではないと見える。",
  ui_story_5038_50380101_71_dialog_content = "それなら、<color=#FFB400>「羅針盤」</color>の行方には、\n興味がおありだろうな？",
  ui_story_5038_50380101_72_dialog_content = "！？",
  ui_story_5038_50380101_73_dialog_content = "あなたはリン家の人だったかしら？それとも…",
  ui_story_5038_50380101_74_dialog_content = "そうビックリすることないよ。\nボクたちは半年前の<color=#FFB400>あの事件</color>に居合わせたんだ。",
  ui_story_5038_50380101_75_dialog_content = "賊の船から誰かが逃げ延びたと言う話は聞いていないわ、\nそんなはずは…",
  ui_story_5038_50380101_76_dialog_content = "船長さんも知らなかったなら、\n賊どもだってボクらが生きてるなんて知らないだろうね～。",
  ui_story_5038_50380101_77_dialog_content = "あの時海に沈まなかったのは、\nボクとシュウさんだけだから。",
  ui_story_5038_50380101_78_dialog_content = "ということは、まさか、あなたがあのシュウ様？",
  ui_story_5038_50380101_79_dialog_content = "いかにも。",
  ui_story_5038_50380101_80_dialog_content = "当主が安否を心配しておりました。\n生きていらしたと知れば、さぞ喜ばれることでしょう。",
  ui_story_5038_50380101_81_dialog_content = "ふむ、奴も逃げおおせていたか。",
  ui_story_5038_50380101_82_dialog_content = "船長殿は大した胆力の持ち主と見受けられる。\nこの状況で航路を再開させるとは、実に見事な気概だ。",
  ui_story_5038_50380101_83_dialog_content = "だが、おそらくは双閣港との交易の回復以外に、\n「羅針盤」を探す使命も与えられているのであろう？",
  ui_story_5038_50380101_84_dialog_content = "…ええ。",
  ui_story_5038_50380101_85_dialog_content = "もしあくまで船に乗るとおっしゃるなら、\nお力を貸してはいただけませんか？",
  ui_story_5038_50380101_86_dialog_content = "むろんだ。だが、詳しくは船の上で話すとしよう。\n内陸の客人をこのまま放っておいては申し訳が立たぬ。",
  ui_story_5038_50380101_87_dialog_content = "僕たちのことですか？\nそんなに気をつかわなくて大丈夫ですよ…",
  ui_story_5038_50380101_88_dialog_content = "いずれにせよ、出航は2日後となります。\nその時また港でお会いしましょう。",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>2日後</color>",
  ui_story_5038_50380101_90_dialog_content = "あ！PlayerNameじゃないか！",
  ui_story_5038_50380101_91_dialog_content = "お別れを言いにきてくれたの？",
  ui_story_5038_50380101_92_dialog_content = "うん、カレンとバイスはもう双閣港を離れちゃったんだけど、\n伝言を預かってるから、伝えに来たんだ。",
  ui_story_5038_50380101_93_dialog_content = "「よい船旅を！またアストラ大陸に遊びに来てね」って。",
  ui_story_5038_50380101_94_dialog_content = "僕からの気持ちでもあるよ。",
  ui_story_5038_50380101_95_dialog_content = "まだ知り合ったばかりだけど、\nお別れするとなると、やっぱりさみしいね。",
  ui_story_5038_50380101_96_dialog_content = "ふむ、こちらの者はずいぶんと\nざっくばらんに気持ちを伝えるようじゃな。",
  ui_story_5038_50380101_97_dialog_content = "殿下も何かお話しになりますか？",
  ui_story_5038_50380101_98_dialog_content = "ふむ、そうじゃな…",
  ui_story_5038_50380101_99_dialog_content = "PlayerName、そなたの事は覚えておこう。",
  ui_story_5038_50380101_100_dialog_content = "シュウさんとテンカンが船の中で待ってるよ。\nボクたちもそろそろ行かなきゃ。",
  ui_story_5038_50380101_101_dialog_content = "そういえば、この間の白い小鳥さんは？",
  ui_story_5038_50380101_102_dialog_content = "…そうなんだよね。\nタタの見送りもしたいと思ってたんだけど…",
  ui_story_5038_50380101_103_dialog_content = "<size=50>うわあああああん！！！</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerNameはん！\n助けておくれやすうぅぅぅ！</size>",
  ui_story_5038_50380101_105_dialog_content = "あ！タタ、やっと来たね！",
  ui_story_5038_50380101_106_dialog_content = "手紙も小包も…\nいっこうに配達が終わらへんのですぅぅ！",
  ui_story_5038_50380101_107_dialog_content = "北境宛ての緊急の配達が入ったんどす！\n他の人も手が回らんっちゅう話で…",
  ui_story_5038_50380101_108_dialog_content = "えらく寒いところですし、道も分かりにくうおすやろ…\n配達できるのがうちしか居らんくて…",
  ui_story_5038_50380101_109_dialog_content = "ということは…まさか…",
  ui_story_5038_50380101_110_dialog_content = "せやからPlayerNameはん、タタを助けとぉくれやす！",
  ui_story_5038_50380101_111_dialog_content = "タタの代わりに龍州に行ってもらえへんやろか？",
  ui_story_5038_50380101_112_dialog_content = "お代はちゃんと払いますえ！\n今月のお給金が出たら、全部渡します！",
  ui_story_5038_50380101_113_dialog_content = "（なんだか聞き覚えがあるなぁ…）",
  ui_story_5038_50380101_114_dialog_content = "もちろん、助けるのは構わないけど、\nお金の問題じゃないんじゃない？",
  ui_story_5038_50380101_115_dialog_content = "君の乗船券って僕が使えるの？",
  ui_story_5038_50380101_116_dialog_content = "どうかしたかしら？",
  ui_story_5038_50380101_117_dialog_content = "船長は～ん！実は――",
  ui_story_5038_50380101_118_dialog_content = "…なるほど…そういう事ね。",
  ui_story_5038_50380101_119_dialog_content = "規則としては、\n別の人が代わりに乗船することは許されないわ。",
  ui_story_5038_50380101_120_dialog_content = "うう…そないですか…",
  ui_story_5038_50380101_121_dialog_content = "ほな、切符を持ってはる他の人に、\n配達を代わってもらえへんか聞いてみます…",
  ui_story_5038_50380101_122_dialog_content = "ただし、それとは別に…PlayerName、\n船長としてあなたを船に招待させてもらうわ。",
  ui_story_5038_50380101_123_dialog_content = "え！？どうして急に…",
  ui_story_5038_50380101_124_dialog_content = "シュウ様のご意向と言うべきかしら。",
  ui_story_5038_50380101_125_dialog_content = "2日前にシュウ様と話をして、\n「羅針盤」を探すことにしたの。",
  ui_story_5038_50380101_126_dialog_content = "シュウ様いわく、空の末裔であるあなたの助けを借りられれば、\n事はたやすく運ぶだろうという話だったわ。",
  ui_story_5038_50380101_127_dialog_content = "（たやすく…僕の感知能力で、羅針盤を感知するってこと？）",
  ui_story_5038_50380101_128_dialog_content = "今回は、来た時の経験を活かすことができるわ。",
  ui_story_5038_50380101_129_dialog_content = "「羅針盤」の事件でその場にいた、\nシュウ様とリンセイもついているし…",
  ui_story_5038_50380101_130_dialog_content = "タンドウ殿下とキュウ、テンカンも、\n全力で船を守ってくれるわ。",
  ui_story_5038_50380101_131_dialog_content = "私の舵取りの腕を信じてもらえるならだけど、\n手を貸してもらいたいの。",
  ui_story_5038_50380101_132_dialog_content = "（前からリン家商会とは何度かすれ違いになってるし、\nリン家と縁のある友だちもいる…）",
  ui_story_5038_50380101_133_dialog_content = "（今度こそ僕が何か助けになれるなら…）",
  ui_story_5038_50380101_134_option_content = "分かったよ！",
  ui_story_5038_50380101_135_dialog_content = "快諾に感謝するわ。\nそれならPlayerName、私は先に船に上がっているから。",
  ui_story_5038_50380101_136_dialog_content = "お兄さん、お、おおきに！",
  ui_story_5038_50380101_137_dialog_content = "そうと決まれば、何をもたもたしておる？\n早う船に乗るがよい。",
  ui_story_5038_50380101_138_dialog_content = "あ、い、今行くよ！",
  ui_story_5038_50380101_139_dialog_content = "ニャ～オ！",
  ui_story_5038_50380101_140_dialog_content = "あ！チビシッポ、お魚を見つけたみたいだ！",
  ui_story_5038_50380101_141_dialog_content = "でも、飛び降りたりしたらだめだよ！",
  ui_story_5038_50380101_142_dialog_content = "ニャ～…",
  ui_story_5038_50380101_143_dialog_content = "アストラ大陸の海風は、龍州の風よりずっと冷たいようね…",
  ui_story_5038_50380101_144_dialog_content = "船出には最高の天気だわ。",
  ui_story_5038_50380101_145_dialog_content = "蜃風号の帆は…西南の風ね。",
  ui_story_5038_50380101_146_dialog_content = "足場を上げるわ。\nみんな、しっかり座っていなさい！",
  ui_story_5038_50380101_147_dialog_content = "蜃風号、出航！",
  ui_story_5038_50380201_1_dialog_content = "（リン家の商船には本当に驚きだ。\n今まで乗ったことのある、どんな船より大きい…）",
  ui_story_5038_50380201_2_dialog_content = "（しかも、甲板まで極東風の華やかな設計になってる）",
  ui_story_5038_50380201_3_dialog_content = "（辺りは見渡す限りの海…）",
  ui_story_5038_50380201_4_dialog_content = "（それに、青空と波、さわやかな海風…）",
  ui_story_5038_50380201_5_dialog_content = "ん？",
  ui_story_5038_50380201_6_dialog_content = "シュウさん、一人で海を眺めてますけど、\n何かあったんですか？",
  ui_story_5038_50380201_7_dialog_content = "海の水を見ておる。",
  ui_story_5038_50380201_8_dialog_content = "海の水…何か変わったところでもあったんですか？",
  ui_story_5038_50380201_9_dialog_content = "いや…むしろ、変わりがないからこそ、\n故郷の港を思い出すのだ。",
  ui_story_5038_50380201_10_dialog_content = "故郷が恋しかったんですね。",
  ui_story_5038_50380201_11_dialog_content = "そういえば、出発前は他にも双閣港に足止めされてた人たちがいて、\nみんな船に乗るものだと思ってたのに…",
  ui_story_5038_50380201_12_dialog_content = "乗ったのは結局、シュウさんとリンセイだけでしたね。",
  ui_story_5038_50380201_13_dialog_content = "客地暮らしが長くなれば、誰でも故郷を思うものだ。",
  ui_story_5038_50380201_14_dialog_content = "乗船をやめた者たちも、故郷を思っていないわけではない。\nただ、双閣港にも「故郷」と言う心持ちの種がまかれ、根を張りだしたにすぎん。",
  ui_story_5038_50380201_15_dialog_content = "双閣港に新しい家族や友ができて、\n望郷の念は鏡の中の花のような、心に浮かぶだけの物となっているのだ。",
  ui_story_5038_50380201_16_dialog_content = "身ひとつで何の気がかりもなく旅することができるのは、\nそれがしのような者だけだ。",
  ui_story_5038_50380201_17_dialog_content = "その気持ち、何となく分かる気がします…",
  ui_story_5038_50380201_18_dialog_content = "はっはっは、貴公は若いと言うのに、\nそれがしの話に耳を傾けてくれるのだな。",
  ui_story_5038_50380201_19_dialog_content = "こうして話をしたのも何かの縁であろう。\nあまりかしこまらず、気楽に話してもらいたい。",
  ui_story_5038_50380201_20_dialog_content = "貴公とは友となりたいのでな。\n堅苦しいことは抜きにせぬか？",
  ui_story_5038_50380201_21_dialog_content = "リンセイ同様、気軽に付き合ってくれればよい。",
  ui_story_5038_50380201_22_dialog_content = "そんな風に言ってもらえて光栄です。\nそれじゃあ…",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>バシャッ！</color>",
  ui_story_5038_50380201_24_dialog_content = "うわ！？",
  ui_story_5038_50380201_25_dialog_content = "何があったの！？いきなり顔に水が…",
  ui_story_5038_50380201_26_dialog_content = "お魚の群れだね～。",
  ui_story_5038_50380201_27_dialog_content = "龍みたいな尻尾の魚だったら、\nそれは<color=#FFB400>ミズチウオ</color>だよ。",
  ui_story_5038_50380201_28_dialog_content = "びっくりしたなぁ…\nこんな高い甲板の上にいるのに水しぶきが届くの？",
  ui_story_5038_50380201_29_dialog_content = "ミズチウオは冬に元気になるからね。\n繁殖期ともいうけど。",
  ui_story_5038_50380201_30_dialog_content = "生まれてすぐに群れを作って、\n遠くの海へ泳いでいく魚なんだ。",
  ui_story_5038_50380201_31_dialog_content = "でも、どんなに遠くまで行っても、\n冬になるとまた仲間たちが集まって、それから…",
  ui_story_5038_50380201_32_dialog_content = "いっせいに回遊して、龍州の海の浅い所に卵を産む。\nそれを繰り返して、命をつないでいくんだよ。",
  ui_story_5038_50380201_33_dialog_content = "リンセイ、魚に詳しいんだね？",
  ui_story_5038_50380201_34_dialog_content = "フフン！\nまぁ、ミズチウオは、リン家商会に大事に思われてるからね。",
  ui_story_5038_50380201_35_dialog_content = "守り神とか象徴って言うのかな？",
  ui_story_5038_50380201_36_dialog_content = "あ、分かった気がする。\nその魚みたいに、出航した船が必ず戻って来ることを願ってるんだね。",
  ui_story_5038_50380201_37_dialog_content = "PlayerNameは賢い子だね～。\n卜子（ぼくし）いわく、孺子教うべし！",
  ui_story_5038_50380201_38_dialog_content = "まるで自分の方が大人みたいな物言いだね。",
  ui_story_5038_50380201_39_dialog_content = "小さくたって、PlayerNameの先輩かもしれないよ？",
  ui_story_5038_50380201_40_dialog_content = "キミには後輩らしく…",
  ui_story_5038_50380201_41_dialog_content = "…あれ？くんくん…いい匂いがする！\nお魚を焼いてるみたいだ！",
  ui_story_5038_50380201_42_dialog_content = "ちょうど昼餉の時間じゃからな。",
  ui_story_5038_50380201_43_dialog_content = "海へ出て1日目となれば、\n栄養をつけて、士気を上げねばなるまい。",
  ui_story_5038_50380201_44_dialog_content = "PlayerNameも食べるがよい。\n龍州名物――<color=#FFB400>揚げ魚の甘酢あんかけ</color>！",
  ui_story_5038_50380201_45_dialog_content = "魚の骨をとり、飾り包丁を入れ、\n油で揚げた後に甘酸っぱいあんかけをかけたものじゃ。",
  ui_story_5038_50380201_46_dialog_content = "ちょっと待って！\nこれ、何の魚で作ったの！？",
  ui_story_5038_50380201_47_dialog_content = "ミズチウオじゃ。とても柔らかいぞ。",
  ui_story_5038_50380201_48_dialog_content = "何だって！？",
  ui_story_5038_50380201_49_dialog_content = "ふふ…冗談じゃ。\n船に積んであった売り物の魚よ。",
  ui_story_5038_50380201_50_dialog_content = "二人とも、船室へ急ぐがいい。\n他の者はもう揃っておるぞ。",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>蜃風号、船室内</color>",
  ui_story_5038_50380201_52_dialog_content = "へ～え、殿下の料理の腕はたいしたもんですねぇ。\nまさに本場の味ってヤツです！",
  ui_story_5038_50380201_53_dialog_content = "そなたのほめ言葉は、どう受け取ればいいのか分からぬな。",
  ui_story_5038_50380201_54_dialog_content = "ただ、料理は全てキュウがこしらえたものじゃ。",
  ui_story_5038_50380201_55_dialog_content = "殿下も手伝ってくださいました。",
  ui_story_5038_50380201_56_dialog_content = "いやはや、お互いに認め合い、ゆずり合う主従なんてのは、\n済の国じゅう探しても、他にいないんじゃありませんかねぇ？",
  ui_story_5038_50380201_57_dialog_content = "…",
  ui_story_5038_50380201_58_dialog_content = "申し訳ありませんが、\n殿下はお国のことに関する話は好まれませんので…",
  ui_story_5038_50380201_59_dialog_content = "ここはやはり、双閣港からいらしたリン家ゆかりのお二方に、\n<color=#FFB400>事件</color>のことをお話し願えないでしょうか？",
  ui_story_5038_50380201_60_dialog_content = "もぐもぐ…ああ、おいしいおいしい！",
  ui_story_5038_50380201_61_dialog_content = "ほら、チビシッポも一口食べて！",
  ui_story_5038_50380201_62_dialog_content = "ニャ～オ。",
  ui_story_5038_50380201_63_dialog_content = "そちらの小さなお医者様は、\nお話どころではなさそうね。",
  ui_story_5038_50380201_64_dialog_content = "シュウ様、お願いいたします。",
  ui_story_5038_50380201_65_dialog_content = "船長殿に信用していただけたことはかたじけない。\nだが、半年も前のことだ。記憶違いもあるやもしれぬ。",
  ui_story_5038_50380201_66_dialog_content = "まずは、事件の起こる前後のことを話して進ぜよう。\n物語か何かと思って聞いてくれればよい。",
  ui_story_5038_50380201_67_dialog_content = "願ってもないことですねぇ！僕もあちこち回ってますが、\n奇聞珍聞ってのが一番好きでして。",
  ui_story_5038_50380201_68_dialog_content = "こいつはそう気楽に聞ける話ではないと思うがな。",
  ui_story_5038_50380201_69_dialog_content = "そもそも、それがしとリンセイは厳密にはリン家の者ではない。\nリン家の一員であられるのは、こちらの船長殿の方だ。",
  ui_story_5038_50380201_70_dialog_content = "シュウ様、恐れ入りますが…",
  ui_story_5038_50380201_71_dialog_content = "私もリンの姓を名乗ってはおりませんから、\n正式な家人とは言えません。",
  ui_story_5038_50380201_72_dialog_content = "これは失礼した。船長殿の姓を論じるつもりではなかった。\n話がそれてしまったのは私の落ち度だ。",
  ui_story_5038_50380201_73_dialog_content = "ともあれ、それがしはリン家と長い付き合いがあり、\nリンセイはリン家の食客だ。",
  ui_story_5038_50380201_74_dialog_content = "おかげで、あのような事件があってなお、\n生き延びることができたと言おうか。",
  ui_story_5038_50380201_75_dialog_content = "半年前に何があったんですか？",
  ui_story_5038_50380201_76_dialog_content = "全ては「羅針盤」に始まって、「羅針盤」に終わる。",
  ui_story_5038_50380201_77_dialog_content = "リン家は「羅針盤」の力によって海運を独占しておる。\nそれゆえ、反感も買い、よからぬことを考える者どもも多くいた。",
  ui_story_5038_50380201_78_dialog_content = "ある商会が先頭に立ち、いくつかの氏族と力を合わせ、\nリン家の勢力を覆そうとしたのだ。",
  ui_story_5038_50380201_79_dialog_content = "勢力としてはリン家に到底及ばぬが、\n恥知らずな手を使うこともいとわぬ連中だ。",
  ui_story_5038_50380201_80_dialog_content = "あの日、それがしとリンセイはリン家の宴会に招かれた。\n家の側近も多くいたのだが…",
  ui_story_5038_50380201_81_dialog_content = "にぎやかに酒が酌み交わされる中、\n突如として賊どもが乱入し…",
  ui_story_5038_50380202_1_dialog_content = "シュウさん！こっちだよ、急いで！",
  ui_story_5038_50380202_2_dialog_content = "ケガはない？",
  ui_story_5038_50380202_3_dialog_content = "かすり傷だ、大事ない。",
  ui_story_5038_50380202_4_dialog_content = "何はともあれ、ご当主だけは逃がすことができた。",
  ui_story_5038_50380202_5_dialog_content = "当主様、無事なんだね！よかった！",
  ui_story_5038_50380202_6_dialog_content = "だが、他の者は…",
  ui_story_5038_50380202_7_dialog_content = "今日を境に、商いの世界から\nリン家の屋号が消えるであろうな…",
  ui_story_5038_50380202_8_dialog_content = "どうしてこんなことに…\n堂々と屋敷に押し入りなんて、天も法もあったもんじゃないよ！",
  ui_story_5038_50380202_9_dialog_content = "そもそも失う物の無いやからということだろう。",
  ui_story_5038_50380202_10_dialog_content = "誰かがそれなりの見返りさえ出せば、\n命もかえりみず、悪事に手を染める。",
  ui_story_5038_50380202_11_dialog_content = "それがしの予想が正しければ、\n賊どもの真の目的は「羅針盤」であろうな。",
  ui_story_5038_50380202_12_dialog_content = "「羅針盤」？でも、アレはここには…",
  ui_story_5038_50380202_13_dialog_content = "賊どもの知らぬ事だからな。",
  ui_story_5038_50380202_14_dialog_content = "ご当主はあらかじめ「羅針盤」を守る手はずを整えておった。",
  ui_story_5038_50380202_15_dialog_content = "だが、万一のことがあれば…\nそれがしが始末をつけねばなるまい。",
  ui_story_5038_50380202_16_dialog_content = "リンセイ、ついて来い。",
  ui_story_5038_50380202_17_dialog_content = "その後、我らは何とか戦いから身を脱したのだが…",
  ui_story_5038_50380202_18_dialog_content = "その時は確証が無かったが、\nやはり賊どもの真の目的はリン家当主の命では無かった。",
  ui_story_5038_50380202_19_dialog_content = "だが、ご当主は「羅針盤」が賊の手に落ちたり壊されたりせぬよう、\nいち早く信頼のおける一族の者に羅針盤を託した。",
  ui_story_5038_50380202_20_dialog_content = "そうして「羅針盤」を乗せた船が、\n港を飛び出し、大海原へ落ち延びたのだ。",
  ui_story_5038_50380202_21_dialog_content = "大事な宝を乗せて海に…どうして？\n海にいた方が不測の事態が起こる可能性が高いんじゃ？",
  ui_story_5038_50380202_22_dialog_content = "隠し金庫とか、そういったところに置いておいた方が、\n安全じゃないんですか？",
  ui_story_5038_50380202_23_dialog_content = "海で生まれたものは、\n海にあるのが一番安全なんだよ。",
  ui_story_5038_50380202_24_dialog_content = "え？それってどういうこと…？",
  ui_story_5038_50380202_25_dialog_content = "「羅針盤」が守ってくれる船は一路順風、万事如意…\nつまり、絶対に遭難しないんだ。",
  ui_story_5038_50380202_26_dialog_content = "ただ…",
  ui_story_5038_50380202_27_dialog_content = "その「羅針盤」が結局、なくなってしまった。\n船長が聞きたいのはそのことだよね？",
  ui_story_5038_50380202_28_dialog_content = "「羅針盤」がなくなったのは、\n天災じゃない。人災なんだ。",
  ui_story_5038_50380202_29_dialog_content = "…",
  ui_story_5038_50380202_30_dialog_content = "賊どもは船を駆って、蜃風号を追った。",
  ui_story_5038_50380202_31_dialog_content = "騒ぎの中で、それがしとリンセイは海に落とされ、\n船に戻れなくなった。",
  ui_story_5038_50380202_32_dialog_content = "貴公らも察しがつくであろうが、賊どもは「羅針盤」を奪えておらぬ。\nさもなくば、航路がこうも長い間途絶えることはなかった。",
  ui_story_5038_50380202_33_dialog_content = "我らも賊の船も皆<color=#FFB400>大嵐</color>に見舞われてしまったのだ。",
  ui_story_5038_50380202_34_dialog_content = "それがしとリンセイ以外の者は皆、助からなかった。",
  ui_story_5038_50380202_35_dialog_content = "この両足もその時に傷を負ったのだ。",
  ui_story_5038_50380202_36_dialog_content = "大嵐が起こったのはどこの海域でしょう？",
  ui_story_5038_50380202_37_dialog_content = "すまぬが、分からん。\nそれがしは船乗りのような方向感覚は持っておらぬのでな。",
  ui_story_5038_50380202_38_dialog_content = "祟霊（すいれい）が生まれ持つ感覚というのか、\nリンセイのおかげで、それがしはアストラ大陸までたどり着くことができた。",
  ui_story_5038_50380202_39_dialog_content = "<color=#FFB400>「祟霊」</color>って何ですか？",
  ui_story_5038_50380202_40_dialog_content = "ええ～、PlayerName、失礼だなぁ。\n「祟霊」のことを知らないなんて。",
  ui_story_5038_50380202_41_dialog_content = "祟霊っていうのは、\nボクみたいに尻尾とか耳が生えてる光霊のこと！",
  ui_story_5038_50380202_42_dialog_content = "ついでにいうと、\n実は「チビシッポ」ってボクの兄さんにあたるんだ。",
  ui_story_5038_50380202_43_dialog_content = "ニャー！",
  ui_story_5038_50380202_44_dialog_content = "なるほど、だいたい分かったよ。",
  ui_story_5038_50380202_45_dialog_content = "（つまり、亜人族の血を引く光霊ってことかな。\n龍州ではきっとそう呼ぶんだろう）",
  ui_story_5038_50380202_46_dialog_content = "リン家の歴史に記録されている限り、\nこれまで「羅針盤」が失われたことはないの。",
  ui_story_5038_50380202_47_dialog_content = "この目で見たことはないけれど、\n<color=#FFB400>「船と共に生き、船とともに死す」</color>宝だと聞いているわ。",
  ui_story_5038_50380202_48_dialog_content = "私はたとえ船の残骸しか残っていないとしても、\nその行方を突き止めたいと考えているの。",
  ui_story_5038_50380202_49_dialog_content = "でも、今の話を聞いたうえで、\n皆さんを危険に巻き込むことも望んではいないわ。",
  ui_story_5038_50380202_50_dialog_content = "僕はその気持ちもわかるよ。\n船の皆の安全に関わる宝なら、そう簡単に諦めるわけには行かないよね。",
  ui_story_5038_50380202_51_dialog_content = "船長に言われなくても、\nボクは必ず「羅針盤」を見つけるつもりだけどね。",
  ui_story_5038_50380202_52_dialog_content = "夜も更けてきたわ。\n今日はこの辺りで帆を下ろしましょう。",
  ui_story_5038_50380202_53_dialog_content = "皆さんは安心して休んでいて。\n船の見張りは私たちの仕事だから。",
  ui_story_5038_50380202_54_dialog_content = "ボクも手伝うよ！",
  ui_story_5038_50380202_55_dialog_content = "子どもは早く寝なさい。",
  ui_story_5038_50380202_56_dialog_content = "もうっ！子どもじゃないって言ってるでしょ！",
  ui_story_5038_50380202_57_dialog_content = "それに、ボクもチビシッポも、\n夜はそもそも寝付けないんだよ。",
  ui_story_5038_50380202_58_dialog_content = "リンセイの好きにさせてやってくれ。\nさもないと、辛抱できずに他の者の眠りを妨げかねん。",
  ui_story_5038_50380202_59_dialog_content = "そんなことしないよ！",
  ui_story_5038_50380202_60_dialog_content = "分かりました。\nそういうことなら、リンセイは後で私に付いて甲板へ来て。",
  ui_story_5038_50380202_61_dialog_content = "船倉内の個室が寝室になっているわ。\nPlayerName、シュウ様、こちらへ。",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>真夜中</color>",
  ui_story_5038_50380301_2_dialog_content = "すぅ…",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>ゴロゴロ…</color>",
  ui_story_5038_50380301_4_dialog_content = "（ん？雷…？）",
  ui_story_5038_50380301_5_dialog_content = "（ずいぶん揺れてる…雨が降り出したのかな…）",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_5038_50380301_7_dialog_content = "わあ！？",
  ui_story_5038_50380301_8_dialog_content = "何の音！？",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>ニャーオ！</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>フシュー！！</color>",
  ui_story_5038_50380301_11_dialog_content = "怖がるでない…シン、よい子だ、大丈夫だ。",
  ui_story_5038_50380301_12_dialog_content = "面目ない。貴公の眠りを妨げてしまったようだな。",
  ui_story_5038_50380301_13_dialog_content = "シン、メン、ダクはそれがしと生死を共にしたネコたちでな…\n蜃風号の事件も経験している。",
  ui_story_5038_50380301_14_dialog_content = "こやつらにとって今の様子は\n悪夢の再現も同然、きっと恐ろしいのだろう。",
  ui_story_5038_50380301_15_dialog_content = "ネコの鳴き声は大したことじゃないですよ。\nそれよりも、今の音、聞こえました？",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_5038_50380301_17_dialog_content = "皆様、お目覚めですか。\nご無事でしょうか？",
  ui_story_5038_50380301_18_dialog_content = "キュウが真っ先に音に気付いて、\n二人で皆を起こしに回っていたところじゃ。",
  ui_story_5038_50380301_19_dialog_content = "いったい何が起こってるの？",
  ui_story_5038_50380301_20_dialog_content = "分からぬ。何かが船に当たっているとしか…",
  ui_story_5038_50380301_21_dialog_content = "しかも…どうやら<color=#FFB400>1体</color>ではないようですね。",
  ui_story_5038_50380301_22_dialog_content = "（まさか、暗鬼が…？真夜中の海に？）",
  ui_story_5038_50380301_23_dialog_content = "甲板に見に行ってくるよ！",
  ui_story_5038_50380301_24_dialog_content = "僕もおともしますよ。",
  ui_story_5038_50380301_25_dialog_content = "では、シュウ様は私と殿下と共に避難を。",
  ui_story_5038_50380301_26_dialog_content = "それがしの記憶が正しければ、\n下の船室とここがつながっているはずだ。",
  ui_story_5038_50380301_27_dialog_content = "なぜそれを…？",
  ui_story_5038_50380301_28_dialog_content = "古い方の蜃風号と作りがそっくりそのままなのでな。",
  ui_story_5038_50380301_29_dialog_content = "とにかく、急がねばならん。",
  ui_story_5038_50380301_30_dialog_content = "余計な世話かもしれぬが、\nリンセイと船長殿と合流しても、事態が解決できぬ時は…",
  ui_story_5038_50380301_31_dialog_content = "早々に見切りをつけ、2人を連れて下へ戻って来るがよい。\n無理をしてはならん。",
  ui_story_5038_50380301_32_dialog_content = "分かりました、安心してください。",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>蜃風号、甲板</color>",
  ui_story_5038_50380301_34_dialog_content = "すごい雨だ…",
  ui_story_5038_50380301_35_dialog_content = "船長！リンセイ！",
  ui_story_5038_50380301_36_dialog_content = "おーい、船長さん！ネコ坊！",
  ui_story_5038_50380301_37_dialog_content = "こりゃあいけない。\nこうも雨音が大きくちゃあ、僕らの声なんか届きやしませんねぇ。",
  ui_story_5038_50380301_38_dialog_content = "感知ってのを試してみたらどうです？\nウワサに名高い空の末裔なんでしょう？",
  ui_story_5038_50380301_39_option_content = "強制感知！",
  ui_story_5038_50380301_40_dialog_content = "うっ…ダメだ。\nかすかな光力と暗力が混ざってるのが分かるだけだ…",
  ui_story_5038_50380301_41_dialog_content = "…あれ？",
  ui_story_5038_50380301_42_dialog_content = "他にも、何か感じたことのない気配がする…",
  ui_story_5038_50380301_43_dialog_content = "タンドウの護衛の人が言ってた…1体じゃない、何かの群れだ！",
  ui_story_5038_50380301_44_dialog_content = "それから、すごく強いエネルギーを感じる…",
  ui_story_5038_50380301_45_dialog_content = "もうひと踏ん張りお願いしますよ、ダンナ！",
  ui_story_5038_50380301_46_dialog_content = "うーん…これ以上は…",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>ドカン！！！</color></size>",
  ui_story_5038_50380301_49_dialog_content = "うわっ！気を付けて！",
  ui_story_5038_50380301_50_dialog_content = "この音の出元を探ってみるってのはどうですかねぇ？",
  ui_story_5038_50380301_51_dialog_content = "そうだね！",
  ui_story_5038_50380301_52_dialog_content = "あ、あれは…",
  ui_story_5038_50380301_53_dialog_content = "チビシッポ！暴れちゃだめだって！",
  ui_story_5038_50380301_54_dialog_content = "これ以上暴れたら、落っこちちゃうよ！",
  ui_story_5038_50380301_55_dialog_content = "船長…そっちはどう！？",
  ui_story_5038_50380301_56_dialog_content = "リンセイ、まずはしっかりつかまりなさい！\n動き回らないで！",
  ui_story_5038_50380301_57_dialog_content = "リンセイ！船長！",
  ui_story_5038_50380301_58_dialog_content = "PlayerName、それにテンカンも！",
  ui_story_5038_50380301_59_dialog_content = "どうして上がってきたの！？",
  ui_story_5038_50380301_60_dialog_content = "急いで安全な所に逃げなさい。\nリンセイも連れて行って！",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>ドン！！！</color></size>",
  ui_story_5038_50380301_62_dialog_content = "あれは…<color=#FFB400>ミズチウオ</color>！",
  ui_story_5038_50380301_63_dialog_content = "ミズチウオが船腹にぶつかってきている！？\n工員、来なさい！",
  ui_story_5038_50380301_64_dialog_content = "は、はい！",
  ui_story_5038_50380301_65_dialog_content = "人数を集めて最下層の船室へ向かい、\n浸水防止の応急処置を！",
  ui_story_5038_50380301_66_dialog_content = "了解！",
  ui_story_5038_50380301_67_dialog_content = "ミズチウオだって！？",
  ui_story_5038_50380301_68_dialog_content = "なんで…どうしてミズチウオがこの船を？",
  ui_story_5038_50380301_69_dialog_content = "（これがリンセイの言っていたミズチウオ…）",
  ui_story_5038_50380301_70_dialog_content = "（銀色の宝石みたいで、見た目はきれいだけど…\nこんなに強い力があるなんて！）",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>ドン！！！</color></size>",
  ui_story_5038_50380301_72_dialog_content = "ほら、ネコ坊、何をぼーっとしてるんです！\n船べりから離れないと落ちますよ！",
  ui_story_5038_50380301_73_dialog_content = "リンセイ、ミズチウオはどうすれば止められるの！？",
  ui_story_5038_50380301_74_dialog_content = "む、無理だよ…\n「羅針盤」がなければ、止めるなんて…",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>ドン――</color></size>",
  ui_story_5038_50380301_76_dialog_content = "まずい…",
  ui_story_5038_50380301_77_dialog_content = "全員、急いで避難して。\n私が船首を安定させて、しばらく時間をかせぐわ！",
  ui_story_5038_50380301_78_dialog_content = "船がもう傾き始めてるの。\n船員の指示に従って、救命艇に乗りなさい！",
  ui_story_5038_50380301_79_dialog_content = "待って！",
  ui_story_5038_50380301_80_dialog_content = "待てると思う！？",
  ui_story_5038_50380301_81_dialog_content = "蜃風号が傾いてるのは、他に理由があるんだ！\n感知したんだ…",
  ui_story_5038_50380301_82_dialog_content = "何かが大量に船に上がって来てる！",
  ui_story_5038_50380301_83_dialog_content = "グォォ…",
  ui_story_5038_50380301_84_dialog_content = "グアァ！！！",
  ui_story_5038_50380301_85_dialog_content = "やっぱり…暗鬼が混乱に紛れて襲って来てる！",
  ui_story_5038_50380301_86_dialog_content = "…PlayerName、あなたが船に乗っていて\n本当によかったわ。",
  ui_story_5038_50380301_87_dialog_content = "こうとなれば、全部まとめて片づけましょう！",
  ui_story_5038_50380302_1_dialog_content = "これで全部だ！",
  ui_story_5038_50380302_2_dialog_content = "助かったわ、PlayerName。",
  ui_story_5038_50380302_3_dialog_content = "…と言っても、船は傾き続けてるようですねぇ…",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5038_50380302_5_dialog_content = "重量のあるものと貨物を船尾に移して、\n船体の平衡を保って！",
  ui_story_5038_50380302_6_dialog_content = "はい！",
  ui_story_5038_50380302_7_dialog_content = "ミズチウオが船首の縄をくわえていたせいで、\n暗鬼が船に上がってきたのね。",
  ui_story_5038_50380302_8_dialog_content = "PlayerName、リンセイ、テンカン。\nあなたたちも船尾へ移動して。",
  ui_story_5038_50380302_9_dialog_content = "分かった！",
  ui_story_5038_50380302_10_dialog_content = "ほら、こいつを掴んでください、PlayerNameの旦那！",
  ui_story_5038_50380302_11_dialog_content = "うわっ！？重い！これ、何？",
  ui_story_5038_50380302_12_dialog_content = "蜃風号が龍州から運んできた、\n箱いっぱいの分銅ですねぇ。",
  ui_story_5038_50380302_13_dialog_content = "どうしてそんなものが…",
  ui_story_5038_50380302_14_dialog_content = "勘定に使いますから、商売には欠かせないものですねぇ。\nとかく、役には立ちますよ。",
  ui_story_5038_50380302_15_dialog_content = "それにほら、今まさに役に立つところでしょう？",
  ui_story_5038_50380302_16_dialog_content = "僕と旦那で1箱ずつ持って船尾に行きゃあ、\n蜃風号の「おもし」になりますよ…",
  ui_story_5038_50380302_17_dialog_content = "おっとネコ坊、その小さい身体で無理はいけませんねぇ。",
  ui_story_5038_50380302_18_dialog_content = "ボクはここに残る。",
  ui_story_5038_50380302_19_dialog_content = "何を言ってるんですかねぇ？\nほら、行きますよ。",
  ui_story_5038_50380302_20_dialog_content = "ここに残るって言ってるでしょ。",
  ui_story_5038_50380302_21_dialog_content = "（リンセイはさっきからずっと海の方を見てる…\n何かを探してるみたいだ）",
  ui_story_5038_50380302_22_dialog_content = "リンセイ、何か考えでもあるの？\nミズチウオが暴れ出した理由を知ってるとか？",
  ui_story_5038_50380302_23_dialog_content = "いいや、ぜんぜん…",
  ui_story_5038_50380302_24_dialog_content = "でも、ミズチウオがワケもなく人を襲ったことなんて、\n今まで一度もないんだよ！",
  ui_story_5038_50380302_25_dialog_content = "ミズチウオは群れの「ヌシ」に従って行動するんだ…",
  ui_story_5038_50380302_26_dialog_content = "でも、だったら「ヌシ」はどうしてこの船を狙ってるんだろう？\nいったい何のために…？",
  ui_story_5038_50380302_27_dialog_content = "「ヌシ」を見つけようとしてるの？",
  ui_story_5038_50380302_28_dialog_content = "そうだよ…少なくとも、どの<color=#FFB400>方向</color>から来てるのか、\n見定めなくちゃ。",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_5038_50380302_30_dialog_content = "（群れの勢いがどんどん激しくなってる…\nこのままじゃまずい…）",
  ui_story_5038_50380302_31_option_content = "強制感知してみる！",
  ui_story_5038_50380302_32_dialog_content = "そんなことができるんですかい？",
  ui_story_5038_50380302_33_dialog_content = "わ、分からないけど、試してみる価値はあるよ！",
  ui_story_5038_50380302_34_dialog_content = "（さっきだって暗鬼の群れが「見えた」んだし…）",
  ui_story_5038_50380302_35_dialog_content = "（魚の群れだって感知できるかもしれない…\n何とかして大人しくさせなくちゃ…）",
  ui_story_5038_50380302_36_dialog_content = "（…ダメだ。ぜんぜん反応がない！）",
  ui_story_5038_50380302_37_dialog_content = "あっ、ホントに止まった！\nPlayerName、見て！",
  ui_story_5038_50380302_38_dialog_content = "え！？ま、まぐれかな！？",
  ui_story_5038_50380302_39_dialog_content = "群れが急に方向を変えて、帯みたいになってる…",
  ui_story_5038_50380302_40_dialog_content = "…いや、違う！何かおかしい！！",
  ui_story_5038_50380302_41_dialog_content = "ど、どういうことです！？",
  ui_story_5038_50380302_42_dialog_content = "船べりをつかんで、かがんで！",
  ui_story_5038_50380302_43_dialog_content = "こっちに…突進してくる！！",
  ui_story_5038_50380302_44_dialog_content = "船長、急いで方向転換して！",
  ui_story_5038_50380302_45_dialog_content = "（ミズチウオに散々ぶつかられて、蜃風号は傷だらけ。\nそのうえ、この大嵐じゃ…）",
  ui_story_5038_50380302_46_dialog_content = "（舵なんて利かない…）",
  ui_story_5038_50380302_47_dialog_content = "しっかりつかまりなさい！\n頭を守って！",
  ui_story_5038_50380302_48_dialog_content = "（海よ…再び蜃風号を拒まれると言うのですか…）",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>ドン！！！</color></size>",
  ui_story_5038_50380402_1_dialog_content = "イタタタ――！",
  ui_story_5038_50380402_2_dialog_content = "（体中が痛い…背中も痛めたみたいだ…）",
  ui_story_5038_50380402_3_dialog_content = "（僕は…生きてる？）",
  ui_story_5038_50380402_4_dialog_content = "PlayerName、大丈夫？",
  ui_story_5038_50380402_5_dialog_content = "ユ、ユエ！助かったんだね！",
  ui_story_5038_50380402_6_dialog_content = "…皆は？",
  ui_story_5038_50380402_7_dialog_content = "PlayerName、いつまで寝てるの？\nお日様が出てから、もうだいぶ経ってるよ！",
  ui_story_5038_50380402_8_dialog_content = "大事ないか、小友？",
  ui_story_5038_50380402_9_dialog_content = "心配したぞ、PlayerName。",
  ui_story_5038_50380402_10_dialog_content = "まだ頭が少し痛むけど…\n昨日は結局、どうなったの？",
  ui_story_5038_50380402_11_dialog_content = "ミズチウオに衝突されて、蜃風号はほぼ制御不能…",
  ui_story_5038_50380402_12_dialog_content = "最終的に、暗礁に乗り上げたわ。",
  ui_story_5038_50380402_13_dialog_content = "その後どういうわけか、\nミズチウオが去って、風や波もおさまったの。",
  ui_story_5038_50380402_14_dialog_content = "あなたとテンカンは揺れで気を失っていたところを\n船方が見つけて、船室へ移されたというところよ。",
  ui_story_5038_50380402_15_dialog_content = "リンセイがあなたたち2人に\n薬を飲ませてくれてるわ。",
  ui_story_5038_50380402_16_dialog_content = "甲板で日向ぼっこさせようっていうのも、\nボクの考えだよ。",
  ui_story_5038_50380402_17_dialog_content = "確かに、体が温まってる気がする…",
  ui_story_5038_50380402_18_dialog_content = "うっ！？",
  ui_story_5038_50380402_19_dialog_content = "おえっ…口の中がすごく苦い！\nな、何を飲ませたの！？",
  ui_story_5038_50380402_20_dialog_content = "あ、だめだよ、吐き出しちゃ！\n船酔いを止める薬なんだから！",
  ui_story_5038_50380402_21_dialog_content = "マンダラゲとキンギンカ、あとハッカが入ってるんだ。",
  ui_story_5038_50380402_22_dialog_content = "良薬口に苦しっていうでしょ！？\nPlayerName、がまんしてね！",
  ui_story_5038_50380402_23_dialog_content = "わ、分かったよ…",
  ui_story_5038_50380402_24_dialog_content = "でも、もう立って動けるみたいだし、\n心配はいらなそうだね。",
  ui_story_5038_50380402_25_dialog_content = "僕のことより、あんな目に遭って、\n蜃風号はどうなってるの？",
  ui_story_5038_50380402_26_dialog_content = "よくないわね。",
  ui_story_5038_50380402_27_dialog_content = "帆柱が風と波で折られたわ。\n船倉内の浸水もひどい。",
  ui_story_5038_50380402_28_dialog_content = "蜃風号はもうボロボロね。\nこれ以上の波風には耐えられないわ。",
  ui_story_5038_50380402_29_dialog_content = "そんなに！？",
  ui_story_5038_50380402_30_dialog_content = "それじゃあ、航海を続けるどころか、\n生きていられるかも分からないってことだよね…",
  ui_story_5038_50380402_31_dialog_content = "…まさにあの時見たままの光景だな…",
  ui_story_5038_50380402_32_dialog_content = "私の思い上がりだったのよ。自分の力だけで航路を再開できる、\nアストラ大陸まで船を出せるなんて思ったばっかりに…",
  ui_story_5038_50380402_33_dialog_content = "それだけじゃないわ。\n「羅針盤」がなくても、無事に航海できると思っていた…",
  ui_story_5038_50380402_34_dialog_content = "やはり…リン家には「羅針盤」の加護が必要だったのね…",
  ui_story_5038_50380402_35_dialog_content = "きのうのミズチウオの群れ、\n今思い返してもやっぱり何かおかしいよ。",
  ui_story_5038_50380402_36_dialog_content = "船長、リン家の人なんでしょ。\nだったら、ミズチウオの習性も知ってるはずだよね。",
  ui_story_5038_50380402_37_dialog_content = "ミズチウオはヌシに従って行動する生き物で、\nむやみに攻撃なんてしない。",
  ui_story_5038_50380402_38_dialog_content = "それは昔の話よ。",
  ui_story_5038_50380402_39_dialog_content = "この半年で海を回遊するミズチウオの性格が\n大きく変わっているの。",
  ui_story_5038_50380402_40_dialog_content = "理由もなく海を行く船を襲い、\n船人もろとも船を沈めてしまうようになったのよ。",
  ui_story_5038_50380402_41_dialog_content = "私と部下だけなら賭けに出るのは構わないけど、\n預かっている命まで賭けるわけには行かない…",
  ui_story_5038_50380402_42_dialog_content = "蜃風号では、これ以上の航行は…",
  ui_story_5038_50380402_43_dialog_content = "どういうことじゃ？\n先に進めぬと言うが、ここに永久にとどまることも出来ぬぞ…",
  ui_story_5038_50380402_44_dialog_content = "座して死を待てということか？",
  ui_story_5038_50380402_45_dialog_content = "…",
  ui_story_5038_50380402_46_dialog_content = "船長…",
  ui_story_5038_50380402_47_dialog_content = "昼間っからしょぼくれた顔してちゃあ、\nいけませんねぇ。",
  ui_story_5038_50380402_48_dialog_content = "さっき卦を立ててみたんですがね、\n聞いてみませんか？",
  ui_story_5038_50380402_49_dialog_content = "かような時まで、イカサマで人をたぶらかそうとしおって…",
  ui_story_5038_50380402_50_dialog_content = "イカサマじゃありませんって。他の皆さんはいいとしても、\n船長さんには聞いてもらわないといけませんねぇ。",
  ui_story_5038_50380402_51_dialog_content = "なぜ私なのかしら？",
  ui_story_5038_50380402_52_dialog_content = "さっき夢から覚めた時、\nまぶたがやけに落ち着かなかったものでねぇ。",
  ui_story_5038_50380402_53_dialog_content = "昨日の晩のことを思い出してみて、\n窮地の中にこそ天啓が隠れてると悟ったってワケですよ。",
  ui_story_5038_50380402_54_dialog_content = "要点を話してもらえるかしら。",
  ui_story_5038_50380402_55_dialog_content = "はいはい、分かりましたよ…\n蜃風号の運命を占ってみたんですがねぇ…",
  ui_story_5038_50380402_56_dialog_content = "僕の「万類天斗卦」は一見ただの陰陽と動物を卦象としてるだけに見えますがね、\n実際は色々と奥深くて…",
  ui_story_5038_50380402_57_dialog_content = "残念なことに僕は算命のことなら分かるんですが、\n蜃風号のことは分かりませんのでね…",
  ui_story_5038_50380402_58_dialog_content = "要するに、船長に船の事を教えていただかないと、\n卦の意味が分からないってことですねぇ。",
  ui_story_5038_50380402_59_dialog_content = "もったいぶらなくていいわ。",
  ui_story_5038_50380402_60_dialog_content = "今の蜃風号の有り様じゃ、\nわらにもすがってみるしかないもの。",
  ui_story_5038_50380402_61_dialog_content = "どうも奇妙な結果でしてねぇ。\n「首鼠両端」、「猿猴取月」、「狡兎三窟」と出まして。",
  ui_story_5038_50380402_62_dialog_content = "僕も長年あちこち回ってますがね、\nこんなワケの分からない卦象は初めてですよ。",
  ui_story_5038_50380402_63_dialog_content = "3つとも同じ陰陽ってことは、\n何か一つのことを指してるとは思うんですけどねぇ…",
  ui_story_5038_50380402_64_dialog_content = "ネズミ、サル、ウサギ…？",
  ui_story_5038_50380402_65_dialog_content = "テンカン、あなたはどう思っているの？",
  ui_story_5038_50380402_66_dialog_content = "シロウト考えですがね、\n「交換する」ってことではないかなと。",
  ui_story_5038_50380402_67_dialog_content = "ニセモノもホンモノも見方次第ってことですよ。\n何かの<color=#FFB400>代わり</color>を探せと言ってるんじゃないですかねぇ。",
  ui_story_5038_50380402_68_dialog_content = "「代わり」を探す…",
  ui_story_5038_50380402_69_dialog_content = "分かったわ。",
  ui_story_5038_50380402_70_dialog_content = "龍州の習わしでは、\n船体の重要な部品を干支という動物の種類になぞらえて呼ぶの。",
  ui_story_5038_50380402_71_dialog_content = "そうすることで、吉祥を呼び込み、\n陸を歩くその動物たちのように、穏やかに航海を終えられるよう祈りを込めるのよ。",
  ui_story_5038_50380402_72_dialog_content = "昨日の嵐で、たくさんの部品が損傷しているわ。",
  ui_story_5038_50380402_73_dialog_content = "蜃風号の「鼠尾」と「猴頭」…つまり船尾と船首もそのうちね。\n「鼠尾」は失くなり、「猴頭」は破損…",
  ui_story_5038_50380402_74_dialog_content = "でも、「兎耳」に大きな損傷はないわね。",
  ui_story_5038_50380402_75_dialog_content = "「兎」の卦については、僕ももう少し考えてみますか…",
  ui_story_5038_50380402_76_dialog_content = "でも、残りの2つの代わりが見つかれば、\n蜃風号が元のように航海できるようになるんじゃないですかねぇ？",
  ui_story_5038_50380402_77_dialog_content = "今言えるのは、修理の参考にはなるということだけね。\n航海できるようになるかは断言できないわ。",
  ui_story_5038_50380402_78_dialog_content = "ボロボロの場所が多いし、小手先でごまかせる問題じゃないわ。\n一つ一つ修理していくしかないの。",
  ui_story_5038_50380402_79_dialog_content = "それに、代わりといっても、\nいったいどこにあるというの？",
  ui_story_5038_50380402_80_dialog_content = "そのことならば、それがしに思い当たる事がある。",
  ui_story_5038_50380402_81_dialog_content = "この大海原こそ、まさに大きな「宝の山」なのではないか？",
  ui_story_5038_50380501_1_dialog_content = "（シュウとユエの提案で、救命艇は使わず、\n蜃風号で航海を続けることになった）",
  ui_story_5038_50380501_2_dialog_content = "（船のいかりも引き上げられた）",
  ui_story_5038_50380501_3_dialog_content = "（僕たちはこれで…無事に旅を続けられるんだろうか？）",
  ui_story_5038_50380501_4_dialog_content = "非常に危険な賭けではあるが…",
  ui_story_5038_50380501_5_dialog_content = "海には無数の船が沈んでおる。\nこの蜃風号が半年前事故のあった海域にたどり着けたならば…",
  ui_story_5038_50380501_6_dialog_content = "何か使える部品を引き上げられるやもしれぬ。",
  ui_story_5038_50380501_7_dialog_content = "大海に針をすくうようなマネであることは分かっているが…",
  ui_story_5038_50380501_8_dialog_content = "残された策の中ではマシな選択と言えよう。",
  ui_story_5038_50380501_9_dialog_content = "シュウ様のおっしゃる通りね。",
  ui_story_5038_50380501_10_dialog_content = "蜃風号の救命艇で嵐を越えるのは不可能よ。",
  ui_story_5038_50380501_11_dialog_content = "かといって、いつまでも海の上には留まれない。",
  ui_story_5038_50380501_12_dialog_content = "天候の良い時を選んでゆっくりと進む方が、\nこのままただ死ぬのを待っているよりはずっといいはず。",
  ui_story_5038_50380501_13_dialog_content = "皆、帆を下ろして、船の両側面にかいを出して。",
  ui_story_5038_50380501_14_dialog_content = "海図の航路と印に従って、\n海難のあった場所を目指すわ。",
  ui_story_5038_50380501_15_dialog_content = "船長は簡単そうに言うけど、\nやっぱり危険よね…",
  ui_story_5038_50380501_16_dialog_content = "おい、船長の目の前だぞ。\n聞かれたらどうする。",
  ui_story_5038_50380501_17_dialog_content = "いざ災難となったら、俺たちの命なんざ、\nどうせ船長のいいなりに任せるしかねぇんだ。",
  ui_story_5038_50380501_18_dialog_content = "陰で船長をそしるとは、口さがない奴らじゃな。",
  ui_story_5038_50380501_19_dialog_content = "で、殿下…",
  ui_story_5038_50380501_20_dialog_content = "恨み言があるなら、堂々と本人に話せばよい。\nこの場は皆で解決策を探るのが正道というもの。",
  ui_story_5038_50380501_21_dialog_content = "何が起こるか分からぬ大海原に命を投げ出して、\n今さら何を恐れると言うか？",
  ui_story_5038_50380501_22_dialog_content = "何の騒ぎかしら？",
  ui_story_5038_50380501_23_dialog_content = "そちに話のあるものがおるようじゃぞ。",
  ui_story_5038_50380501_24_dialog_content = "い、いえ、話などありません…",
  ui_story_5038_50380501_25_dialog_content = "俺もです。殿下、お許しください…",
  ui_story_5038_50380501_26_dialog_content = "…",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>シュッ！</color>",
  ui_story_5038_50380501_28_dialog_content = "せ、せせ船長、お許しください！俺は…",
  ui_story_5038_50380501_29_dialog_content = "後ろよ。",
  ui_story_5038_50380501_30_dialog_content = "え…？",
  ui_story_5038_50380501_31_dialog_content = "グァ…",
  ui_story_5038_50380501_32_dialog_content = "昼ひなかから堂々と船に乗り込んで悪さを働くつもりか？\nなんと無礼な奴らよ。",
  ui_story_5038_50380501_33_dialog_content = "もともとこいつらに礼などないでしょう。",
  ui_story_5038_50380501_34_dialog_content = "2人とも、私の後ろへ。",
  ui_story_5038_50380501_35_dialog_content = "あなたたちにここで死なれては困るわ。",
  ui_story_5038_50380501_36_dialog_content = "は…はい！船長！",
  ui_story_5038_50380602_1_dialog_content = "「鼠尾」、「猴頭」、「兎耳」…",
  ui_story_5038_50380602_2_dialog_content = "サッパリつながりが分からないや。\n名前だけじゃ、何のことだか分からないね。",
  ui_story_5038_50380602_3_dialog_content = "簡単に言えば、それぞれ風見、滑車、木板のことね。",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>風見</color>は帆柱の先端に設置する、\n風の強さや向きを計る道具よ。",
  ui_story_5038_50380602_5_dialog_content = "尾翼にネズミの尾のような縄が結ばれているから、\n「鼠尾」と呼ばれているの。",
  ui_story_5038_50380602_6_dialog_content = "「鼠尾」は軽くて、水に落ちてもすぐに浮かんでくるわね。",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>滑車</color>はそのまま、よくある滑車ね。\n帆の上げ下ろしに使うわ。",
  ui_story_5038_50380602_8_dialog_content = "ちょうどサルの頭くらいの大きさだから、\n「猴頭」と呼ばれているのよ。",
  ui_story_5038_50380602_9_dialog_content = "この2つの代わりが見つかれば、\n帆が使えるようになるわ。",
  ui_story_5038_50380602_10_dialog_content = "へえ、それなら簡単そうだね！",
  ui_story_5038_50380602_11_dialog_content = "じゃあ、最後の「兎耳」は？",
  ui_story_5038_50380602_12_dialog_content = "…これだけは事情が違うわ。\n簡単に代わりは見つからないでしょうね。",
  ui_story_5038_50380602_13_dialog_content = "幸い、蜃風号の「兎耳」に損傷はないわ。\nまずは「鼠尾」と「猴頭」を探しましょう。",
  ui_story_5038_50380602_14_dialog_content = "うん、分かった！",
  ui_story_5038_50380602_15_dialog_content = "PlayerName、タンドウ、キミたちも手伝ってくれるでしょ？",
  ui_story_5038_50380602_16_dialog_content = "もちろん！",
  ui_story_5038_50380602_17_dialog_content = "（何のことやら、さっぱり分からんぞ…！）",
  ui_story_5038_50380602_18_dialog_content = "殿下、ご無理をなさらず。\n済の国ではお屋敷を出ることもほとんどなかったのですから…",
  ui_story_5038_50380602_19_dialog_content = "皆さんの言っていることが分からずとも当然です。",
  ui_story_5038_50380602_20_dialog_content = "…だとしても、何もせんわけにはいかん。",
  ui_story_5038_50380602_21_dialog_content = "お主の方こそ、見ておられぬと言うなら、\n無理に付いてこなくて結構じゃぞ。",
  ui_story_5038_50380602_22_dialog_content = "殿下…",
  ui_story_5038_50380602_23_dialog_content = "う～ん、気難しいお姫様だね～。",
  ui_story_5038_50380602_24_dialog_content = "殿下に対して無礼な物言いは控えていただけますか？",
  ui_story_5038_50380602_25_dialog_content = "はいはい…じゃあPlayerName、ボクたちは先に始めよう。",
  ui_story_5038_50380602_26_dialog_content = "うん、でも…いったいどこへ行けばいいの？\n探すっていっても、どう探すのか、僕には見当もつかないよ。",
  ui_story_5038_50380602_27_dialog_content = "うーん、そうだなぁ…",
  ui_story_5038_50380602_28_dialog_content = "ボクとチビシッポの嗅覚を使えばいいんだ！\n甲板の向こう側に行って、匂いを探ってみよう！",
  ui_story_5038_50380602_29_dialog_content = "ボクたちはネズミの匂いに敏感だからね！",
  ui_story_5038_50380602_30_dialog_content = "そういうことじゃないと思うんだけど…",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>蜃風号、船室内</color>",
  ui_story_5038_50380602_32_dialog_content = "ふむ…",
  ui_story_5038_50380602_33_dialog_content = "（こちらも探してみるか…）",
  ui_story_5038_50380602_34_dialog_content = "殿下、何をお探しで？",
  ui_story_5038_50380602_35_dialog_content = "そなたには関わりの無きことじゃ。",
  ui_story_5038_50380602_36_dialog_content = "つれないですねぇ。\n僕が卦を立てて差し上げましょう。",
  ui_story_5038_50380602_37_dialog_content = "この期に及んでまた人をたばかるつもりか？",
  ui_story_5038_50380602_38_dialog_content = "たばかるつもりかどうかは、\nさっきの話で分かっていただけたと思っていましたがねぇ？",
  ui_story_5038_50380602_39_dialog_content = "フン、まぁよい…少なくとも手練手管は達者ということじゃな。",
  ui_story_5038_50380602_40_dialog_content = "船長の言った「鼠尾」を探しておる。",
  ui_story_5038_50380602_41_dialog_content = "…船の中でですか？",
  ui_story_5038_50380602_42_dialog_content = "そうじゃ。わらわなりに先程の話を聞いて、\n船上にあるものと考えた。",
  ui_story_5038_50380602_43_dialog_content = "船長が話していたであろう？\n「鼠尾」は軽く、水に落ちてもすぐに浮かんでくると。",
  ui_story_5038_50380602_44_dialog_content = "昨日から今まで、\n船方どもがずっと目を巡らせておる…",
  ui_story_5038_50380602_45_dialog_content = "リン家商会で働くほどの者どもであれば、\n海に落ちた針とて見つけられよう。",
  ui_story_5038_50380602_46_dialog_content = "ならば、物は船上にあると考えるほかあるまい。",
  ui_story_5038_50380602_47_dialog_content = "さすが、殿下は聡明でございますねぇ。\n僕もそう思います。",
  ui_story_5038_50380602_48_dialog_content = "となりゃあ、一緒に探して差し上げやしょう。",
  ui_story_5038_50380602_49_dialog_content = "タゲン、タゴ――",
  ui_story_5038_50380602_50_dialog_content = "ワカッタ、ワカッタ。",
  ui_story_5038_50380602_51_dialog_content = "セカスナ、セカスナ。",
  ui_story_5038_50380602_52_dialog_content = "そやつら、話せるのか！？",
  ui_story_5038_50380602_53_dialog_content = "訓練のたまものってやつですねぇ。\nまぁ、人様のマネをしてるだけなんでしょうけど。",
  ui_story_5038_50380602_54_dialog_content = "さあ、タゲン、タゴ。\n「ネズミのしっぽ」をつけた風向計を探すんです。",
  ui_story_5038_50380602_55_dialog_content = "見つけたら、ごほうびをあげますよ。",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>パタパタ…パタパタ…</color>",
  ui_story_5038_50380602_57_dialog_content = "今度は「卦」に頼らぬのか？",
  ui_story_5038_50380602_58_dialog_content = "良禽（りょうきん）は木をえらんで棲むって言いますしねぇ。\nこういう時にゃ、辺りを見下ろせる鳥の方が卦象より役にたちますよ。",
  ui_story_5038_50380602_59_dialog_content = "じゃ、行きましょうか、殿下。\nあいつらの後を追いましょう。",
  ui_story_5038_50380602_60_dialog_content = "ネズミがしっぽを出すかも知れませんからねぇ。",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>ガア――ガア――</color>",
  ui_story_5038_50380602_62_dialog_content = "千年古樹ノナツメ！",
  ui_story_5038_50380602_63_dialog_content = "キラキライイ匂イノウリ！",
  ui_story_5038_50380602_64_dialog_content = "はいはい、ごほうびは後でたっぷりあげますよ。\nで、見つかりましたか？",
  ui_story_5038_50380602_65_dialog_content = "これは…",
  ui_story_5038_50380602_66_dialog_content = "ネズミのしっぽのような形をしておるな。\n船長が「鼠尾」と言った物に違いあるまい。",
  ui_story_5038_50380602_67_dialog_content = "僕にも見せてください…\nへえ！これで間違いなさそうですねぇ。",
  ui_story_5038_50380602_68_dialog_content = "さすがはタゲン、タゴ。\nこんな泥まみれの中からよく見つけましたねぇ。",
  ui_story_5038_50380602_69_dialog_content = "あとで上等なナツメとリュウガン、\nそれからヒマワリの種もあげましょうかねぇ。",
  ui_story_5038_50380602_70_dialog_content = "では、殿下。",
  ui_story_5038_50380602_71_dialog_content = "急いで「鼠尾」を船長に渡すとしましょう。",
  ui_story_5038_50380701_1_dialog_content = "（タンドウが「鼠尾」を見つけて来てから…）",
  ui_story_5038_50380701_2_dialog_content = "（修繕作業は順調に進んでる…帆柱もだいぶ元の姿を取り戻した）",
  ui_story_5038_50380701_3_dialog_content = "（蜃風号の速度もだいぶ上がってきた。\n出発したばかりの頃と変わらないくらいだ）",
  ui_story_5038_50380701_4_dialog_content = "（ただ…）",
  ui_story_5038_50380701_5_dialog_content = "風向きが変わったわ。\n直ちにかいを止め、いかりを下ろす準備を！",
  ui_story_5038_50380701_6_dialog_content = "はい！",
  ui_story_5038_50380701_7_dialog_content = "（ただ、頻繁にいかりを下ろして\n止まらないといけない状況は変わってない）",
  ui_story_5038_50380701_8_dialog_content = "貴公、何やら気がかりがあるようだな？",
  ui_story_5038_50380701_9_dialog_content = "いや、そんなことは…\nむしろ、船長の判断力はすごいなって思ってたところです。",
  ui_story_5038_50380701_10_dialog_content = "隠すことはない。\nそれがしも同じことを考えておる。",
  ui_story_5038_50380701_11_dialog_content = "（見透かされてたのか…）",
  ui_story_5038_50380701_12_dialog_content = "リン家の海図に従い、\n「羅針盤」が失われた場所へ進んではいるが…",
  ui_story_5038_50380701_13_dialog_content = "船の状態は良くない。急場しのぎの修繕で\nかろうじて動いている…というより、無理やり動かしておるにすぎん。",
  ui_story_5038_50380701_14_dialog_content = "航海には綿密さが肝要…\n1つとて手抜かりがあってはならぬのだ。",
  ui_story_5038_50380701_15_dialog_content = "祈りだけで海は渡れぬ。",
  ui_story_5038_50380701_16_dialog_content = "…とは言うものの、\n結局それがしも勝手に気をもんでいるにすぎぬがな。",
  ui_story_5038_50380701_17_dialog_content = "ゆえに、貴公もそう気に病むことはない。",
  ui_story_5038_50380701_18_dialog_content = "はい、僕もちゃんと落ち着くようにします。\nお互い心配しすぎないようにしましょう。",
  ui_story_5038_50380701_19_dialog_content = "蜃風号だって行きは無事にアストラ大陸まで来たんですし、\n僕たちもこんな所で死んだりは…",
  ui_story_5038_50380701_20_dialog_content = "言うな！",
  ui_story_5038_50380701_21_dialog_content = "えっ！？",
  ui_story_5038_50380701_22_dialog_content = "…取り乱した、面目ない。",
  ui_story_5038_50380701_23_dialog_content = "それがしの故郷では、新年を迎えるこの時期、\n口にしてはならん言葉と言うものがあるのだ。",
  ui_story_5038_50380701_24_dialog_content = "ただの風習ではあるが、禁忌には違いないのでな。\n許してくれ。",
  ui_story_5038_50380701_25_dialog_content = "それがしは頭を冷やしてくる。",
  ui_story_5038_50380701_26_dialog_content = "（禁忌…？「死ぬ」って言っちゃいけなかったのかな…）",
  ui_story_5038_50380701_27_dialog_content = "シュウさんがあんなに声を荒げるなんて、\n珍しいね…",
  ui_story_5038_50380701_28_dialog_content = "やっぱり、半年前と同じことが起こるんじゃないかって、\n心配してるんだね。",
  ui_story_5038_50380701_29_dialog_content = "PlayerName、手伝ってもらえる？",
  ui_story_5038_50380701_30_dialog_content = "蜃風号の救命艇を、\nこっそり船べりまで持っていきたいんだ。",
  ui_story_5038_50380701_31_dialog_content = "え？待って…それって<color=#FFB400>盗みだす</color>ってこと？",
  ui_story_5038_50380701_32_dialog_content = "もう、いやだなぁ。\nそんな言い方しないでよ。",
  ui_story_5038_50380701_33_dialog_content = "ほら、見てよ。船長とシュウさんは今、\n浸水や漏水をどう防ぐかって話で忙しいでしょ。",
  ui_story_5038_50380701_34_dialog_content = "邪魔をしたくないだけ。",
  ui_story_5038_50380701_35_dialog_content = "でも、1人で何をするつもり？",
  ui_story_5038_50380701_36_dialog_content = "海に出て「猴頭」を引き上げるんだ。",
  ui_story_5038_50380701_37_dialog_content = "ダメだよ！危険すぎる！",
  ui_story_5038_50380701_38_dialog_content = "まぁまぁ、PlayerName、まずは話を聞いて。\n蜃風号は今、人と同じように「病気」なんだ。",
  ui_story_5038_50380701_39_dialog_content = "病気を治すには、症状に合わせた薬が必要なんだ。\nでも、材料には簡単に手に入るものと…",
  ui_story_5038_50380701_40_dialog_content = "すっごく険しくて危ない場所に生えていて、\nなかなか手に入らないものがあるんだよ。",
  ui_story_5038_50380701_41_dialog_content = "壊れた「猴頭」の代わりになるものは、\n船の上にはないから…",
  ui_story_5038_50380701_42_dialog_content = "病気を治したいなら、海に潜らないといけないってこと。",
  ui_story_5038_50380701_43_dialog_content = "海に潜る？船の上にないのに、\n海の中にある可能性なんてもっと低いんじゃ…",
  ui_story_5038_50380701_44_dialog_content = "気づいてないの？\nこの辺りの海、船の残骸がぽつぽつ浮かんでるでしょ。",
  ui_story_5038_50380701_45_dialog_content = "あれ、この辺で難破した船だよ。",
  ui_story_5038_50380701_46_dialog_content = "他の船の「猴頭」が見つかれば、\nきっと蜃風号の「猴頭」の代わりにできるでしょ。",
  ui_story_5038_50380701_47_dialog_content = "そうすれば、蜃風号は帆を張って航海できるし、\n「兎耳」の心配もしなくて済む！",
  ui_story_5038_50380701_48_dialog_content = "確かにその通りだけど…そんなことできるのかな？",
  ui_story_5038_50380701_49_dialog_content = "こんな広い海の中で、うまく見つかる？",
  ui_story_5038_50380701_50_dialog_content = "ボクが大丈夫って言うんだから、大丈夫だよ。\nPlayerName、なんたってボクは「祟霊」なんだよ！",
  ui_story_5038_50380701_51_dialog_content = "<color=#FFB400>海の中の「友だち」</color>が、\nボクを導いてくれる！",
  ui_story_5038_50380701_52_dialog_content = "本当に？",
  ui_story_5038_50380701_53_dialog_content = "もちろんだよ。\n船に乗るたびに、いつもみんなと話してるんだ。",
  ui_story_5038_50380701_54_dialog_content = "ボクのお願いなら、きっと聞いてくれるよ！",
  ui_story_5038_50380701_55_dialog_content = "「猴頭」を代わりに探してくれるってこと？",
  ui_story_5038_50380701_56_dialog_content = "でも…海の中の友だちは、\n「猴頭」がどんなものか知ってるの？",
  ui_story_5038_50380701_57_dialog_content = "心配いらないよ。ボクが教えてあげればいいだけ。",
  ui_story_5038_50380701_58_dialog_content = "とにかく…手伝って！\n救命艇を運んでくれたら、あとはボク1人で大丈夫だから！",
  ui_story_5038_50380701_59_dialog_content = "やっぱり心配だなぁ…\nじゃあ、僕は君を感知して見失わないようにするよ。",
  ui_story_5038_50380701_60_dialog_content = "何かあったら、すぐに知らせて。",
  ui_story_5038_50380701_61_dialog_content = "分かってるって。いい知らせを待ってて！",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5038_50380701_63_dialog_content = "うわあ――！",
  ui_story_5038_50380701_64_dialog_content = "リンセイ！どうしたの！？",
  ui_story_5038_50380701_65_option_content = "強制感知！",
  ui_story_5038_50380701_66_dialog_content = "（水がいっぱい！\nみ、水…水ばっかりだ！）",
  ui_story_5038_50380701_67_dialog_content = "うう…PlayerName！水に囲まれてる！",
  ui_story_5038_50380701_68_dialog_content = "そりゃそうだよ、海の中なんだから…",
  ui_story_5038_50380701_69_dialog_content = "…待って。もしかして水が怖いの？",
  ui_story_5038_50380701_70_dialog_content = "あ、当たり前でしょ！\nネコが水を怖がっておかしい！？",
  ui_story_5038_50380701_71_dialog_content = "（すごく震えてる…半年前の事件で負った心の傷が治ってないんだ）",
  ui_story_5038_50380701_72_dialog_content = "じゃ、じゃあ急いで上がって！\nそのままじっとしてて。救命艇ごと引き上げるから…",
  ui_story_5038_50380701_73_dialog_content = "よいしょ…っと…",
  ui_story_5038_50380701_74_dialog_content = "うう…",
  ui_story_5038_50380701_75_dialog_content = "無茶しすぎだよ。水が怖いのに潜ろうなんて。",
  ui_story_5038_50380701_76_dialog_content = "1人でも大丈夫だって思ったんだけど…",
  ui_story_5038_50380701_77_dialog_content = "オホン、オホン…PlayerName、\n頼みたいことがもう一つあるんだ。",
  ui_story_5038_50380701_78_dialog_content = "分かってるよ。一緒に海に下りよう。\nそれでいいよね？",
  ui_story_5038_50380701_79_dialog_content = "他の皆は船の修理で手いっぱいだし、\n僕たちも早く「猴頭」を見つけて戻ろう。",
  ui_story_5038_50380701_80_dialog_content = "うん！",
  ui_story_5038_50380701_81_dialog_content = "（海に出る前に、\n船の安全を確かめておかなきゃ…）",
  ui_story_5038_50380701_82_dialog_content = "グアァ！！！",
  ui_story_5038_50380701_83_dialog_content = "うっ…！？",
  ui_story_5038_50380701_84_dialog_content = "こんな短い間に縄をつたって上がってきたの！？",
  ui_story_5038_50380702_1_dialog_content = "みんな、よく聞いてね。\nボクたちはおサルさんの頭くらいの大きさのものを探してるんだ。",
  ui_story_5038_50380702_2_dialog_content = "だいたいこれぐらいの大きさで、\n丸くて、硬いものだよ。",
  ui_story_5038_50380702_3_dialog_content = "それから、もしかしたら縄か何かが巻きついてるかも…",
  ui_story_5038_50380702_X3_dialog_content = "「友だち」って…魚のことだったの？",
  ui_story_5038_50380702_4_dialog_content = "ううっ…はあはあ…",
  ui_story_5038_50380702_5_dialog_content = "リンセイ、どうしたの？\nまた気分が悪くなった？",
  ui_story_5038_50380702_6_dialog_content = "卜子いわく、「医者、自らを医することあたわず」…\n今のボクみたいな状況を言ってるんだろうね。",
  ui_story_5038_50380702_7_dialog_content = "どうすれば落ち着ける？",
  ui_story_5038_50380702_8_dialog_content = "そうだなぁ、あごの下をなでてもらえると――",
  ui_story_5038_50380702_9_dialog_content = "いやいや！！オホン！\nあごの下をなでられて喜ぶのは、チビシッポぐらいだよ！",
  ui_story_5038_50380702_10_dialog_content = "ボクは人間に化けられもしない、ただのネコじゃないんだ！\nそんなの必要ないもんね！",
  ui_story_5038_50380702_11_dialog_content = "（意地を張るところが妙に可愛らしい…）",
  ui_story_5038_50380702_12_dialog_content = "そういえば、PlayerNameの故郷って、\n「祟霊」はいないんだよね？",
  ui_story_5038_50380702_13_dialog_content = "うーん…亜人族の血を引く光霊の友だちはいるよ。",
  ui_story_5038_50380702_14_dialog_content = "ほとんどが亜人族と光霊の末裔なんだ。\nアストラ大陸でも数は少ない方だけどね。",
  ui_story_5038_50380702_15_dialog_content = "ふ～ん。\nでも、やっぱり「祟霊」とは違うみたいだね。",
  ui_story_5038_50380702_16_dialog_content = "PlayerNameにはもう言ったっけ？\nチビシッポって、実はボクの兄さんなんだ。",
  ui_story_5038_50380702_17_dialog_content = "お兄さん？",
  ui_story_5038_50380702_18_dialog_content = "そういえば、テンカンがずっと君のことを「ネコ坊」って呼んでたね。\nそれってやっぱり、君がネコだから？",
  ui_story_5038_50380702_19_dialog_content = "あんな呼び方、失礼しちゃうよね！",
  ui_story_5038_50380702_20_dialog_content = "でもまあ、その通りだよ。龍州で「祟霊」って呼ばれてるのは、\n修練を積んで光霊になった動物のことなんだ。",
  ui_story_5038_50380702_21_dialog_content = "龍州で権勢があって、和を重んじる一族は、\n「祟霊」を屋敷に招いて居そうろうさせてることが多いんだ。",
  ui_story_5038_50380702_22_dialog_content = "そういう祟霊は「食客」なんて呼んだりもするね。",
  ui_story_5038_50380702_23_dialog_content = "で、ボクも食客として、\nリン家の当主と知り合ったんだよ。",
  ui_story_5038_50380702_24_dialog_content = "聞いた限り、当主は情を重んじる人みたいだね。",
  ui_story_5038_50380702_25_dialog_content = "実を言うとね…リン家の人たちが話してる商いのことは、\nボクにはまったく理解できないんだ。",
  ui_story_5038_50380702_26_dialog_content = "ボクが屋敷に招かれたのは、\n<color=#FFB400>お魚の面倒</color>を見て欲しいからってだけ。",
  ui_story_5038_50380702_27_dialog_content = "お魚はネコの大好物ってよく言われてるけど、\n海の中のお魚は、ボクの友だちなんだよ。",
  ui_story_5038_50380702_28_dialog_content = "だから、君はミズチウオとも話ができるってこと？",
  ui_story_5038_50380702_29_dialog_content = "そういうこと。\nでも、あの夜の事件では、何の助けにもなれなかった…",
  ui_story_5038_50380702_30_dialog_content = "あ、海の中の「友だち」が答えてくれた！",
  ui_story_5038_50380702_31_dialog_content = "「猴頭」がこのすぐ下にあるって。",
  ui_story_5038_50380702_32_dialog_content = "本当に？",
  ui_story_5038_50380702_33_dialog_content = "ええと…たぶん、海藻がからみついてるのかな。",
  ui_story_5038_50380702_34_dialog_content = "ちょっと待ってて。\n漁網を使って、引き上げよう…",
  ui_story_5038_50380702_35_dialog_content = "よいしょ！",
  ui_story_5038_50380702_36_dialog_content = "ほら見て、PlayerName！",
  ui_story_5038_50380702_37_dialog_content = "す、すごい！",
  ui_story_5038_50380702_38_dialog_content = "まるで魔法みたいだね。",
  ui_story_5038_50380702_39_dialog_content = "言ったでしょ。\n海の友だちが助けてくれるって。",
  ui_story_5038_50380702_40_dialog_content = "この「猴頭」があれば、船の修理も進むよ！",
  ui_story_5038_50380702_41_dialog_content = "そうだね。じゃあ、今すぐ戻ろう！",
  ui_story_5038_50380702_42_dialog_content = "船の皆もきっと喜ぶよ！",
  ui_story_5038_50380702_43_dialog_content = "うん！",
  ui_story_5038_50380702_44_dialog_content = "（羅針盤、大丈夫かな…）",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>蜃風号、甲板</color>",
  ui_story_5038_50380702_46_dialog_content = "おや…リンセイとPlayerNameが戻ったようじゃな。",
  ui_story_5038_50380702_47_dialog_content = "それがしが申したであろう、2人とも無事に違いないと。",
  ui_story_5038_50380702_48_dialog_content = "ふ…そういう割には、箸が止まっておったな。",
  ui_story_5038_50380702_49_dialog_content = "PlayerName、リンセイ、無茶をしすぎよ！",
  ui_story_5038_50380702_50_dialog_content = "海に出る前に、最悪の事態を考えなかったの？",
  ui_story_5038_50380702_51_dialog_content = "船長、見て！",
  ui_story_5038_50380702_52_dialog_content = "…！",
  ui_story_5038_50380702_53_dialog_content = "これは…「猴頭」！？",
  ui_story_5038_50380702_54_dialog_content = "海水に長く浸かっていたのでしょうけど、\nすこし手入れすれば、まだ使えるわ。",
  ui_story_5038_50380702_55_dialog_content = "どこで見つけたの？",
  ui_story_5038_50380702_56_dialog_content = "海の中だよ！",
  ui_story_5038_50380702_57_dialog_content = "潜ったの？",
  ui_story_5038_50380702_58_dialog_content = "危険だと分かっていたでしょう。今は全員手いっぱいだから、\n万が一があっても、助けられるか分からないのよ。",
  ui_story_5038_50380702_59_dialog_content = "でも、ボクたち2人ともピンピンしてるでしょ！\n万が一なんて起こってない！",
  ui_story_5038_50380702_60_dialog_content = "アハハ、だいぶ無茶をしちゃったけど、\n結果は上々だったね。",
  ui_story_5038_50380702_61_dialog_content = "もともと今回の航海は危険だって。\n船長も言ってたでしょ。",
  ui_story_5038_50380702_62_dialog_content = "リンセイのおかげで、新しい「猴頭」が見つかったんだ！\nここはほめてあげようよ！",
  ui_story_5038_50380702_63_dialog_content = "あなたたちという人は…",
  ui_story_5038_50380702_64_dialog_content = "そうね…「猴頭」が見つかったことで船の修繕が大きく進むのは確か。\nありがとう。",
  ui_story_5038_50380702_65_dialog_content = "ただし、勝手に船を下りるような危険なまねは、\n今後一切しないでちょうだい。",
  ui_story_5038_50380702_66_dialog_content = "分かったら、早く食事をして来るといいわ。",
  ui_story_5038_50380702_67_dialog_content = "そうじゃそうじゃ、早う来んか！",
  ui_story_5038_50380702_68_dialog_content = "お主らが部品を探す間に、\nキュウが龍州の料理をこしらえておるぞ。",
  ui_story_5038_50380702_69_dialog_content = "わあ、ちょうどお腹が空いてたんだ！",
  ui_story_5038_50380702_70_dialog_content = "いい匂い！もしかして紅焼肉（ホンショウロウ）？",
  ui_story_5038_50380702_71_dialog_content = "よく利く鼻じゃな。\nその通りじゃ、今日の昼餉の主菜は――<color=#FFB400>紅焼肉</color>ぞ！",
  ui_story_5038_50380702_72_dialog_content = "肉の塊をひもでくくり、\n様々な香料と合わせてじっくりと煮込んだものじゃ…",
  ui_story_5038_50380702_73_dialog_content = "船の上では揃う材料にも限りはあるが、\n龍州で食べるものに劣らぬ味に仕上がっておる。",
  ui_story_5038_50380702_74_dialog_content = "皆さんは先に食べていて。\n私はまだ修繕作業が残っているから、後にするわ。",
  ui_story_5038_50380702_75_dialog_content = "新しい「猴頭」があれば、\n帆柱の修繕はすぐに終わるはずよ。",
  ui_story_5038_50380702_76_dialog_content = "そうすれば、蜃風号も本来の速さで航行できるわ。",
  ui_story_5038_50380702_77_dialog_content = "僕も手伝うよ！",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>グゥ…</color>",
  ui_story_5038_50380702_79_dialog_content = "ふふ…まずは食べた方がよさそうね？",
  ui_story_5038_50380702_80_dialog_content = "それに、空腹のお客様に手伝わせるなんて、\nリン家のおもてなしとしてあり得ないわ。",
  ui_story_5038_50380801_1_dialog_content = "（船の速度は戻ったけど、\n船体の損傷を考えると安心はできない）",
  ui_story_5038_50380801_2_dialog_content = "（皆、ひと時も休まず動いてる。\nちょっとでも手を止めたら、蜃風号が沈没するとでも言うみたいに…）",
  ui_story_5038_50380801_3_dialog_content = "（いや、むしろ、くたくたに疲れて不安を忘れようとしてるんだ）",
  ui_story_5038_50380801_4_dialog_content = "帆を少し左に回して。\n風向きが変わったわ。",
  ui_story_5038_50380801_5_dialog_content = "はい！",
  ui_story_5038_50380801_6_dialog_content = "貨物庫の状況は？",
  ui_story_5038_50380801_7_dialog_content = "浸水が止まりません。\n人手を送り続けて、外にかき出すしかありません。",
  ui_story_5038_50380801_8_dialog_content = "幸い、浸水の悪化は見られていないので、\n現在のところ、対応は間に合っています。",
  ui_story_5038_50380801_9_dialog_content = "分かったわ。交代制にして、\n全員しっかり休ませるようにしなさい。",
  ui_story_5038_50380801_10_dialog_content = "この状況があとどのぐらい続くかが分からないわ。\n力は温存しておかないと。",
  ui_story_5038_50380801_11_dialog_content = "はい！",
  ui_story_5038_50380801_12_dialog_content = "針路がズレていないといいけれど。\nもう一度船首で確認しておきましょう…",
  ui_story_5038_50380801_13_dialog_content = "（ユエは船長としてずっと働き続けてる。\n話す時でさえ足を止めてない）",
  ui_story_5038_50380801_14_dialog_content = "（一番色々考えなきゃいけない立場にいるから、\nそれだけプレッシャーも大きくて、不安も具体的に見えてるんだ）",
  ui_story_5038_50380801_15_dialog_content = "（蜃風号は満身創痍だけど、\n彼女のおかげで何とかなってる）",
  ui_story_5038_50380801_16_dialog_content = "またか…",
  ui_story_5038_50380801_17_dialog_content = "キュウ、これでいくつじゃ？",
  ui_story_5038_50380801_18_dialog_content = "42です、殿下。",
  ui_story_5038_50380801_19_dialog_content = "やはり多い…",
  ui_story_5038_50380801_20_dialog_content = "船の向かう先から流れて来るとなると…気がかりじゃな。",
  ui_story_5038_50380801_21_dialog_content = "（今朝になって、海面に木材がたくさん浮かんでいる）",
  ui_story_5038_50380801_22_dialog_content = "（昨日見つけた猴頭は氷山の一角に過ぎなかったんだ。\nこの辺りには、かつて難破した無数の船の残骸がある…）",
  ui_story_5038_50380801_23_dialog_content = "（タンドウは休憩する時、船べりに立って、\n海面の浮き木を数えてる）",
  ui_story_5038_50380801_24_dialog_content = "（海を漂うだけになった残骸にとっては、\nそれが唯一、誰かの気にかけてもらえる時間だろう…）",
  ui_story_5038_50380801_25_dialog_content = "何も心配することなんてないよ。\nボクはむしろ、いいことだと思うよ？",
  ui_story_5038_50380801_26_dialog_content = "この先で船が事故に遭ってるってことは、\n針路は間違ってないってことだもん。",
  ui_story_5038_50380801_27_dialog_content = "周りに何もない方が怖いんじゃない？",
  ui_story_5038_50380801_28_dialog_content = "（リンセイが煮干しをくわえながら近づいてきた）",
  ui_story_5038_50380801_29_dialog_content = "（ずっと忙しそうに何かを手伝ってるけど、\nどこか心ここにあらずって感じがする…）",
  ui_story_5038_50380801_30_dialog_content = "（もしかしたら、そうしてないと\n時間の流れに耐えられないのかも）",
  ui_story_5038_50380801_31_dialog_content = "いや～、こりゃあ疲れますねぇ。",
  ui_story_5038_50380801_32_dialog_content = "貨物庫内の水ときたら、\nいくら汲み出しても、きりがありませんよ。",
  ui_story_5038_50380801_33_dialog_content = "おや、PlayerNameの旦那もこちらでしたか。",
  ui_story_5038_50380801_34_dialog_content = "うん、少し休んでていいって言われたんだ。",
  ui_story_5038_50380801_35_dialog_content = "（テンカンは相変わらずだ。\nどんな時でもよくしゃべる）",
  ui_story_5038_50380801_36_dialog_content = "そりゃあ、そうですねぇ。\nくたびれて病気にでもなったらたまりませんから。",
  ui_story_5038_50380801_37_dialog_content = "水を全部汲み出したところで、\n明日もまた入ってきますからねぇ。",
  ui_story_5038_50380801_38_dialog_content = "航海ってのは、海より大きく、\nゆったり構えなきゃあいけません。",
  ui_story_5038_50380801_39_dialog_content = "君はいつでも、もっともらしいことを言うね。",
  ui_story_5038_50380801_40_dialog_content = "当然ですよ。僕は自分に平常心を保つように\n言い聞かせてるんです。まだ先が長いですからねぇ。",
  ui_story_5038_50380801_41_dialog_content = "少なくとも、あの車いすに乗った旦那がまだ駆り出されてないなら、\n最悪の状況じゃないって事でしょうしねぇ。",
  ui_story_5038_50380801_42_dialog_content = "それがしに言いたいことがあるようだな？",
  ui_story_5038_50380801_43_dialog_content = "おやおや、これはこれは！\nシュウの旦那！",
  ui_story_5038_50380801_44_dialog_content = "風にでも当たりに？\n甲板の上は気持ちいい風が吹いていますからねぇ！",
  ui_story_5038_50380801_45_dialog_content = "持ち上げようとせんでいい。\n陸の上でも大した権勢は持っておらん。船の上ではなおさらだ。",
  ui_story_5038_50380801_46_dialog_content = "そりゃあ謙そんが過ぎるってもんですよ。老虎は爪牙を失してなお三分の威風あり。\nそれがかの平野大将軍なら、なおのことってやつですねえ。",
  ui_story_5038_50380801_47_dialog_content = "分かった分かった、\n口では勝てぬ、お主の好きにせい。",
  ui_story_5038_50380801_48_dialog_content = "実は、状況を解決できるやもしれぬ策があるのだが…",
  ui_story_5038_50380801_49_dialog_content = "やるとなれば、貴公らの力が必要となる。",
  ui_story_5038_50380801_50_dialog_content = "本当に！？どんな策ですか？",
  ui_story_5038_50380801_51_dialog_content = "喜んで手伝います！",
  ui_story_5038_50380801_52_dialog_content = "旦那の策と言うなら、\n僕も喜んで力を貸しましょう。",
  ui_story_5038_50380801_53_dialog_content = "大して難しいことではない。\nいくつか浮き木を引き上げて欲しいのだ。",
  ui_story_5038_50380801_54_dialog_content = "浮き木を？",
  ui_story_5038_50380801_55_dialog_content = "それなら簡単そうだね。\n魚とりの網で引き上げられそう。",
  ui_story_5038_50380801_56_dialog_content = "構いませんよ、ちょうど目の前の海に、\nたっぷり浮いてますからねぇ。",
  ui_story_5038_50380801_57_dialog_content = "ただ、どれでもいいという訳ではない。\nそれがしの言うものを引き上げてもらいたい。",
  ui_story_5038_50380801_58_dialog_content = "何か違いがあるんですか？",
  ui_story_5038_50380801_59_dialog_content = "旦那の策ですからねぇ。\nこの場はひとまず、言う通りにしましょう。",
  ui_story_5038_50380801_60_dialog_content = "網を借りてきますよ。",
  ui_story_5038_50380801_61_dialog_content = "よいしょ…よいしょ…",
  ui_story_5038_50380801_62_dialog_content = "よし、あと一息ですよ！",
  ui_story_5038_50380801_63_dialog_content = "えいっ――！",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>ガラガラガラ――</color>",
  ui_story_5038_50380801_65_dialog_content = "ふぅ、やった！",
  ui_story_5038_50380801_66_dialog_content = "何が「やった」なの？",
  ui_story_5038_50380801_67_dialog_content = "お魚が全然捕まってないじゃない！\nボロボロの板なんて引き上げて「やった」も何もある？",
  ui_story_5038_50380801_68_dialog_content = "リンセイ？いや、違うんだ。僕たちは…",
  ui_story_5038_50380801_69_dialog_content = "それがしが板を引き上げるよう頼んだのだ。",
  ui_story_5038_50380801_70_dialog_content = "ふ～ん？…へんなの。\nそんなもの引き上げてどうするの？",
  ui_story_5038_50380801_71_dialog_content = "引き上げた板をよく見るがいい。\nただの板ではないぞ。",
  ui_story_5038_50380801_72_dialog_content = "おそらく船体に付いていた時には、\n「兎耳」と呼ばれていたものであろう。",
  ui_story_5038_50380801_73_dialog_content = "おお、確かにウサギの耳のような形じゃな。",
  ui_story_5038_50380801_74_dialog_content = "やっぱり、僕と同じ考えだったってわけですか。",
  ui_story_5038_50380801_75_dialog_content = "「兎耳」は出た卦の最後の1つでしたからねぇ。",
  ui_story_5038_50380801_76_dialog_content = "何に使うものじゃ？",
  ui_story_5038_50380801_77_dialog_content = "舷の外側に取り付ける横舵だ。\n通常は1隻に2つ付いている。",
  ui_story_5038_50380801_78_dialog_content = "船の他の部分よりも精巧に加工され、\n水がしみ込まないようになっている部分だ。",
  ui_story_5038_50380801_79_dialog_content = "ゆえに、引き上げてもらった。",
  ui_story_5038_50380801_80_dialog_content = "つまり…防水性が目当てってことですねぇ？",
  ui_story_5038_50380801_81_dialog_content = "さよう。",
  ui_story_5038_50380801_82_dialog_content = "「防水」とは、水のあるべきでないところに、\n水を寄せ付けないことだ。",
  ui_story_5038_50380801_83_dialog_content = "水のあるべきでないところ…",
  ui_story_5038_50380801_84_dialog_content = "あ、分かった！\n船底にある貨物庫のことですね！",
  ui_story_5038_50380801_85_dialog_content = "その木材を使って、浸水を止めようってことですね！",
  ui_story_5038_50380801_86_dialog_content = "貴公は頭の回転が速いようだな。",
  ui_story_5038_50380801_87_dialog_content = "「兎耳」で船底の浸水を塞ぎ、\n釘でしっかりと打ち付けるのだ。",
  ui_story_5038_50380801_88_dialog_content = "急場しのぎではあるが、わずかでも負担は減らせるであろう。\nさすれば、皆も水のくみ出しで忙しくする必要もなくなる。",
  ui_story_5038_50380801_89_dialog_content = "名案ですねぇ。\n「兎耳」を接ぎ木代わりに使おうということですか。",
  ui_story_5038_50380801_90_dialog_content = "兎の卦の意味が分かりましたよ。",
  ui_story_5038_50380801_91_dialog_content = "良さそうな考えですね！",
  ui_story_5038_50380801_92_dialog_content = "浸水の心配が無くなれば、\n他の作業に回せる人も増えます。",
  ui_story_5038_50380801_93_dialog_content = "急いであと何枚か引き上げよう！",
  ui_story_5038_50380801_94_dialog_content = "見つけましたよ、PlayerNameの旦那。",
  ui_story_5038_50380801_95_dialog_content = "あれも「兎耳」ですねぇ。",
  ui_story_5038_50380801_96_dialog_content = "さあ、早いとこ網を！",
  ui_story_5038_50380801_97_dialog_content = "また水位が上がってきてる！？",
  ui_story_5038_50380801_98_dialog_content = "ああ、まったく目が離せないな…",
  ui_story_5038_50380801_99_dialog_content = "こうしちゃいられん。さっさとくみ出すぞ。",
  ui_story_5038_50380801_100_dialog_content = "そ、そうね。分かったわ…",
  ui_story_5038_50380801_101_dialog_content = "ねえ、誰か手伝ってくれない？",
  ui_story_5038_50380801_102_dialog_content = "リンセイの声だわ？",
  ui_story_5038_50380801_103_dialog_content = "早く受け取って！\nもう担いでられないよ！",
  ui_story_5038_50380801_104_dialog_content = "今行くけど、いったい何を…",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>ガラガラガラ――</color>",
  ui_story_5038_50380801_106_dialog_content = "え！？",
  ui_story_5038_50380801_107_dialog_content = "あー、重かったぁ。",
  ui_story_5038_50380801_108_dialog_content = "でも、ここまで運んでくれば、\nボクの仕事は終わりだね。",
  ui_story_5038_50380801_109_dialog_content = "リンセイ、どうしてこんなものを？",
  ui_story_5038_50380801_110_dialog_content = "まったく、シュウさんのせいだよ。\nこんな重労働をボクにやらせるなんて。",
  ui_story_5038_50380801_111_dialog_content = "シュウさんがね、\nこの板で浸水してる場所を塞げって。",
  ui_story_5038_50380801_112_dialog_content = "板だって！？海から拾ってきたのか？",
  ui_story_5038_50380801_113_dialog_content = "そんなもん、水を吸って腐っちまってるだろ。\n使い物にならんと思うが…",
  ui_story_5038_50380801_114_dialog_content = "腐ってはいないよ。すっごく重かったけど。",
  ui_story_5038_50380801_115_dialog_content = "触ってみれば？",
  ui_story_5038_50380801_116_dialog_content = "板一枚運べないなんて、お前が貧弱なだけだろ…",
  ui_story_5038_50380801_117_dialog_content = "どれどれ――",
  ui_story_5038_50380801_118_dialog_content = "ん…これ、「兎耳」じゃないか？",
  ui_story_5038_50380801_119_dialog_content = "どう、分かったでしょ？",
  ui_story_5038_50380801_120_dialog_content = "…そうか、こいつなら確かに使えるかもしれないな。",
  ui_story_5038_50380801_121_dialog_content = "金槌はどこだ？持って来てくれ！",
  ui_story_5038_50380801_122_dialog_content = "3、2、1――",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>ガラガラガラ――</color>",
  ui_story_5038_50380801_124_dialog_content = "うむ、また1枚じゃ！",
  ui_story_5038_50380801_125_dialog_content = "ふぅ…造作もないですねぇ。",
  ui_story_5038_50380801_126_dialog_content = "ぞ、造作もない…？待って、少し休ませて…",
  ui_story_5038_50380801_127_dialog_content = "あなたたち、何をしているの？",
  ui_story_5038_50380801_128_dialog_content = "船長！ご覧の通りですよ。\n海に浮かんでる板を引き上げてるんです。",
  ui_story_5038_50380801_129_dialog_content = "シュウの旦那が沈んでる船の「兎耳」を使えば、\n浸水を止められるかも知れないとおっしゃったのでねぇ。",
  ui_story_5038_50380801_130_dialog_content = "「兎耳」…",
  ui_story_5038_50380801_131_dialog_content = "やったよ！浸水してたところ、\nほんとに「兎耳」でふさげた！",
  ui_story_5038_50380801_132_dialog_content = "リンセイ！うまく行ったんだね、良かった！",
  ui_story_5038_50380801_133_dialog_content = "うん、さっき運んだ「兎耳」で浸水を1か所塞げたんだ。",
  ui_story_5038_50380801_134_dialog_content = "でも、まだいっぱい浸水してるところがあるから、\nもっとたくさん「兎耳」が必要だって。",
  ui_story_5038_50380801_135_dialog_content = "だから、手を止めちゃだめだよ！\nもっとたくさん引き上げなきゃ！",
  ui_story_5038_50380801_136_dialog_content = "分かったよ。今すぐ…",
  ui_story_5038_50380801_137_dialog_content = "お客様の手を煩わすわけにはいかないわ。\nあちらで休んでいて。",
  ui_story_5038_50380801_138_dialog_content = "そうと分かったら、後は船方の仕事よ。",
  ui_story_5038_50380801_139_dialog_content = "お客様をヘトヘトにさせるなんて、\n蜃風号のおもてなしにそぐわないもの。",
  ui_story_5038_50380801_140_dialog_content = "さあ、いくぞ！",
  ui_story_5038_50380801_141_dialog_content = "よいっ――しょ！",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>ガラガラガラ――</color>",
  ui_story_5038_50380801_143_dialog_content = "こっちにも1枚あったわ！",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>ガラガラガラ――</color>",
  ui_story_5038_50380801_145_dialog_content = "さあ、急いで運ぶぞ！",
  ui_story_5038_50380801_146_dialog_content = "釘が足りない、もう少し持ってきてくれ！",
  ui_story_5038_50380801_147_dialog_content = "そう急ぐな、一個ずつだ！",
  ui_story_5038_50380801_148_dialog_content = "皆が手伝ってくれたおかげで、\nだいぶ効率が上がったね。",
  ui_story_5038_50380801_149_dialog_content = "もう何枚「兎耳」を引き上げたか、\n思いだせないぐらいだよ。",
  ui_story_5038_50380801_150_dialog_content = "この調子なら、今日中に船底の穴を塞げそうですねぇ！",
  ui_story_5038_50380801_151_dialog_content = "あら、この「兎耳」…",
  ui_story_5038_50380801_152_dialog_content = "ねえ、ちょっと見て。",
  ui_story_5038_50380801_153_dialog_content = "どうした？何か問題でもあるのか？",
  ui_story_5038_50380801_154_dialog_content = "いいえ、でも、どこか見覚えがある気がして…",
  ui_story_5038_50380801_155_dialog_content = "ああ！？確かに見覚えがあるぞ！",
  ui_story_5038_50380801_156_dialog_content = "こいつはリク兄貴の船のじゃねぇか！",
  ui_story_5038_50380801_157_dialog_content = "ええ…この春、遠くまで漁に行くって海に出たきり、\nずっと便りがなかったけど…",
  ui_story_5038_50380801_158_dialog_content = "まさか、こんなところで…",
  ui_story_5038_50380801_159_dialog_content = "え？…事故にあった船のことが分かるの？",
  ui_story_5038_50380801_160_dialog_content = "うむ…",
  ui_story_5038_50380801_161_dialog_content = "板きれ1枚で見分けがつくんですか…？",
  ui_story_5038_50380801_162_dialog_content = "「兎耳」は特別な部品でな。",
  ui_story_5038_50380801_163_dialog_content = "どの船にもたった2つしかなく、\n目立つ位置にある。",
  ui_story_5038_50380801_164_dialog_content = "ゆえに、船主は己の好みで文様を刻む。\nそれが船の顔となるのだ。",
  ui_story_5038_50380801_165_dialog_content = "なるほど…",
  ui_story_5038_50380801_166_dialog_content = "龍州の船人の間では、よく知られたことだ。",
  ui_story_5038_50380801_167_dialog_content = "船長殿も「兎耳」をしばらく眺めておった様子…",
  ui_story_5038_50380801_168_dialog_content = "おそらく、他の者より多く見知った兎耳があるのであろうな。",
  ui_story_5038_50380801_169_dialog_content = "ええ…",
  ui_story_5038_50380801_170_dialog_content = "何隻かの船が夏に出航して嵐に遭い、\nそのまま港に戻って来ませんでした。",
  ui_story_5038_50380801_171_dialog_content = "ことに客船の「兎耳」はきらびやかに装飾されていますから、\n一目で分かります。",
  ui_story_5038_50380801_172_dialog_content = "漁船は少ないみたいですね。\n漁師は遠海に出ることの怖さをよく知っているから…",
  ui_story_5038_50380801_173_dialog_content = "でも、今年は不漁だったので、\n危険を承知で遠海に出た者もいました。",
  ui_story_5038_50380801_174_dialog_content = "一番多いのは商船ですね。",
  ui_story_5038_50380801_175_dialog_content = "遠方の大陸で利益を掴もうと、\n先代の蜃風号に付いて出航した商船は少なくありません。",
  ui_story_5038_50380801_176_dialog_content = "でも、今日まで無事に大陸の間を往復できた商船は、蜃風号だけ…",
  ui_story_5038_50380801_177_dialog_content = "そうだったんだ…",
  ui_story_5038_50380801_178_dialog_content = "今ようやく、自分たちの引き上げた\nものの重さが分かった気がする…",
  ui_story_5038_50380801_179_dialog_content = "1隻の船に「兎耳」はたった2つ。",
  ui_story_5038_50380801_180_dialog_content = "つまり、「兎耳」を2枚引き上げることは、\n沈んだ船1隻の証を引き上げたと言うことだ。",
  ui_story_5038_50380801_181_dialog_content = "見分けのつくものであれば、\n誰ぞの記憶を呼び起こし…",
  ui_story_5038_50380801_182_dialog_content = "見分けのつかないものは、\n静かに数となって積みあがる。",
  ui_story_5038_50380801_183_dialog_content = "僕たちが引き上げた「兎耳」、\nもう相当な数になってますね…",
  ui_story_5038_50380801_184_dialog_content = "航海とはそもそも、そういうものよ。",
  ui_story_5038_50380801_185_dialog_content = "大海原に寄りどころはない。\nだから、前人が後に続く者のよりどころになるの。",
  ui_story_5038_50380801_186_dialog_content = "船底ももうすぐ塞がるわ。",
  ui_story_5038_50380801_187_dialog_content = "これは商船、こやつは漁船、これも商船じゃな…",
  ui_story_5038_50380801_188_dialog_content = "それから、これも商船…\nこれもまた商船…",
  ui_story_5038_50380801_189_dialog_content = "タンドウ、何してるの？",
  ui_story_5038_50380801_190_dialog_content = "引き上げた「兎耳」の由緒を確かめておる。",
  ui_story_5038_50380801_191_dialog_content = "船長が言ったことじゃ。\n龍州に戻った時、少なくとも行方知れずの船の記録に始末をつけてやれるとな。",
  ui_story_5038_50380801_192_dialog_content = "なるほど…",
  ui_story_5038_50380801_193_dialog_content = "貨物庫に運んだものは見終わった。\n新しく引き上げたものは他にあるか？",
  ui_story_5038_50380801_194_dialog_content = "もうないよ。\n船の残骸が散らばってる海域も抜けちゃったみたいだしね。",
  ui_story_5038_50380801_195_dialog_content = "それに、もう十分足りてるみたいだから。",
  ui_story_5038_50380801_196_dialog_content = "船底の修繕はもうすぐ終わりそうだし、\n皆、最後の作業に入ってるよ。",
  ui_story_5038_50380801_197_dialog_content = "そうか、それは重畳。\nわらわもそろそろ切り上げられそうじゃ。",
  ui_story_5038_50380801_198_dialog_content = "じゃが、口惜しいのう。\n何の手がかりも見つからんとは…",
  ui_story_5038_50380801_199_dialog_content = "手がかり？",
  ui_story_5038_50380801_200_dialog_content = "もともとは「羅針盤」の手がかりを探そうと思っておったのじゃ…",
  ui_story_5038_50380801_201_dialog_content = "蜃風号に付いて出航した船の「兎耳」も多くあったからの。",
  ui_story_5038_50380801_202_dialog_content = "同じように海で難に遭うたなら、\n先代の蜃風号の「兎耳」も見つかるのではないかと思ったのじゃが。",
  ui_story_5038_50380801_203_dialog_content = "今にしてみれば、安易に考えすぎたようじゃな。",
  ui_story_5038_50380801_204_dialog_content = "言われてみると、僕もその通りだと思うよ。\n前の蜃風号の手がかりが、沈没船の残骸の中にあるかもしれない。",
  ui_story_5038_50380801_205_dialog_content = "「羅針盤」は大事な物なんだし、\nもっと詳しく探してみた方がいいかもしれないね。",
  ui_story_5038_50380801_206_dialog_content = "船長に伝えた方がよいじゃろうか…？",
  ui_story_5038_50380801_207_dialog_content = "うーん、でも…シュウさんは「兎耳」を見ても、\nまったく気にする様子が無かった。",
  ui_story_5038_50380801_208_dialog_content = "…ってことは、僕たちが引き上げたものの中にはないって、\n確信があるのかも。",
  ui_story_5038_50380801_209_dialog_content = "ない事を確信している？\nそんなことが起こり得るかのう？",
  ui_story_5038_50380801_210_dialog_content = "そうだなぁ…たとえば、前の蜃風号の「兎耳」は特別な形をしていて、\n遠くから見てもすぐに分かる、とか？",
  ui_story_5038_50380801_211_dialog_content = "それはあり得ぬ話じゃ。",
  ui_story_5038_50380801_212_dialog_content = "百里も向こうまで見渡せる広大な海の上じゃぞ？\n全てを一目で見分けられる者などおらん。",
  ui_story_5038_50380801_213_dialog_content = "うーん、そうか…だったら、前の蜃風号には\n「兎耳」がなかったってことは…",
  ui_story_5038_50380801_214_dialog_content = "いや、それもないか…特殊な船だったとしても、\n他の部位の残骸はあるはずだし…",
  ui_story_5038_50380801_215_dialog_content = "でも、シュウさんは確かに残骸には\n何の興味も示してなかった…",
  ui_story_5038_50380801_216_dialog_content = "まさか…",
  ui_story_5038_50380801_217_dialog_content = "そんなの当然の話だよ。",
  ui_story_5038_50380801_218_dialog_content = "だって、残骸になってないもん。",
  ui_story_5038_50380801_219_dialog_content = "リンセイ、いつから居った？",
  ui_story_5038_50380801_220_dialog_content = "残骸になってない…？",
  ui_story_5038_50380801_221_dialog_content = "行方不明と沈没は同じことじゃないよ。",
  ui_story_5038_50380801_222_dialog_content = "考えてもみてよ。航海が絶対安全になる「羅針盤」があるんだよ？\n沈むはずないでしょ？",
  ui_story_5038_50380801_223_dialog_content = "そんなにすごい力があるの？",
  ui_story_5038_50380801_224_dialog_content = "当然だよ。でなきゃ、\n血眼で奪おうなんてヤツ出ないでしょ。",
  ui_story_5038_50380801_225_dialog_content = "ま、その話は置いておいて…",
  ui_story_5038_50380801_226_dialog_content = "もうすぐご飯だよ。みんな待ってるから。",
  ui_story_5038_50380801_227_dialog_content = "早く来てね。",
  ui_story_5038_50380801_228_dialog_content = "皆の衆が？揃っておるのか？",
  ui_story_5038_50380801_229_dialog_content = "そうだよ、修繕作業が終わったから、\nやっとみんなで一緒に休憩できるんだ。",
  ui_story_5038_50380801_230_dialog_content = "だから、皆をガッカリさせないでよね。\nシュウさんだってもう席に着いてるんだよ？",
  ui_story_5038_50380801_231_dialog_content = "さ、急いで急いで！",
  ui_story_5038_50380801_232_dialog_content = "おやおや、やっと来ましたか！",
  ui_story_5038_50380801_233_dialog_content = "料理がそろったところに出て来るなんて、\nさては匂いに誘われてきたな？",
  ui_story_5038_50380801_234_dialog_content = "さあ、座った、座った！",
  ui_story_5038_50380801_235_dialog_content = "わぁ、にぎやかだね！",
  ui_story_5038_50380801_236_dialog_content = "ふむ、よい香りじゃ！",
  ui_story_5038_50380801_237_dialog_content = "当然ですよ。厨房の者が腕をふるったんです！",
  ui_story_5038_50380801_238_dialog_content = "なんたって「祝宴」ですから。",
  ui_story_5038_50380801_239_dialog_content = "祝宴？",
  ui_story_5038_50380801_240_dialog_content = "そうですよ。蜃風号修繕成功と\n航海が軌道に戻ったことを祝って…",
  ui_story_5038_50380801_241_dialog_content = "おっと、こいつは俺が言うべきことじゃなかったですね。\n船長、さ、挨拶を！",
  ui_story_5038_50380801_242_dialog_content = "え、私…？",
  ui_story_5038_50380801_243_dialog_content = "ごめんなさい。こういうことには慣れていないから…",
  ui_story_5038_50380801_244_dialog_content = "とにかく、皆…食事を楽しんで。",
  ui_story_5038_50380801_245_dialog_content = "船にあるものなら、好きなだけ食べて構わないわ。",
  ui_story_5038_50380801_246_dialog_content = "本当ですかい！？\nだったら、倉庫にあった干し肉が食いてえです！",
  ui_story_5038_50380801_247_dialog_content = "毎日魚じゃ、飽きちまいましたよ！",
  ui_story_5038_50380801_248_dialog_content = "ちょっと、お魚の何がいけないの？",
  ui_story_5038_50380801_249_dialog_content = "食べないなら、全部ボクにちょうだい！",
  ui_story_5038_50380801_250_dialog_content = "シュウ様、お席が皆さまと離れているようですが…",
  ui_story_5038_50380801_251_dialog_content = "お料理をもって参りましょうか？",
  ui_story_5038_50380801_252_dialog_content = "気遣いかたじけない。\nだが、こうして静かに座っているだけでよい。",
  ui_story_5038_50380801_253_dialog_content = "にぎやかな宴はお嫌いでしたか。",
  ui_story_5038_50380801_254_dialog_content = "いいや、そういうわけでもない。",
  ui_story_5038_50380801_255_dialog_content = "まだ官にあった頃には、宴にもよく出たものだ。",
  ui_story_5038_50380801_256_dialog_content = "ただ、一線を退いてから、\nにぎやかな宴ほど、遠くから眺めておるのが好きだと分かってな。",
  ui_story_5038_50380801_257_dialog_content = "こうして、場にいる皆の喜びを眺めている時、\nそれがしは誰より宴を楽しんでいるのだ。",
  ui_story_5038_50380801_258_dialog_content = "さようですか？\n難しいことをおっしゃいますね…",
  ui_story_5038_50380801_259_dialog_content = "キュウ！ここにおったか。",
  ui_story_5038_50380801_260_dialog_content = "殿下！驚かせないでください…",
  ui_story_5038_50380801_261_dialog_content = "船の衆が皆で踊ると言っておる。\nそなたも来んか。",
  ui_story_5038_50380801_262_dialog_content = "そなたの美しき舞を見せてやれ。",
  ui_story_5038_50380801_263_dialog_content = "殿下、恐れ入りますが、\n私の舞など他人にお見せするようなものでは…",
  ui_story_5038_50380801_264_dialog_content = "それなら、ちょうど新しい料理が出ておるぞ。\n食べに行くとするか。",
  ui_story_5038_50380801_265_dialog_content = "早くせんと、なくなってしまうぞ！",
  ui_story_5038_50380801_266_dialog_content = "アハハ、タンドウ、\n楽しんでるみたいだね。",
  ui_story_5038_50380801_267_dialog_content = "うむ、大いに楽しんでおる。",
  ui_story_5038_50380801_268_dialog_content = "見るがよい。我らの上にある帆は我らの手で建て直したもの。\n足元の船も、我らの手で直したものじゃ。",
  ui_story_5038_50380801_269_dialog_content = "それ以上の幸があるか？",
  ui_story_5038_50380801_270_dialog_content = "我らは今ひとつ船の上で、\n各々の力を合わせ、海を渡っておる。",
  ui_story_5038_50380801_271_dialog_content = "うん、その通りだね。\n僕にも何だか蜃風号が自分の家みたいに思えてきたよ。",
  ui_story_5038_50380801_272_dialog_content = "じゃろう？\nここに居合わせる者にしか共有できぬ心地じゃ。",
  ui_story_5038_50380801_273_dialog_content = "むろん、皆が喜んでいることは他にもある…",
  ui_story_5038_50380801_274_dialog_content = "見るがよい。",
  ui_story_5038_50380801_275_dialog_content = "本当に大変だったわね。ずいぶん苦労したわ…",
  ui_story_5038_50380801_276_dialog_content = "でも、これでようやくゆっくり眠れそうよ。",
  ui_story_5038_50380801_277_dialog_content = "そうだな…明日からは帆柱を修理する必要もなけりゃ、\n水をくみ出す必要もねえ…",
  ui_story_5038_50380801_278_dialog_content = "やっと龍州に帰れるんだ。",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>5日後</color>",
  ui_story_5038_50380901_2_dialog_content = "船長、全部品の点検、終わりました。\n問題は何もありません。",
  ui_story_5038_50380901_3_dialog_content = "貨物庫に軽い浸水がありますが、\n昨日から大きな変わりはありません。",
  ui_story_5038_50380901_4_dialog_content = "分かったわ。問題がなければいいの。",
  ui_story_5038_50380901_5_dialog_content = "濡れてしまった荷物の処分は？",
  ui_story_5038_50380901_6_dialog_content = "済んでます。まったく使えないものは海に捨てて、\n濡れのひどくないものは今甲板で乾かしてます。",
  ui_story_5038_50380901_7_dialog_content = "ただ…処分の必要な食料が多かったので、\n残りがだいぶ少なくなりました。",
  ui_story_5038_50380901_8_dialog_content = "食料…",
  ui_story_5038_50380901_9_dialog_content = "水は？淡水はどれだけ残っているの？",
  ui_story_5038_50380901_10_dialog_content = "水は少し余裕があります。\n半月ほどは持つでしょう。",
  ui_story_5038_50380901_11_dialog_content = "船長、岸まであとどのぐらいです？",
  ui_story_5038_50380901_12_dialog_content = "悪いけど、まだ分からないわ。",
  ui_story_5038_50380901_13_dialog_content = "海図も海の真ん中にはそこまで詳しくないし、\n例の襲撃もあったから…",
  ui_story_5038_50380901_14_dialog_content = "今は海図に何もない辺りにいるの。\n方向も距離も、予測しか立てられないわね。",
  ui_story_5038_50380901_15_dialog_content = "これからは魚を捕って食べましょう。\n備蓄の食料はできるだけ温存して。",
  ui_story_5038_50380901_16_dialog_content = "水も同じよ。飲み水以外は、できる限り節約して。",
  ui_story_5038_50380901_17_dialog_content = "それだけよ、行きなさい。",
  ui_story_5038_50380901_18_dialog_content = "…はい、船長。",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>さらに5日後</color>",
  ui_story_5038_50380901_20_dialog_content = "今日のお昼ご飯、また量が減ったね…",
  ui_story_5038_50380901_21_dialog_content = "ええ…仕方ないのよ。",
  ui_story_5038_50380901_22_dialog_content = "やっぱり足りない？",
  ui_story_5038_50380901_23_dialog_content = "そもそも一口も食べてないよ。",
  ui_story_5038_50380901_24_dialog_content = "ボクの分、全部チビシッポにあげたんだ。",
  ui_story_5038_50380901_25_dialog_content = "ダメよ、食べなかったら背が伸びないわ。",
  ui_story_5038_50380901_26_dialog_content = "い、いやだなぁ、そんなの古い考え方だよ！\n背が高ければいいってもんじゃないでしょ！？",
  ui_story_5038_50380901_27_dialog_content = "甲板に行ってくるわ。",
  ui_story_5038_50380901_28_dialog_content = "運が良ければ、夜はお魚を食べられるかもね。",
  ui_story_5038_50380901_29_dialog_content = "お魚！？ほんとに！？",
  ui_story_5038_50380901_30_dialog_content = "ええ！運が良ければね。",
  ui_story_5038_50380901_31_dialog_content = "私は…魚をとることは得意じゃないから…",
  ui_story_5038_50380901_32_dialog_content = "とにかく…楽しみにして…",
  ui_story_5038_50380901_33_dialog_content = "どうしたの？なんかふらふらしてるよ！？",
  ui_story_5038_50380901_34_dialog_content = "え？そんなこと…",
  ui_story_5038_50380901_35_dialog_content = "手を出して。",
  ui_story_5038_50380901_36_dialog_content = "そんな、大したことじゃ…",
  ui_story_5038_50380901_37_dialog_content = "…病気だね。",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>さらに5日後</color>",
  ui_story_5038_50380901_39_dialog_content = "チビシッポ、走り回っちゃダメだよ！",
  ui_story_5038_50380901_40_dialog_content = "海に落ちたらどうするの！？",
  ui_story_5038_50380901_41_dialog_content = "ニャ～オ。",
  ui_story_5038_50380901_42_dialog_content = "おせっかいかもしれないけど、\nこんなに風が強いんだ。",
  ui_story_5038_50380901_43_dialog_content = "いつ突風で飛ばされるか分からないよ。",
  ui_story_5038_50380901_44_dialog_content = "早く中に入ろう。",
  ui_story_5038_50380901_45_dialog_content = "ニャ～オ――",
  ui_story_5038_50380901_46_dialog_content = "ふぅ…ふぅ…やっぱりネコって速いなぁ。\n追いつかない…",
  ui_story_5038_50380901_47_dialog_content = "心配することはないわ。\n動物の方が人より危険に敏感よ。",
  ui_story_5038_50380901_48_dialog_content = "本当に危険な時には、\nむしろ人が動物に頼ることになるの。",
  ui_story_5038_50380901_49_dialog_content = "あ、船長！",
  ui_story_5038_50380901_50_dialog_content = "リンセイを見かけなかった？\n今日一日全然会ってないんだけど…",
  ui_story_5038_50380901_51_dialog_content = "そうでもなきゃ、\n僕だってチビシッポの心配はしないし…",
  ui_story_5038_50380901_52_dialog_content = "看病してるわ。",
  ui_story_5038_50380901_53_dialog_content = "昨日また船員が2人倒れたの。\n熱病にかかったらしいわ。",
  ui_story_5038_50380901_54_dialog_content = "リンセイには面倒を掛けてしまっているわね。",
  ui_story_5038_50380901_55_dialog_content = "また…",
  ui_story_5038_50380901_56_dialog_content = "龍州まではあとどのくらい？",
  ui_story_5038_50380901_57_dialog_content = "…",
  ui_story_5038_50380901_58_dialog_content = "分からないわ…",
  ui_story_5038_50380901_59_dialog_content = "（ユエが悲しそうな顔をしていることにふと気づいた）",
  ui_story_5038_50380901_60_dialog_content = "（そもそも答えようのない質問なのかもしれない）",
  ui_story_5038_50380901_61_dialog_content = "（僕は彼女に聞けばいいが、\n彼女はいったい誰に聞けばいいというのだろう？）",
  ui_story_5038_50380901_62_dialog_content = "海は広いのよ。\n龍州ほど遠くの場所が見えるはずないわ。",
  ui_story_5038_50380901_63_dialog_content = "見えるのは近くにあるものだけ。",
  ui_story_5038_50380901_64_dialog_content = "中に入った方がいいわ。\nもうすぐ嵐が来そう。",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5038_50380901_66_dialog_content = "船長、甲板にあったものは全部片づけました。\n船員は全員配置についています。",
  ui_story_5038_50380901_67_dialog_content = "下積みは点検した？",
  ui_story_5038_50380901_68_dialog_content = "はい、問題はありません。\n嵐にも耐えられるはずです。",
  ui_story_5038_50380901_69_dialog_content = "分かったわ。これで準備はほぼ完了ね。",
  ui_story_5038_50380901_70_dialog_content = "船尾で私の号令を待ちなさい。",
  ui_story_5038_50380901_71_dialog_content = "あの…船長、待ってください。\n帆は下ろさないでいいんですか？",
  ui_story_5038_50380901_72_dialog_content = "このままでいいの。\n風に乗って目いっぱいに広げておいて。",
  ui_story_5038_50380901_73_dialog_content = "嵐の中で帆を上げて進むつもりですか！？",
  ui_story_5038_50380901_74_dialog_content = "き、危険すぎますよ！？\n船体が持つかどうか…",
  ui_story_5038_50380901_75_dialog_content = "それに…この間みたいに、\n波に紛れて暗鬼が船に上がってくるかも…",
  ui_story_5038_50380901_76_dialog_content = "分かっているわ。\nだけど、これ以上は時間がない。",
  ui_story_5038_50380901_77_dialog_content = "海だけじゃないわ。\nこれは時間との勝負でもあるの。",
  ui_story_5038_50380901_78_dialog_content = "このまま蜃風号を止めてしまったら、\nおそらく陸まで間に合わない…",
  ui_story_5038_50380901_79_dialog_content = "それは…",
  ui_story_5038_50380901_80_dialog_content = "とにかく、風に乗って進むしかないの。\nたとえそれが嵐でも。",
  ui_story_5038_50380901_81_dialog_content = "暗鬼が甲板まで登ってくるようなら、\n怖がるべきは向こうの方じゃないかしら。",
  ui_story_5038_50380901_82_dialog_content = "お客様の多くが退屈しているようだもの。",
  ui_story_5038_50380901_83_dialog_content = "そこまで言うなら…",
  ui_story_5038_50380901_84_dialog_content = "やりましょう！\n俺も船の男だ、船長に従います！",
  ui_story_5038_50380901_85_dialog_content = "ありがとう。\nでは、今すぐ船尾に向かって、位置について。",
  ui_story_5038_50380901_86_dialog_content = "波がすぐに高くなるわ。\nいつでも号令で動けるようにしておいて。",
  ui_story_5038_50380901_87_dialog_content = "はい！！！",
  ui_story_5038_50381001_1_dialog_content = "（蜃風号はもう丸1日、嵐に揺られている）",
  ui_story_5038_50381001_2_dialog_content = "（僕たちも散々な目に遭った。\n船には酔うし、そこら中にぶつかるし、暗鬼にも襲われた）",
  ui_story_5038_50381001_3_dialog_content = "（でも、ようやく今、帆を狂ったように\nうならせていた風の音が小さくなってきた）",
  ui_story_5038_50381001_4_dialog_content = "（蜃風号は、嵐を乗り越えたんだ）",
  ui_story_5038_50381001_5_dialog_content = "甲板に危険はなさそうじゃな。",
  ui_story_5038_50381001_6_dialog_content = "そうだね。もう嵐は通り過ぎたんだよね？",
  ui_story_5038_50381001_7_dialog_content = "ええ。一番危ないところは越えたわ。",
  ui_story_5038_50381001_8_dialog_content = "この後も少し強風や高波が続くでしょうけど、\n油断しなければ問題はないわ。",
  ui_story_5038_50381001_9_dialog_content = "そりゃありがたい、やっと終わりましたか…",
  ui_story_5038_50381001_10_dialog_content = "これ以上揺られていたら、\n五臓六腑が飛び出るところでしたねぇ。",
  ui_story_5038_50381001_11_dialog_content = "テンカン、大丈夫？顔色が悪いね。",
  ui_story_5038_50381001_12_dialog_content = "まあまあってところですねぇ。\n甲板で風に当たったら、だいぶよくなりました。",
  ui_story_5038_50381001_13_dialog_content = "それより船長、そろそろ食事の時間じゃないですかねぇ？",
  ui_story_5038_50381001_14_dialog_content = "嵐で揺らされ続けた上に、\n1日中すきっ腹じゃあ、身体が持ちませんよ。",
  ui_story_5038_50381001_15_dialog_content = "その通りね。",
  ui_story_5038_50381001_16_dialog_content = "厨房に夕食を支度させて。",
  ui_story_5038_50381001_17_dialog_content = "分かりました。",
  ui_story_5038_50381001_18_dialog_content = "ただ…船長、残りの食料も少なくなっていますので…\n日数分を残しておかないと…",
  ui_story_5038_50381001_19_dialog_content = "あと何日ほどですか？",
  ui_story_5038_50381001_20_dialog_content = "…まだはっきりとは分からないわ。",
  ui_story_5038_50381001_21_dialog_content = "今日はまず皆に\nお腹いっぱい食べさせて…",
  ui_story_5038_50381001_22_dialog_content = "いえ、八分目にしておきましょう。",
  ui_story_5038_50381001_23_dialog_content = "ねえ、あとどのぐらい残ってるの？",
  ui_story_5038_50381001_24_dialog_content = "…",
  ui_story_5038_50381001_25_dialog_content = "分かってるんでしょう？\n教えてくれてもいいじゃない。",
  ui_story_5038_50381001_26_dialog_content = "よくない状況なのは分かってるわ。\nただ、はっきり知っておきたいだけよ。",
  ui_story_5038_50381001_27_dialog_content = "このままじゃまずい。",
  ui_story_5038_50381001_28_dialog_content = "え？",
  ui_story_5038_50381001_29_dialog_content = "行くぞ、皆で魚をとるんだ。",
  ui_story_5038_50381001_30_dialog_content = "今から？でも私、まだ作業が…",
  ui_story_5038_50381001_31_dialog_content = "そうとう重要でないなら後回しにするんだ。",
  ui_story_5038_50381001_32_dialog_content = "これからは、全員少しでも時間を作って、\n食料を確保するんだ。",
  ui_story_5038_50381001_33_dialog_content = "でねえと、あと数日で空きっ腹を抱えることになるぞ。",
  ui_story_5038_50381001_34_dialog_content = "そこまで深刻なの…？",
  ui_story_5038_50381001_35_dialog_content = "分かったわ。皆を呼んでくる。",
  ui_story_5038_50381001_36_dialog_content = "網を上げるぞ！",
  ui_story_5038_50381001_37_dialog_content = "急げ、網を上げるのを手伝ってくれ！",
  ui_story_5038_50381001_38_dialog_content = "よいしょ！",
  ui_story_5038_50381001_39_dialog_content = "どうして急に、みんなで魚をとりだしたんだろう？",
  ui_story_5038_50381001_40_dialog_content = "もしかして…食料の問題かな？",
  ui_story_5038_50381001_41_dialog_content = "でしょうねぇ。\n人の一番原始的な心配事ですから。",
  ui_story_5038_50381001_42_dialog_content = "船が直ったところで、\n人がもたなきゃあ意味がないですからねぇ。",
  ui_story_5038_50381001_43_dialog_content = "うん…",
  ui_story_5038_50381001_44_dialog_content = "今いるのが海でよかったかもね。\n少なくとも、魚はいくらでもいるし。",
  ui_story_5038_50381001_45_dialog_content = "そう簡単なことじゃあありません。",
  ui_story_5038_50381001_46_dialog_content = "魚で飢えはしのげるとしても、\n淡水はどんどん減っていきますから。",
  ui_story_5038_50381001_47_dialog_content = "水を使いきってしまったら、\nもう希望がないってことになります。",
  ui_story_5038_50381001_48_dialog_content = "人というのは結局、陸の上で暮らす生き物ですから…",
  ui_story_5038_50381001_49_dialog_content = "海に出たその時から、毎日が引き算というわけですねぇ。",
  ui_story_5038_50381001_50_dialog_content = "引き算か…",
  ui_story_5038_50381001_51_dialog_content = "あとどのくらいの時間が残されてるんだろう…？",
  ui_story_5038_50381001_52_dialog_content = "また1匹かかったぞ！大物だ！",
  ui_story_5038_50381001_53_dialog_content = "みんな来てくれ、引き上げるぞ！",
  ui_story_5038_50381001_54_dialog_content = "3、2、1――",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>バシャン――</color>",
  ui_story_5038_50381001_56_dialog_content = "わ、こりゃ大きい！",
  ui_story_5038_50381001_57_dialog_content = "ハハハ！やったぞ！",
  ui_story_5038_50381001_58_dialog_content = "この大きさなら、5、6人前にはなる！",
  ui_story_5038_50381001_59_dialog_content = "わぁ、本当に大きいね！",
  ui_story_5038_50381001_60_dialog_content = "おやおや、こんな大物、\n今までに見たことないですねぇ。",
  ui_story_5038_50381001_61_dialog_content = "さあ、急いで厨房に運ぶぞ。",
  ui_story_5038_50381001_62_dialog_content = "今晩はまともに食えなかったし、\n夜食にでもするか！",
  ui_story_5038_50381001_63_dialog_content = "<size=50>うおおー！！</size>",
  ui_story_5038_50381001_64_dialog_content = "放してやれ。",
  ui_story_5038_50381001_65_dialog_content = "ん？誰だ！？",
  ui_story_5038_50381001_66_dialog_content = "それを放してやれと申したのだ。",
  ui_story_5038_50381001_67_dialog_content = "シュウ様？なぜ…",
  ui_story_5038_50381001_68_dialog_content = "シュウさんの言う通りだよ。\n早く放してあげて。",
  ui_story_5038_50381001_69_dialog_content = "よく見てよ。そのお魚、ミズチウオだよ！",
  ui_story_5038_50381001_70_dialog_content = "ミズチウオ！？",
  ui_story_5038_50381001_X70_dialog_content = "まずいぞ、さっきは気づかなかったが、\nこの前船を襲った…",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>ドン――！！！</color>",
  ui_story_5038_50381001_72_dialog_content = "わわわ！？",
  ui_story_5038_50381001_73_dialog_content = "うわっ！？",
  ui_story_5038_50381001_74_dialog_content = "どういうこと！？船に何かぶつかったの！？",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>ドン――！！！</color>",
  ui_story_5038_50381001_76_dialog_content = "ま、またですか！？",
  ui_story_5038_50381001_77_dialog_content = "下だ！下を見てみろ！",
  ui_story_5038_50381001_78_dialog_content = "魚だ！魚がたくさんぶつかってきてるぞ！",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>ドン――！！！</color>",
  ui_story_5038_50381001_80_dialog_content = "気をつけろ！！甲板まで飛び込んでくる！",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>ドン――！！！</color>",
  ui_story_5038_50381002_2_dialog_content = "うわあ！！",
  ui_story_5038_50381002_3_dialog_content = "どうしたらいいんだ！？\nまだぶつかってくるぞ！",
  ui_story_5038_50381002_4_dialog_content = "修繕したとはいえ、今度壊されたら…",
  ui_story_5038_50381002_5_dialog_content = "早く、そのお魚、ボクに渡して！",
  ui_story_5038_50381002_6_dialog_content = "なに？",
  ui_story_5038_50381002_7_dialog_content = "ほら、お魚さん、早く海へお帰り！",
  ui_story_5038_50381002_8_dialog_content = "えい！",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5038_50381002_10_dialog_content = "よし、これで大丈夫だよ。",
  ui_story_5038_50381002_11_dialog_content = "あの魚が攻撃された原因だったの？",
  ui_story_5038_50381002_12_dialog_content = "そうだよ。ミズチウオは仲間意識がとっても強いんだ。",
  ui_story_5038_50381002_13_dialog_content = "1匹でも捕まれば、群れ全体で助けにくるんだよ。",
  ui_story_5038_50381002_14_dialog_content = "だから、ミズチウオを怒らせちゃうと、\nたいへんなことになるんだ。",
  ui_story_5038_50381002_15_dialog_content = "面白い習性だね…",
  ui_story_5038_50381002_16_dialog_content = "リンセイとシュウ様に感謝します…",
  ui_story_5038_50381002_17_dialog_content = "俺たちの軽率な行動のせいで、\n大変なことになるところでした。",
  ui_story_5038_50381002_18_dialog_content = "いいんだよ。みんな同じ船の仲間でしょ！\nそんな硬いことは抜き抜き！",
  ui_story_5038_50381002_19_dialog_content = "大事になる前に済んだんだから、\nそれでいいでしょ。",
  ui_story_5038_50381002_20_dialog_content = "でも…この辺りにミズチウオが出るってことは、\nまた船が狙われるんじゃ…？",
  ui_story_5038_50381002_21_dialog_content = "今度やられたら持ちませんよ…",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5038_50381002_23_dialog_content = "またミズチウオだ！早く放してやれ！",
  ui_story_5038_50381002_24_dialog_content = "分かってるよ、初めてじゃねえんだから！",
  ui_story_5038_50381002_25_dialog_content = "まったく…ミズチウオ様よぅ、俺たちのことも考えてくれよ。",
  ui_story_5038_50381002_26_dialog_content = "７匹目…",
  ui_story_5038_50381002_27_dialog_content = "船長！ここにいたんだね！",
  ui_story_5038_50381002_28_dialog_content = "昼食ができたよ。\n皆に呼んでくるように言われたんだ。",
  ui_story_5038_50381002_29_dialog_content = "今日のお昼は豪華だよ。\n全部魚料理だけどね、アハハ。",
  ui_story_5038_50381002_30_dialog_content = "私はいいわ、皆で食べて。",
  ui_story_5038_50381002_31_dialog_content = "え？食べないの？",
  ui_story_5038_50381002_32_dialog_content = "何か…悩みでも？",
  ui_story_5038_50381002_33_dialog_content = "気になることがあって…\nはっきりさせないと気持ちが落ち着かないの。",
  ui_story_5038_50381002_34_dialog_content = "え？気になることって…",
  ui_story_5038_50381002_35_dialog_content = "ミズチウオの様子がおかしいわ。",
  ui_story_5038_50381002_36_dialog_content = "ミズチウオは海を回遊する魚よ。\n龍州とアストラの間を一年周期で行き来しているの。",
  ui_story_5038_50381002_37_dialog_content = "陸地の近くで少しの間留まる以外、\n海のどこでも移動し続けているはずよ。",
  ui_story_5038_50381002_38_dialog_content = "だけど今は、群れになったミズチウオが\nこの海域に留まり続けている…",
  ui_story_5038_50381002_39_dialog_content = "そうだね。\n今日も網にミズチウオばっかりかかってるみたいだった。",
  ui_story_5038_50381002_40_dialog_content = "また襲撃されたりは…",
  ui_story_5038_50381002_41_dialog_content = "今のところ、その兆候はないわ。",
  ui_story_5038_50381002_42_dialog_content = "いちおう、できる限り群れを避けて、\nこの間と同じことにならないように努めてはいる…",
  ui_story_5038_50381002_43_dialog_content = "それでも、ミズチウオの行動がおかしいのは確かよ。\n少なくとも、この海域に何かがある。",
  ui_story_5038_50381002_44_dialog_content = "龍州以上にミズチウオを引き付ける、何かが…",
  ui_story_5038_50381002_45_dialog_content = "ううん…",
  ui_story_5038_50381002_46_dialog_content = "あなたは戻って食べに行って。\n私は海図を確かめてみるわ。",
  ui_story_5038_50381002_47_dialog_content = "蜃風号の場所は…",
  ui_story_5038_50381002_48_dialog_content = "昨日の針路、風速から考えて…",
  ui_story_5038_50381002_49_dialog_content = "いいえ、もっと北よりのはずね。",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>コン、コン</color>",
  ui_story_5038_50381002_51_dialog_content = "誰？",
  ui_story_5038_50381002_52_dialog_content = "シュウだ。",
  ui_story_5038_50381002_53_dialog_content = "シュウ様？どうしてこちらに…",
  ui_story_5038_50381002_54_dialog_content = "海上で何日も揺られて、\nそれがしでは方角が分からぬ故な。",
  ui_story_5038_50381002_55_dialog_content = "船長殿にお尋ねしたい。\n今、この蜃風号はどのあたりにあるのか？",
  ui_story_5038_50381002_56_dialog_content = "どのあたりと申されましても…",
  ui_story_5038_50381002_57_dialog_content = "海図も完全なものではありませんので、\n私でも正確な位置は答えかねます。",
  ui_story_5038_50381002_58_dialog_content = "もう少し分析が進んで予測が立ちましたら、\nだいたいの位置はお教えできると思いますが。",
  ui_story_5038_50381002_59_dialog_content = "案ずるな。それがしでは航行の役に立てぬ。\nただ尋ねただけのことだ。",
  ui_story_5038_50381002_60_dialog_content = "船長殿がこの後のことについて、\n分かっているのであれば、それでよい。",
  ui_story_5038_50381002_61_dialog_content = "…",
  ui_story_5038_50381002_62_dialog_content = "ただそれがしと同様、\n貴公に確信がないと見えることが恐ろしい。",
  ui_story_5038_50381002_63_dialog_content = "それは…",
  ui_story_5038_50381002_64_dialog_content = "シュウ様、大海原を前に全てに確信を持つなどという\n大それたこと、このユエには致しかねます。",
  ui_story_5038_50381002_65_dialog_content = "ただ、全力を尽くすとしか申し上げられません。",
  ui_story_5038_50381002_66_dialog_content = "先のことなど誰にも測れぬ。",
  ui_story_5038_50381002_67_dialog_content = "船長殿の覚悟に敬服いたす。",
  ui_story_5038_50381002_68_dialog_content = "ただ、大海原の上で、全てに確信を持てる方法はある。",
  ui_story_5038_50381002_69_dialog_content = "…",
  ui_story_5038_50381002_70_dialog_content = "「羅針盤」ですね？",
  ui_story_5038_50381002_71_dialog_content = "左様。船長殿が陸に着くことを第一としていることは、\nそれがしも重々承知しておる。",
  ui_story_5038_50381002_72_dialog_content = "されど、蜃風号の物資は枯渇しつつあり、方位も分からぬ有り様…\n窮地を脱する唯一の手立ては「羅針盤」を探し出すことではあるまいか？",
  ui_story_5038_50381002_73_dialog_content = "「羅針盤」を探す…",
  ui_story_5038_50381002_74_dialog_content = "おそれながら、仮にその通りだとしても、\nそれには並々ならぬ労力が必要です。",
  ui_story_5038_50381002_75_dialog_content = "今の状態で、この大海原のあちこちを\n探し回る余力はないかと…",
  ui_story_5038_50381002_76_dialog_content = "探し回る必要がないとしたら、いかがかな？",
  ui_story_5038_50381002_77_dialog_content = "リン家の秘宝「羅針盤」は、\nまさにこの海域にある。",
  ui_story_5038_50381002_78_dialog_content = "…！？",
  ui_story_5038_50381002_79_dialog_content = "はぁ…",
  ui_story_5038_50381002_80_dialog_content = "また食料がダメになってやがる…",
  ui_story_5038_50381002_81_dialog_content = "…捨てずにとっておくか…？",
  ui_story_5038_50381002_82_dialog_content = "腐ってても、何もないよりはマシだろ…",
  ui_story_5038_50381002_83_dialog_content = "水は…",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>ゴトン――</color>",
  ui_story_5038_50381002_85_dialog_content = "このタルはもう空か…",
  ui_story_5038_50381002_86_dialog_content = "ああ、天の神様よ。少しでいいから雨を降らせてくれ…",
  ui_story_5038_50381002_87_dialog_content = "残りはあと1、2、3…",
  ui_story_5038_50381002_88_dialog_content = "もう、やっと見つけたわ。\nここにいたのね！",
  ui_story_5038_50381002_89_dialog_content = "ああ？どうした？",
  ui_story_5038_50381002_90_dialog_content = "急いで、船長がお呼びよ！",
  ui_story_5038_50381101_1_dialog_content = "魚とりばかりに気をとられてるんじゃねえぞ。\n遠くの海面もしっかり見とけ！",
  ui_story_5038_50381101_2_dialog_content = "船長からのお達しだ。\nこの海域を徹底的に探す！",
  ui_story_5038_50381101_3_dialog_content = "何か見つけたらすぐ報告しろ！",
  ui_story_5038_50381101_4_dialog_content = "了解！",
  ui_story_5038_50381101_5_dialog_content = "リンセイ、皆「羅針盤」を探してるの？",
  ui_story_5038_50381101_6_dialog_content = "そうだよ。でなきゃ、何もない海を\nみんなでにらみつける必要なんてないでしょ？",
  ui_story_5038_50381101_7_dialog_content = "「羅針盤」は古い方の蜃風号の上にあったって…",
  ui_story_5038_50381101_8_dialog_content = "あ！そういえば、リン家の船は沈没してないって、\nこのあいだ言いかけてたよね？",
  ui_story_5038_50381101_9_dialog_content = "少なくとも、ボクとシュウさんが船を離れた時にはね。",
  ui_story_5038_50381101_10_dialog_content = "ってことは、ずっと船だけで海を漂ってるってこと？",
  ui_story_5038_50381101_11_dialog_content = "想像すると、ちょっと怖いなぁ…",
  ui_story_5038_50381101_12_dialog_content = "その方が探しやすいよ。\nボクたちにとっては都合がいいじゃない？",
  ui_story_5038_50381101_13_dialog_content = "でも…長い間海の上を漂ってるなら、\n嵐や大波にだって遭ってるはず…",
  ui_story_5038_50381101_14_dialog_content = "船に誰もいないなら、\nとっくに傷んで沈んでるんじゃない？",
  ui_story_5038_50381101_15_dialog_content = "それはないよ。",
  ui_story_5038_50381101_16_dialog_content = "忘れたの？ボクたちが探してる「羅針盤」が、\n船にまだ残ってるんだ。",
  ui_story_5038_50381101_17_dialog_content = "チッ、日暮れか…",
  ui_story_5038_50381101_18_dialog_content = "今日はここまでにしない？",
  ui_story_5038_50381101_19_dialog_content = "暗くなったら、探しようがないわ。",
  ui_story_5038_50381101_20_dialog_content = "今日のところは収穫なしか…",
  ui_story_5038_50381101_21_dialog_content = "そう時間もないってぇのに…",
  ui_story_5038_50381101_22_dialog_content = "あっちに何かあるよ！",
  ui_story_5038_50381101_23_dialog_content = "ああ？なんだって！？",
  ui_story_5038_50381101_24_dialog_content = "見てよ、ほら！あそこだよ！",
  ui_story_5038_50381101_25_dialog_content = "本当だ！何か流れてくるぞ！",
  ui_story_5038_50381101_26_dialog_content = "あれは…板かな？",
  ui_story_5038_50381101_27_dialog_content = "もう少し近ければ…もう少し…",
  ui_story_5038_50381101_28_dialog_content = "あ、見えた！",
  ui_story_5038_50381101_29_dialog_content = "木に何か書いてある…",
  ui_story_5038_50381101_30_dialog_content = "「リン」！！",
  ui_story_5038_50381101_31_dialog_content = "リン家の扁額（へんがく）だ！",
  ui_story_5038_50381101_32_dialog_content = "リン家の！？…ってことは、まさか前の蜃風号が…",
  ui_story_5038_50381101_33_dialog_content = "見た感じ、水に落ちてからそう長くない！",
  ui_story_5038_50381101_34_dialog_content = "まちがいないよ！\n先代の蜃風号、この近くにあるんだ！",
  ui_story_5038_50381101_35_dialog_content = "小舟は？降りてみて来る！",
  ui_story_5038_50381101_36_dialog_content = "今から！？",
  ui_story_5038_50381101_37_dialog_content = "少し待った方がいいよ。\nまずは船長たちどう探すか相談したほうが…",
  ui_story_5038_50381101_38_dialog_content = "その必要はないわ。",
  ui_story_5038_50381101_39_dialog_content = "あ、船長…",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>バシャン――</color>",
  ui_story_5038_50381101_41_dialog_content = "と、飛び込んだ！？",
  ui_story_5038_50381101_42_dialog_content = "水が怖くないんだ…うらやましいなぁ。",
  ui_story_5038_50381101_43_dialog_content = "おっと、ボクものんびりしてられないよ！",
  ui_story_5038_50381101_44_dialog_content = "急いで！舟を下ろして！",
  ui_story_5038_50381101_45_dialog_content = "（海水から木材の味がする）",
  ui_story_5038_50381101_46_dialog_content = "（下の方、もっと深いところだわ）",
  ui_story_5038_50381101_47_dialog_content = "（ここに沈んでいるというの？）",
  ui_story_5038_50381101_48_dialog_content = "（「羅針盤」…水に浸かってもまだ無事かしら…）",
  ui_story_5038_50381101_49_dialog_content = "（はぁ…結局、私の腕ではアレに頼るしかないってことね）",
  ui_story_5038_50381101_50_dialog_content = "（もっと下へ…）",
  ui_story_5038_50381101_51_dialog_content = "（もっと深くへ行かないと）",
  ui_story_5038_50381101_52_dialog_content = "（海の底まで…）",
  ui_story_5038_50381101_53_dialog_content = "（あれは…）",
  ui_story_5038_50381101_54_dialog_content = "（！！！）",
  ui_story_5038_50381101_55_dialog_content = "（沈没した船…一隻ではない…）",
  ui_story_5038_50381101_56_dialog_content = "（見慣れているはずの船も、海の底で見ると違うわね）",
  ui_story_5038_50381101_57_dialog_content = "（とても静か…異様なほどに）",
  ui_story_5038_50381101_58_dialog_content = "（遭難した時には激しく揺られていたでしょうに、\n沈んだ後は、ただ静けさだけが残る）",
  ui_story_5038_50381101_59_dialog_content = "（静かすぎて、怖いほどに…）",
  ui_story_5038_50381101_60_dialog_content = "（海に飲み込まれたのは船だけじゃない。\n人々の感情も、叫び声も、一緒に飲み込んでしまった）",
  ui_story_5038_50381101_61_dialog_content = "（海はすべてを飲み込み、同化してしまう。\nいずれは高波さえも収まるように…）",
  ui_story_5038_50381101_62_dialog_content = "（ここが沈没船の墓場…まるで港にいるようで…）",
  ui_story_5038_50381101_63_dialog_content = "（でも、ここにある船が二度と出航することはない）",
  ui_story_5038_50381101_64_dialog_content = "（近くへ見に行った方がいいかしら…）",
  ui_story_5038_50381101_65_dialog_content = "（でも…リン家の船は見当たらないわね）",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5038_50381101_67_dialog_content = "よし、用意できたぞ。",
  ui_story_5038_50381101_68_dialog_content = "今すぐ出る気か？",
  ui_story_5038_50381101_69_dialog_content = "うん、今すぐ出発するよ！",
  ui_story_5038_50381101_70_dialog_content = "リンセイ、僕も一緒に行くよ。",
  ui_story_5038_50381101_71_dialog_content = "君一人で行かせるわけには…",
  ui_story_5038_50381101_72_dialog_content = "水が怖いんでしょ？",
  ui_story_5038_50381101_73_dialog_content = "うーん…",
  ui_story_5038_50381101_74_dialog_content = "分かった、一緒に行こう。",
  ui_story_5038_50381101_75_dialog_content = "かいが長すぎるから、ボクひとりじゃ大変だしね。",
  ui_story_5038_50381101_76_dialog_content = "よし！一緒に行こう！",
  ui_story_5038_50381101_77_dialog_content = "じゃあ、舟を下ろして…",
  ui_story_5038_50381101_78_dialog_content = "グァ…",
  ui_story_5038_50381101_79_dialog_content = "うわ！何の音！？",
  ui_story_5038_50381101_80_dialog_content = "な…何かが舟を引っ張ってやがる！",
  ui_story_5038_50381101_81_dialog_content = "なんだって！？",
  ui_story_5038_50381101_82_dialog_content = "まったく、どこのどいつ…",
  ui_story_5038_50381101_83_dialog_content = "グオオ――！！！",
  ui_story_5038_50381101_84_dialog_content = "うわわわ！",
  ui_story_5038_50381101_85_dialog_content = "コイツめ！どこから出て来たんだろう！？",
  ui_story_5038_50381101_86_dialog_content = "し、下からだ！舟の縄をつたってきてるぞ！",
  ui_story_5038_50381101_87_dialog_content = "なんて数だ！",
  ui_story_5038_50381102_1_dialog_content = "ガァ…",
  ui_story_5038_50381102_2_dialog_content = "縁起が悪いなぁ…手が汚れちゃったよ。",
  ui_story_5038_50381102_3_dialog_content = "他にはまだいる？",
  ui_story_5038_50381102_4_dialog_content = "もういないよ、全部倒せた。",
  ui_story_5038_50381102_5_dialog_content = "それならよかった。じゃあ、急ごう。\n出発だ！",
  ui_story_5038_50381102_6_dialog_content = "本当に…行くのか？",
  ui_story_5038_50381102_7_dialog_content = "甲板にまで暗鬼が上がって来たんだ。\n海の中はもっと危険かもしれねえぞ。",
  ui_story_5038_50381102_8_dialog_content = "でも、船長だって海に飛び込んじゃったよ。",
  ui_story_5038_50381102_9_dialog_content = "ボクたちのことより、船長の方が心配だよ。",
  ui_story_5038_50381102_10_dialog_content = "行こう、PlayerName。",
  ui_story_5038_50381102_11_dialog_content = "うん！",
  ui_story_5038_50381102_12_dialog_content = "チビシッポは付いてきちゃだめだよ。",
  ui_story_5038_50381102_13_dialog_content = "ニャ～？",
  ui_story_5038_50381102_14_dialog_content = "小さな舟に乗ってると、\n海が広いって改めて実感するね。",
  ui_story_5038_50381102_15_dialog_content = "リンセイ、本当にリン家の船を見つけられると思う？",
  ui_story_5038_50381102_16_dialog_content = "手がかりが見つかったんだ。\nそう遠くはないはずだよ。",
  ui_story_5038_50381102_17_dialog_content = "でも…",
  ui_story_5038_50381102_18_dialog_content = "海の底に沈んでるんじゃないかって思ってるの？",
  ui_story_5038_50381102_19_dialog_content = "うん…",
  ui_story_5038_50381102_20_dialog_content = "前に見た船の残骸と同じで、\n部品だけが漂流してたからね…",
  ui_story_5038_50381102_21_dialog_content = "風に飛ばされたのかもしれないよ。",
  ui_story_5038_50381102_22_dialog_content = "暗鬼が船に上ってきて、騒ぎで外れたのかもしれないし…",
  ui_story_5038_50381102_23_dialog_content = "とにかく、そんなことは重要じゃないよ。\nこの近くにあるのは確かなんだ。",
  ui_story_5038_50381102_24_dialog_content = "どうしても見つけないと。",
  ui_story_5038_50381102_25_dialog_content = "アハハ…リン家の船のことに、相当自信があるんだね。",
  ui_story_5038_50381102_26_dialog_content = "当然だよ。だって「羅針盤」があるんだもん。",
  ui_story_5038_50381102_27_dialog_content = "（リンセイはずっと「羅針盤」を見つけようと焦っている）",
  ui_story_5038_50381102_28_dialog_content = "（でも、ユエとは状況がまた違う…）",
  ui_story_5038_50381102_29_dialog_content = "（彼女が焦るのは分かるけど、\nリンセイがここまで執着している理由が僕には分からない）",
  ui_story_5038_50381102_30_dialog_content = "（いつもの無邪気な顔じゃないから、気になるだけだろうか）",
  ui_story_5038_50381102_31_dialog_content = "これは…まずいなぁ。",
  ui_story_5038_50381102_32_dialog_content = "霧が出始めた…",
  ui_story_5038_50381102_33_dialog_content = "そうみたいだね。どんどん視界が悪くなってる。",
  ui_story_5038_50381102_34_dialog_content = "面倒だなぁ。\n風でも吹いてくれればいいのに。",
  ui_story_5038_50381102_35_dialog_content = "これじゃ探しようがないよ！",
  ui_story_5038_50381102_36_dialog_content = "ちょっと待って…\n船探しどころじゃない気がするんだけど…",
  ui_story_5038_50381102_37_dialog_content = "こんな見晴らしの悪さで、\nどうやって蜃風号に戻るの？",
  ui_story_5038_50381102_38_dialog_content = "どっちにあるか分かる？",
  ui_story_5038_50381102_39_dialog_content = "うーん、後ろじゃないの？",
  ui_story_5038_50381102_40_dialog_content = "いや、左かな？",
  ui_story_5038_50381102_41_dialog_content = "覚えてないんだね！",
  ui_story_5038_50381102_42_dialog_content = "万が一蜃風号を見失ったら…",
  ui_story_5038_50381102_43_dialog_content = "大丈夫だって。",
  ui_story_5038_50381102_44_dialog_content = "釣竿があるから、\n魚を釣って食べれば、何日かは生き延びられるよ。",
  ui_story_5038_50381102_45_dialog_content = "「何日か生き延びる」だけじゃ、足りないでしょ…",
  ui_story_5038_50381102_46_dialog_content = "それに、「羅針盤」が見つかれば――",
  ui_story_5038_50381102_47_dialog_content = "ボクたちの方が先に龍州に着くかもしれないよ。",
  ui_story_5038_50381102_48_dialog_content = "この霧じゃ、海の上を探すのは無理だよ。",
  ui_story_5038_50381102_49_dialog_content = "動かずに、霧が晴れるのを待ったらどうかな？",
  ui_story_5038_50381102_50_dialog_content = "うーん、それもそうだね…",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>バシャッ――</color>",
  ui_story_5038_50381102_52_dialog_content = "うわっ！！",
  ui_story_5038_50381102_53_dialog_content = "な、何！？",
  ui_story_5038_50381102_54_dialog_content = "全身びしょびしょだ！",
  ui_story_5038_50381102_55_dialog_content = "リンセイ！僕の後ろに…",
  ui_story_5038_50381102_56_dialog_content = "大きな声を出さないで。私よ。",
  ui_story_5038_50381102_57_dialog_content = "あ…船長？",
  ui_story_5038_50381102_58_dialog_content = "海から上がって来たの？",
  ui_story_5038_50381102_59_dialog_content = "他にどこから来るって言うの？",
  ui_story_5038_50381102_60_dialog_content = "ビックリさせないでよ！",
  ui_story_5038_50381102_61_dialog_content = "うう…びしょびしょで気持ち悪い…",
  ui_story_5038_50381102_62_dialog_content = "悪いけど、わざわざ海に来て水を怖がる人のことなんて\n気遣うのは慣れてないの。",
  ui_story_5038_50381102_63_dialog_content = "ひどい…",
  ui_story_5038_50381102_64_dialog_content = "それよりも、本題に入るわ。",
  ui_story_5038_50381102_65_dialog_content = "潜っている時、海底に沈没船の墓場を見つけたわ。",
  ui_story_5038_50381102_66_dialog_content = "うーん、この下にはやっぱり沈没船が…",
  ui_story_5038_50381102_67_dialog_content = "…いや、待って。海底まで潜ったってこと！？",
  ui_story_5038_50381102_68_dialog_content = "それぐらい出来なかったら、\nいきなり海に飛び込んだりしないわ。",
  ui_story_5038_50381102_69_dialog_content = "それよりも、そこにはたくさんの船があって、\nおおかたは商船だったわ。",
  ui_story_5038_50381102_70_dialog_content = "ただ、一回りしてみたけれど、\nリン家の船の残骸は見つからなかった。",
  ui_story_5038_50381102_71_dialog_content = "手がかりはなしか…",
  ui_story_5038_50381102_72_dialog_content = "海上で収穫はあった？",
  ui_story_5038_50381102_73_dialog_content = "いや、何も。",
  ui_story_5038_50381102_74_dialog_content = "夜でもともと暗かったのに、霧まで出てきたから…",
  ui_story_5038_50381102_75_dialog_content = "船を探すどころか、\n蜃風号がどっちにあったかも分からなくなっちゃったよ。",
  ui_story_5038_50381102_76_dialog_content = "そう。",
  ui_story_5038_50381102_77_dialog_content = "この霧じゃ、今日は何も見つけられなさそうね。",
  ui_story_5038_50381102_78_dialog_content = "戻りましょう。かいを私に。",
  ui_story_5038_50381102_79_dialog_content = "いいけど、蜃風号の位置が分かるの？",
  ui_story_5038_50381102_80_dialog_content = "当然よ。\n船長が船を見失ったりはしないの。",
  ui_story_5038_50381102_81_dialog_content = "よかった、安心したよ。",
  ui_story_5038_50381102_82_dialog_content = "じゃ、じゃあ急いでよ。\n早く火にあたらないと…",
  ui_story_5038_50381102_83_dialog_content = "ええ、任せて。",
  ui_story_5038_50381102_84_dialog_content = "（かいが海水をかき分けていく。\n僕やリンセイよりも、やっぱり彼女は舟をこぎ慣れてる）",
  ui_story_5038_50381102_85_dialog_content = "（あたりは真っ白で、方向が全くわからない。\nこの舟が前に進んでいるのかさえ、確信が持てなくなるぐらいだ）",
  ui_story_5038_50381102_86_dialog_content = "（でも、本当にこの霧の中で方向が分かってるんだろうか…？）",
  ui_story_5038_50381102_87_dialog_content = "（いや、分かるに決まってる。この小舟を見つけられるんだから、\n蜃風号ほど大きな船なら、造作もないはずだ）",
  ui_story_5038_50381102_88_dialog_content = "ハクション――",
  ui_story_5038_50381102_89_dialog_content = "うう…戻ったら、薬を煎じて飲まなきゃ…",
  ui_story_5038_50381102_90_dialog_content = "ん？あれは…",
  ui_story_5038_50381102_91_dialog_content = "ああ！無事に戻って来れた！",
  ui_story_5038_50381102_92_dialog_content = "ほんとだ！ここまで近づかないと分からないなんて…",
  ui_story_5038_50381102_93_dialog_content = "そうだね。そういえば、この角度から見る蜃風号は初めてだ。",
  ui_story_5038_50381102_94_dialog_content = "なかなか壮観だなぁ。",
  ui_story_5038_50381102_95_dialog_content = "急いで引き上げてもらおうよ。",
  ui_story_5038_50381102_96_dialog_content = "おーい、戻ったよ！",
  ui_story_5038_50381102_97_dialog_content = "ここだよ～！",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5038_50381102_99_dialog_content = "どうして誰も答えてくれないんだろ？\n寝ちゃったのかな？",
  ui_story_5038_50381102_100_dialog_content = "そうだね。ずいぶん静かだ。",
  ui_story_5038_50381102_101_dialog_content = "ねえ、誰か！聞こえる？",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5038_50381102_103_dialog_content = "おかしいな。\nけっこう大きな声を出したつもりだけど…",
  ui_story_5038_50381102_104_dialog_content = "霧で音まで聞こえづらくなってる、\nなんてことはないよね…",
  ui_story_5038_50381102_105_dialog_content = "…この船は…",
  ui_story_5038_50381102_106_dialog_content = "どうしたの？",
  ui_story_5038_50381102_107_dialog_content = "とにかく、上がってみましょう。",
  ui_story_5038_50381102_108_dialog_content = "前の方に下りている縄が有るわ。\n自力で上がりましょう。",
  ui_story_5038_50381201_1_dialog_content = "どうしたものか？\n急に濃い霧が出て来たのう。",
  ui_story_5038_50381201_2_dialog_content = "そうですね。船長もリンセイもPlayerNameも、\nまだ海の上です。このまま見失ったら…",
  ui_story_5038_50381201_3_dialog_content = "こんなに広い海で、探せるとは…",
  ui_story_5038_50381201_4_dialog_content = "海の上？どういうことじゃ？",
  ui_story_5038_50381201_5_dialog_content = "先代の蜃風号の手がかりが見つかったんですよ。\nそれで3人が船を下りて、探しに行ったんです。",
  ui_story_5038_50381201_6_dialog_content = "こんな時に限って、急に霧が出るとは…",
  ui_story_5038_50381201_7_dialog_content = "全員にたいまつを持たせろ、船べりに立って探すんだ。",
  ui_story_5038_50381201_8_dialog_content = "帆はもう下ろしてある。\nできるかぎり船が動かないようにするんだ。",
  ui_story_5038_50381201_9_dialog_content = "船長は海を知ってる、\n霧が出たとしても、戻ってこられる。",
  ui_story_5038_50381201_10_dialog_content = "だが、あの2人は…",
  ui_story_5038_50381201_11_dialog_content = "わらわとキュウを呼びつけるとは、いかなる用じゃ？",
  ui_story_5038_50381201_12_dialog_content = "3人の行方が知れぬ。\nわらわも捜索に協力せねばならん。",
  ui_story_5038_50381201_13_dialog_content = "こんな濃霧じゃ、\n目が一人分増えたところで変わりはしませんよ。",
  ui_story_5038_50381201_14_dialog_content = "それより、船の中で僕を助けていただきたいところですねぇ。",
  ui_story_5038_50381201_15_dialog_content = "何をたくらんでおる？",
  ui_story_5038_50381201_16_dialog_content = "シュウの旦那に話を聞くんですよ。",
  ui_story_5038_50381201_17_dialog_content = "お主一人では怖いと言う事か？",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ――</color>",
  ui_story_5038_50381201_19_dialog_content = "シュウの旦那、お休みですか？",
  ui_story_5038_50381201_20_dialog_content = "窓の外が霧で見えぬが、\n何かあったのか？",
  ui_story_5038_50381201_21_dialog_content = "船の衆の話じゃと、船長とリンセイ、PlayerNameが\n海に先代の蜃風号を探しに出たまま、行方知れずだそうな…",
  ui_story_5038_50381201_22_dialog_content = "それはなんとも、間の悪い霧だな。",
  ui_story_5038_50381201_23_dialog_content = "先代の蜃風号さえ見つかればよいのだが…",
  ui_story_5038_50381201_24_dialog_content = "見つけられなければ、海の上は危ないぞ。",
  ui_story_5038_50381201_25_dialog_content = "そうですねぇ。辺りにミズチウオもいますし…\nまさか、また船が襲われるなんてことにはならないでしょうねえ？",
  ui_story_5038_50381201_26_dialog_content = "海の中がどうなってるかも分かりゃあしませんし、\nこの蜃風号だって、どうなるか分かったものじゃあありません。",
  ui_story_5038_50381201_27_dialog_content = "ふむ…他人様の心配ばかりしておれぬか…",
  ui_story_5038_50381201_28_dialog_content = "また襲われでもすれば、今度はひとたまりもあるまい。",
  ui_story_5038_50381201_29_dialog_content = "そういう訳ですから、\nここは僕が蜃風号の未来を占いましょう。",
  ui_story_5038_50381201_30_dialog_content = "襲撃される理由さえ分かれば、\n事前に防ぐこともできますからねぇ。",
  ui_story_5038_50381201_31_dialog_content = "そのようなことが分かるのか？",
  ui_story_5038_50381201_32_dialog_content = "卦を立てるには天の時を見る必要がある…\nつまり、ちょうど今がその時と言う訳です。",
  ui_story_5038_50381201_33_dialog_content = "浅学の身の僕ではありますが、\nまぁ、おおかたは分かりますのでねぇ。",
  ui_story_5038_50381201_34_dialog_content = "では皆さん、失礼して…",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>サッ――サッ――</color>",
  ui_story_5038_50381201_36_dialog_content = "どうじゃ？何か分かったか？",
  ui_story_5038_50381201_37_dialog_content = "承蒙天恩、我が手にお示しあれ…",
  ui_story_5038_50381201_38_dialog_content = "来たる道、原初に戻らば、水の中より現れん…",
  ui_story_5038_50381201_39_dialog_content = "蜃風が襲われし所以、ここにあり…",
  ui_story_5038_50381201_40_dialog_content = "シュウの旦那…\n卦は旦那の名を指しているようですねぇ…？",
  ui_story_5038_50381201_41_dialog_content = "よい…しょ！",
  ui_story_5038_50381201_42_dialog_content = "PlayerName、縄を登るぐらいのことで\nボクの助けが必要なんて、なっさけないね～。",
  ui_story_5038_50381201_43_dialog_content = "悪いけど、皆が皆、こういうことが得意なわけじゃないんだよ。",
  ui_story_5038_50381201_44_dialog_content = "それはそうと、登って来られたのはいいけど…",
  ui_story_5038_50381201_45_dialog_content = "誰もいないね…",
  ui_story_5038_50381201_46_dialog_content = "どうしたんだろう？\n皆も僕たちを探しに海に出ちゃった？",
  ui_story_5038_50381201_47_dialog_content = "中を見てみようよ。\nもしかしたら霧が出たから、中に入ったのかもしれないし。",
  ui_story_5038_50381201_48_dialog_content = "あれ？船倉の入口って、ここじゃなかった？",
  ui_story_5038_50381201_49_dialog_content = "うーん、登って来たから方向を間違えてるのかな。\nやっぱりこっちだったかな…？",
  ui_story_5038_50381201_50_dialog_content = "違うわ。",
  ui_story_5038_50381201_51_dialog_content = "え？",
  ui_story_5038_50381201_52_dialog_content = "おかしいわ。",
  ui_story_5038_50381201_53_dialog_content = "帆柱も、舷も、甲板も…",
  ui_story_5038_50381201_54_dialog_content = "この船は蜃風号じゃない。",
  ui_story_5038_50381201_55_dialog_content = "後ろに気を付けて！！",
  ui_story_5038_50381201_56_dialog_content = "船の上に暗鬼…",
  ui_story_5038_50381201_57_dialog_content = "そうとう多いわね。",
  ui_story_5038_50381201_58_dialog_content = "まずい、囲まれてる…",
  ui_story_5038_50381201_59_dialog_content = "まずは左の敵を！",
  ui_story_5038_50381201_60_dialog_content = "分かったわ。",
  ui_story_5038_50381201_61_dialog_content = "こういう状況、慣れてるみたいね。",
  ui_story_5038_50381201_62_dialog_content = "当然だよ。夢の中でも暗鬼に襲われてるぐらいだからね。",
  ui_story_5038_50381201_63_dialog_content = "次は…",
  ui_story_5038_50381201_64_dialog_content = "分かった！",
  ui_story_5038_50381201_65_dialog_content = "え？何が分かったの？",
  ui_story_5038_50381201_66_dialog_content = "分かったよ！ここ、来たことある！",
  ui_story_5038_50381201_67_dialog_content = "蜃風号だ！先代の蜃風号！！",
  ui_story_5038_50381201_68_dialog_content = "え！？",
  ui_story_5038_50381201_69_dialog_content = "やはり…",
  ui_story_5038_50381201_70_dialog_content = "僕たち…偶然見つけたってこと？",
  ui_story_5038_50381201_71_dialog_content = "うん、間違いないよ！\nこの柵、ボクが折っちゃったやつだ！",
  ui_story_5038_50381201_72_dialog_content = "やった！ようやく見つかった！",
  ui_story_5038_50381201_73_dialog_content = "見つかったのはよかったけど、\n喜ぶにはまだ早いんじゃないかな…",
  ui_story_5038_50381201_74_dialog_content = "「羅針盤」は船倉の中だよ。\nどこにあるかは知ってるんだ。",
  ui_story_5038_50381201_75_dialog_content = "早く付いてきて！ボクが案内してあげる！",
  ui_story_5038_50381201_76_dialog_content = "ちょっと、勝手に走り回っちゃダメだよ！\nまだ暗鬼がいるかもしれないのに！",
  ui_story_5038_50381201_77_dialog_content = "一人はあぶな…",
  ui_story_5038_50381201_78_dialog_content = "あ、もう行っちゃった。",
  ui_story_5038_50381201_79_dialog_content = "早く早く！こっちだよ！",
  ui_story_5038_50381201_80_dialog_content = "聞くつもりはないようね。",
  ui_story_5038_50381201_81_dialog_content = "私たちも行きましょう。",
  ui_story_5038_50381201_82_dialog_content = "暗鬼ごときに、私は止められないわ。",
  ui_story_5038_50381202_1_dialog_content = "蜃風号が襲われたのはシュウ殿のせいと言いたいのか？\n大概にせい…",
  ui_story_5038_50381202_2_dialog_content = "その占いとやら、信用できるのか？",
  ui_story_5038_50381202_3_dialog_content = "ふふ…テンカン、それでここへ来たわけか。",
  ui_story_5038_50381202_4_dialog_content = "その卦はあらかじめ知っていたのであろうな？",
  ui_story_5038_50381202_5_dialog_content = "さすが、お見通しですか。",
  ui_story_5038_50381202_6_dialog_content = "ミズチウオが2度目に出た時、\n卦はもう見ていましてねぇ。",
  ui_story_5038_50381202_X6_dialog_content = "卦象は陰の虎と出ました。",
  ui_story_5038_50381202_X7_dialog_content = "ただ、その陰の虎というのが何を指しているのか、\nいくら考えても分からなかったんですよ。",
  ui_story_5038_50381202_X8_dialog_content = "でも、思いだしましてねぇ。\n「虎を持つ者、すなわち将軍なり」。",
  ui_story_5038_50381202_X9_dialog_content = "将軍は任命される時、その証明として「虎符」を授かる…\nつまり、卦象の指す人物は元将軍である旦那というワケですねぇ。",
  ui_story_5038_50381202_X10_dialog_content = "なかなか面白いではないか。続けるがいい。",
  ui_story_5038_50381202_X11_dialog_content = "旦那のお名前には蝶の相が有りますから…",
  ui_story_5038_50381202_7_dialog_content = "もしかすると、蝶の羽ばたきで生まれた小さい風が、\n巡り巡って嵐になったということかも知れませんねぇ。",
  ui_story_5038_50381202_8_dialog_content = "旦那から聞いた先代の蜃風号の話ですが…",
  ui_story_5038_50381202_9_dialog_content = "リン家の者が秘宝を海に持ち出し、\n賊もそれを追って、奪おうとしたとおっしゃいましたねぇ。",
  ui_story_5038_50381202_10_dialog_content = "…でも結局、最後に生き残ったのは、\n旦那とリンセイ、すなわちリン家の客人…",
  ui_story_5038_50381202_11_dialog_content = "お二人はいったい、\nこの事件でどういう役回りだったんでしょう？",
  ui_story_5038_50381202_12_dialog_content = "そこのところ、教えていただきたいところですねぇ。",
  ui_story_5038_50381202_13_dialog_content = "初めからそれを問いただしに来たのであろう？\nそうかしこまることは無い。",
  ui_story_5038_50381202_14_dialog_content = "殿下とキュウ殿も連れているのは、\nそれがしが逆上することを恐れてか？",
  ui_story_5038_50381202_15_dialog_content = "それで助けが要ると言ったわけか…",
  ui_story_5038_50381202_16_dialog_content = "シュウの旦那は両足が使えなくとも、\n武人としての気迫はいまだご健在…",
  ui_story_5038_50381202_17_dialog_content = "僕一人じゃあ、きっと気おされて\n口を開けなくなってしまいますからねぇ。",
  ui_story_5038_50381202_18_dialog_content = "よかろう。\n聞きたいと言うならば、しばらく付き合って進ぜよう。",
  ui_story_5038_50381202_19_dialog_content = "それがしも疑っておったのだ。\nミズチウオに襲われたことは、己のせいではないかと。",
  ui_story_5038_50381202_20_dialog_content = "あるいは…ミズチウオの異常そのものの発端が、\nそれがしではないか、とな。",
  ui_story_5038_50381202_21_dialog_content = "どういうことでしょう？",
  ui_story_5038_50381202_22_dialog_content = "まずは先代の蜃風号のことから話すとしよう…",
  ui_story_5038_50381202_23_dialog_content = "リン家の者が秘宝を持ち出し、海に出た。\n賊どもがそれを追いかけた。これに偽りはない。",
  ui_story_5038_50381202_24_dialog_content = "しかし、その時のそれがしは蜃風号にはいなかった。\n賊どもの背を追っていたからな。",
  ui_story_5038_50381202_25_dialog_content = "賊の後ろですか？",
  ui_story_5038_50381202_26_dialog_content = "当主とはリン家の家業を守ると、\n約束をしていたからな。",
  ui_story_5038_50381202_27_dialog_content = "約束を果たすためにそれがしは賊を追い、\n奴らの後を追って、蜃風号に乗り込んだ。",
  ui_story_5038_50381202_28_dialog_content = "初めはひそかに羅針盤だけでも取り返し、\n船で大陸に戻ろうと考えておったのだが…",
  ui_story_5038_50381202_29_dialog_content = "あの夜、船で起こったことは\nそれがしの想像を超えていた。",
  ui_story_5038_50381202_30_dialog_content = "賊は蜃風号を抑えたものの、\n「羅針盤」の所在は分からなかった…",
  ui_story_5038_50381202_31_dialog_content = "そこで「羅針盤」のありかを聞き出すため、\n悪辣極まる方法でリン家の者たちをいたぶり始めたのだ。",
  ui_story_5038_50381202_32_dialog_content = "海の上には、法も公もない。\n賊どもには好都合だ。",
  ui_story_5038_50381202_33_dialog_content = "それがしが駆け付けた時には、\nリン家の者は一人残らず犠牲になっておった…",
  ui_story_5038_50381202_34_dialog_content = "その時、それがしは悟った。\nただ「羅針盤」を取り返すだけでは意味がないと。",
  ui_story_5038_50381202_35_dialog_content = "リン家の勢力が削がれた今、\n「羅針盤」をまだ持っているとなれば、さらなる災いを招く。",
  ui_story_5038_50381202_36_dialog_content = "まことにリン家を守りたいと願うならば、\n「羅針盤」を消すほかない。",
  ui_story_5038_50381202_37_dialog_content = "消す？\nまさか旦那、羅針盤を捨ててしまったと？",
  ui_story_5038_50381202_38_dialog_content = "むろん、そのようなことはせぬ。\n羅針盤はリン家を支えるもの、リン家再興の唯一の希望だ。",
  ui_story_5038_50381202_39_dialog_content = "「羅針盤」は何としても守らねばならぬ。\nそして、誰かが羅針盤の名を口にすることもまた、金輪際あってはならぬ。",
  ui_story_5038_50381202_40_dialog_content = "誰も羅針盤の名を口にしない…",
  ui_story_5038_50381202_41_dialog_content = "…まさか、旦那…",
  ui_story_5038_50381202_42_dialog_content = "いかにも。賊どもをすべて亡き者とし、口を封じた。",
  ui_story_5038_50381202_43_dialog_content = "武将として長く戦場を駆け回って来たが…\nあれほど心苦しい戦いは初めてであった。",
  ui_story_5038_50381202_44_dialog_content = "賊どもは所詮、戦士でもない。\nたばになっても太刀打ちできぬと悟り、ひざまずいて命乞いをし始めた。",
  ui_story_5038_50381202_45_dialog_content = "ののしり喚き、泣き叫び、\n絶望の中で、ありとあらゆる醜さをさらけ出しながらな。",
  ui_story_5038_50381202_46_dialog_content = "賊どもは戦に勝とうとしていたのではない。\nただ生きようとしていただけだ。",
  ui_story_5038_50381202_47_dialog_content = "賊になった理由は様々だろう。\n極悪非道の者もおれば、暮らしに窮して道を踏み外した者もおったはずだ。",
  ui_story_5038_50381202_48_dialog_content = "だが、それを見分けている余地はない。\n全ての口を塞ぐしかないからだ。",
  ui_story_5038_50381202_49_dialog_content = "…全ては「羅針盤」を守るため？",
  ui_story_5038_50381202_50_dialog_content = "左様、そう己に言い聞かせた。",
  ui_story_5038_50381202_51_dialog_content = "だが、ふと思う時がある。\nそれがしはとてつもないことをしてしまったのではないかと。",
  ui_story_5038_50381202_52_dialog_content = "だが、刀を鮮血に染めた瞬間から、\nそれがしはもう後戻りなどできぬのだ。",
  ui_story_5038_50381202_53_dialog_content = "そういうことでしたか…",
  ui_story_5038_50381202_54_dialog_content = "嵐に遭ったとしか言わなかったことは、\n確かに皆を騙したことになる。",
  ui_story_5038_50381202_55_dialog_content = "それがしとリンセイが海に落ち、漂流することになったのは、\nミズチウオの襲撃が原因だったのだ。",
  ui_story_5038_50381202_56_dialog_content = "またミズチウオ…",
  ui_story_5038_50381202_57_dialog_content = "ゆえに、ミズチウオの襲撃は\nそれがしが原因ではないかと考えていたのだ。",
  ui_story_5038_50381202_58_dialog_content = "この蜃風号が襲われた時の様子は、\n先代の船で起こったことと極めて似通っている。",
  ui_story_5038_50381202_59_dialog_content = "「羅針盤」の捜索とは関係のないことと、\n話さなかったのだが…",
  ui_story_5038_50381202_60_dialog_content = "尋ねられたからには話すことにした。\n年寄りの昔話を聞いたとでも思ってくれ。",
  ui_story_5038_50381202_61_dialog_content = "そんな話、誰だってしたくないでしょうねぇ。\n申し訳ない、僕が余計なことを聞いてしまったばっかりに…",
  ui_story_5038_50381202_62_dialog_content = "構わぬ。こんな時には皆が力を合わせねばならん。\nわだかまりが解けたのならば、それでよい。",
  ui_story_5038_50381202_63_dialog_content = "そうですねぇ…今は力を合わせなければならない時です。\n旦那の言う通りだ。",
  ui_story_5038_50381202_64_dialog_content = "僕も目の前の窮地を乗り切るために、\n頭を使わないと。",
  ui_story_5038_50381202_65_dialog_content = "この霧では何をしようにもかなわぬ。",
  ui_story_5038_50381202_66_dialog_content = "だが、リンセイが懸命に「羅針盤」を探しておる。\nあやつには祟霊だけがもつ、勘とでも言う何かがある。",
  ui_story_5038_50381202_67_dialog_content = "リンセイが海に飛び出していったと言うのなら、\n先代の蜃風号はこの近くにあるに違いない。",
  ui_story_5038_50381202_68_dialog_content = "霧が晴れる頃には、\n「羅針盤」を持って戻って来るやもしれぬな。",
  ui_story_5038_50381202_69_dialog_content = "そううまくいけばいいんですがねぇ…",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5038_50381202_71_dialog_content = "何事だ…？",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>ドカン！！</color></size>",
  ui_story_5038_50381202_73_dialog_content = "なんじゃ！？",
  ui_story_5038_50381202_74_dialog_content = "何ごとでしょう、\nずいぶん揺れますねぇ？",
  ui_story_5038_50381202_75_dialog_content = "シュウの旦那は…",
  ui_story_5038_50381202_76_dialog_content = "大事ない。急いで甲板に出て\n状況を確かめるのだ！",
  ui_story_5038_50381202_77_dialog_content = "了解です！旦那はここで…",
  ui_story_5038_50381202_78_dialog_content = "<size=45>きゃあああああ！！！</size>",
  ui_story_5038_50381202_79_dialog_content = "なんで叫んでるんです！？",
  ui_story_5038_50381202_80_dialog_content = "ふ、船が…",
  ui_story_5038_50381202_81_dialog_content = "<size=50>船にぶつかられたの！！</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>ドカン――</color>",
  ui_story_5038_50381301_2_dialog_content = "な、何の音！？",
  ui_story_5038_50381301_3_dialog_content = "船首が何かにぶつかったようね。\n大丈夫？",
  ui_story_5038_50381301_4_dialog_content = "大丈夫だよ。船で揺られるのにはもう慣れてるから。",
  ui_story_5038_50381301_5_dialog_content = "でも、衝突って…何にぶつかったんだろう？\n座礁でもしたのかな？",
  ui_story_5038_50381301_6_dialog_content = "早く、もうすぐそこだよ。",
  ui_story_5038_50381301_7_dialog_content = "あ、でも…鍵は開けられる？",
  ui_story_5038_50381301_8_dialog_content = "扉の鍵がけっこう…",
  ui_story_5038_50381301_9_dialog_content = "切って開けるわ。",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5038_50381301_11_dialog_content = "うわわ！ボクごと切る気！？",
  ui_story_5038_50381301_12_dialog_content = "入らないの？",
  ui_story_5038_50381301_13_dialog_content = "うう…",
  ui_story_5038_50381301_14_dialog_content = "まあいいや、とにかく、入ろう。\nずっと探してたお宝、どんなものか見せてあげるよ。",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5038_50381301_16_dialog_content = "うわぁ…",
  ui_story_5038_50381301_17_dialog_content = "飾りの凝った部屋だね！",
  ui_story_5038_50381301_18_dialog_content = "…龍州のお金持ちのお屋敷って、\nこんな感じなんだろうなぁ。",
  ui_story_5038_50381301_19_dialog_content = "この部屋は…",
  ui_story_5038_50381301_20_dialog_content = "私の知っている頃のリン家の屋敷と似ているわ。",
  ui_story_5038_50381301_21_dialog_content = "屋敷を処分した後で、\n骨董や書画は船に移していたようね。",
  ui_story_5038_50381301_22_dialog_content = "知っている頃の屋敷？",
  ui_story_5038_50381301_23_dialog_content = "幼い頃にリン家の屋敷に住んでいたことがあるの。",
  ui_story_5038_50381301_24_dialog_content = "その後、リン家商会は一度没落したのよ。\n財産はすべて抵当に取られ、屋敷も他の人の手に渡ったわ。",
  ui_story_5038_50381301_25_dialog_content = "こんなところで懐かしいものを見ることになるとは、\n思ってもいなかったわね。",
  ui_story_5038_50381301_26_dialog_content = "子どもの頃に住んでいた家か…\n確かに懐かしいだろうね…",
  ui_story_5038_50381301_27_dialog_content = "その事はいいわ。",
  ui_story_5038_50381301_28_dialog_content = "それよりリンセイ、「羅針盤」は…",
  ui_story_5038_50381301_29_dialog_content = "そんな…そんなはずない…",
  ui_story_5038_50381301_30_dialog_content = "リンセイ、どうしたの？",
  ui_story_5038_50381301_31_dialog_content = "ないんだ…どうして…？",
  ui_story_5038_50381301_32_dialog_content = "ない？",
  ui_story_5038_50381301_33_dialog_content = "他の場所に隠してあるんじゃないの？",
  ui_story_5038_50381301_34_dialog_content = "リンセイ、「羅針盤」がどんなものか、\n教えてくれる？一緒に探そう。",
  ui_story_5038_50381301_35_dialog_content = "でも…いったいどこに隠れるっていうの？",
  ui_story_5038_50381301_36_dialog_content = "水槽の外じゃ生きていけないのに…",
  ui_story_5038_50381301_37_dialog_content = "生きていけない？",
  ui_story_5038_50381301_38_dialog_content = "ちょっと待って…もしかして、\n「羅針盤」って僕が思ってるようなものじゃないのかな…？",
  ui_story_5038_50381301_39_dialog_content = "うん、そうだよ。\n「羅針盤」はお魚だもん。",
  ui_story_5038_50381301_40_dialog_content = "え！？",
  ui_story_5038_50381301_41_dialog_content = "ヒッヒッヒッ…",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>ガシャン！</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>バリン！</color>",
  ui_story_5038_50381301_44_dialog_content = "な、何！？何かが割れた！？",
  ui_story_5038_50381301_45_dialog_content = "陶磁器が割れたのね。\nはっきり見えたわけじゃないけど…",
  ui_story_5038_50381301_46_dialog_content = "あっ！誰か、逃げ出したよ！",
  ui_story_5038_50381301_47_dialog_content = "誰かって、他に誰かいたの！？",
  ui_story_5038_50381301_48_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_5038_50381301_49_dialog_content = "扉が閉められた！？",
  ui_story_5038_50381301_50_dialog_content = "外にいる！",
  ui_story_5038_50381301_51_dialog_content = "でも、いったい誰が…",
  ui_story_5038_50381301_52_dialog_content = "カンシャ…",
  ui_story_5038_50381301_53_dialog_content = "！？",
  ui_story_5038_50381301_54_dialog_content = "カンシャ、カンシャ。",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ…</color>",
  ui_story_5038_50381301_56_dialog_content = "いったい何が…？",
  ui_story_5038_50381301_57_dialog_content = "逃げたよ！追いかけなくちゃ！",
  ui_story_5038_50381301_58_dialog_content = "扉が…船長、開けられる？",
  ui_story_5038_50381301_59_dialog_content = "やってみたけど、無理で。\n外側を何か重いもので抑えられてる。",
  ui_story_5038_50381301_60_dialog_content = "たいへんだ、どうしよう…\n早く追いつかないとまずいのに…",
  ui_story_5038_50381301_61_dialog_content = "何か、いい方法は…",
  ui_story_5038_50381301_62_dialog_content = "3人同時に体をぶつければ…",
  ui_story_5038_50381301_63_dialog_content = "無理よ。3人じゃとても足りないわ。",
  ui_story_5038_50381301_64_dialog_content = "まずは落ち着いて。",
  ui_story_5038_50381301_65_dialog_content = "落ち着いてなんかいられないよ！\n逃げられちゃう！",
  ui_story_5038_50381301_66_dialog_content = "外は海なんだよ！\n海に逃げられたら、どうやって探せば…",
  ui_story_5038_50381301_67_dialog_content = "ねえ…もしかしたら、開けられるかもしれないよ。",
  ui_story_5038_50381301_68_dialog_content = "え！ほんとに！？",
  ui_story_5038_50381301_69_dialog_content = "でも、少し時間がかかると思う。",
  ui_story_5038_50381301_70_dialog_content = "少し待ってて…",
  ui_story_5038_50381301_71_dialog_content = "（思い付きだけど…）",
  ui_story_5038_50381301_72_dialog_content = "（この場は試すしかない！）",
  ui_story_5038_50381301_73_option_content = "強制感知！",
  ui_story_5038_50381301_74_dialog_content = "PlayerName、立ったまま動かなくなったわ。\nきっと能力を使っているのね。",
  ui_story_5038_50381301_X74_dialog_content = "今のうちに、聞かせてもらおうかしら。\n「羅針盤」に何があったの？",
  ui_story_5038_50381301_75_dialog_content = "いま逃げて行ったのはいったい何者？",
  ui_story_5038_50381301_76_dialog_content = "うーん…何から話せばいいのかな…",
  ui_story_5038_50381301_77_dialog_content = "ボクも逃げていった人が直接見えたわけじゃないけど…",
  ui_story_5038_50381301_78_dialog_content = "ただ、この部屋から出て行ったってことは、\n可能性は1つしかない…",
  ui_story_5038_50381301_79_dialog_content = "逃げたのは「羅針盤」だよ。",
  ui_story_5038_50381301_80_dialog_content = "「羅針盤」が逃げた！？",
  ui_story_5038_50381301_81_dialog_content = "魚だと言ったり、人だと言ったり…\nいったいどういうこと？",
  ui_story_5038_50381301_82_dialog_content = "「羅針盤」は確かにお魚なんだ。\n特別なミズチウオなんだよ。",
  ui_story_5038_50381301_83_dialog_content = "でも、お魚だからといって、\nいつまでもお魚の姿でいるとは限らない。",
  ui_story_5038_50381301_84_dialog_content = "ほら、ボクだってネコでしょ？",
  ui_story_5038_50381301_85_dialog_content = "つまり…祟霊だと言うこと？",
  ui_story_5038_50381301_86_dialog_content = "それしか考えられないよ。",
  ui_story_5038_50381301_87_dialog_content = "先代の蜃風号が漂流してる間に、\n羅針盤が祟霊になったんだ。",
  ui_story_5038_50381301_88_dialog_content = "新しい力に目覚めたから、水から出られるようになった。\n水槽の中にいる必要もなくなった…",
  ui_story_5038_50381301_89_dialog_content = "でも、鍵のかかった船室を出ることまでは、\nできなかったんじゃないかな。",
  ui_story_5038_50381301_90_dialog_content = "ボクたちが鍵を開けて、入ってくるまでは…",
  ui_story_5038_50381301_91_dialog_content = "…そういうことね…",
  ui_story_5038_50381301_92_dialog_content = "「羅針盤」が魚だったなんて…\nだけど、魚がどう航海の役にたつの？",
  ui_story_5038_50381301_93_dialog_content = "船長、リン家の人だったんでしょ。\nじゃ、ミズチウオについては詳しいよね。",
  ui_story_5038_50381301_94_dialog_content = "ミズチウオはヌシに率いられて、集団行動をする。",
  ui_story_5038_50381301_95_dialog_content = "「羅針盤」が、そのヌシなんだよ。",
  ui_story_5038_50381301_96_dialog_content = "ヌシ…",
  ui_story_5038_50381301_97_dialog_content = "どうりで…ミズチウオがこの辺りから離れなかったのね。",
  ui_story_5038_50381301_98_dialog_content = "あなたとシュウ様はそれで\n羅針盤がここにあると分かっていた。",
  ui_story_5038_50381301_99_dialog_content = "そういうこと。",
  ui_story_5038_50381301_100_dialog_content = "そうだったのね…分かったわ。",
  ui_story_5038_50381301_101_dialog_content = "ミズチウオは2つの大陸の間を往復している。",
  ui_story_5038_50381301_102_dialog_content = "ミズチウオのヌシを飼うことで、\nその習性を利用していたということね。",
  ui_story_5038_50381301_103_dialog_content = "ヌシが手元にいれば、ミズチウオの群れが、\n航海を手伝ってくれる…",
  ui_story_5038_50381301_104_dialog_content = "だいたい合ってるよ。",
  ui_story_5038_50381301_105_dialog_content = "リン家はミズチウオのヌシを\nずっと船に閉じ込めてた。",
  ui_story_5038_50381301_106_dialog_content = "その後から生まれてきたミズチウオたちは、\n先代の蜃風号そのものがヌシだと思うようになって…",
  ui_story_5038_50381301_107_dialog_content = "航海のたびに、ミズチウオの群れが船の後ろについてきて、\n船を助けてくれてたってこと。",
  ui_story_5038_50381301_108_dialog_content = "だから、リン家の船は海で迷う心配も、\n嵐に遭う心配もなかったんだ。",
  ui_story_5038_50381301_109_dialog_content = "ミズチウオの群れが必ず目的地まで送り届けてくれるからね。",
  ui_story_5038_50381301_110_dialog_content = "…どうして、誰もそのことを私に教えてくれなかったの…？",
  ui_story_5038_50381301_111_dialog_content = "リン家も…あなたも、シュウ様も…",
  ui_story_5038_50381301_112_dialog_content = "はぁ…シュウさんに言われてたんだ。\n難しくてボクにはよく分からなかったけど。",
  ui_story_5038_50381301_113_dialog_content = "複雑な事情があるとか、「富はひけらかすものじゃない」とか、\n「リン家の名誉」がとか…",
  ui_story_5038_50381301_114_dialog_content = "だったら、何も言わないのが一番いいかなって。",
  ui_story_5038_50381301_115_dialog_content = "…",
  ui_story_5038_50381301_116_dialog_content = "ボクはただ…羅針盤に悪いとは思ってた。",
  ui_story_5038_50381301_117_dialog_content = "前の蜃風号に乗ったあの日から、\nボクも「羅針盤」を閉じ込めて利用してきた人たちの共犯だからね。",
  ui_story_5038_50381301_118_dialog_content = "でも、何が起こるか分からない海が相手じゃ、\n例え良くないと思ってても、それに頼るしかない。",
  ui_story_5038_50381301_119_dialog_content = "「羅針盤」って物みたいに呼んでたのも、\nその方が気が楽だったから…",
  ui_story_5038_50381301_120_dialog_content = "罪悪感ね…",
  ui_story_5038_50381301_121_dialog_content = "立派な考えだと思うわ。",
  ui_story_5038_50381301_122_dialog_content = "たぶん、心の中では友達だと思ってたんだと思う。",
  ui_story_5038_50381301_123_dialog_content = "そうだ。あの子の名前、「イヨウ」って言うんだ。",
  ui_story_5038_50381301_124_dialog_content = "イヨウ…覚えたわ。",
  ui_story_5038_50381301_125_dialog_content = "あの…ちょっといいかな。",
  ui_story_5038_50381301_126_dialog_content = "たぶん、うまくいったと思う。",
  ui_story_5038_50381301_127_dialog_content = "うまくいった？扉が開いたの！？",
  ui_story_5038_50381301_128_dialog_content = "ええと、もうすぐ開くよ。",
  ui_story_5038_50381301_129_dialog_content = "へ～！キミもなかなかやるじゃない！",
  ui_story_5038_50381301_130_dialog_content = "ただ、準備しておいてね。",
  ui_story_5038_50381301_131_dialog_content = "準備？何を？",
  ui_story_5038_50381301_132_dialog_content = "来た！",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_5038_50381301_134_dialog_content = "ガアァ！！！",
  ui_story_5038_50381301_135_dialog_content = "うわああ！もう、びっくりしたなぁ！",
  ui_story_5038_50381301_136_dialog_content = "どうして暗鬼が…？",
  ui_story_5038_50381301_137_dialog_content = "…もしかして、これが扉を開ける方法？",
  ui_story_5038_50381301_138_dialog_content = "暗鬼をわざと引きつけて、扉を破らせたってこと？",
  ui_story_5038_50381301_139_dialog_content = "うん…乱暴な方法だけど、\n扉は開いたでしょ？",
  ui_story_5038_50381301_140_dialog_content = "悪くないわね。\n暗鬼の方が扉より斬りやすいもの。",
  ui_story_5038_50381301_141_dialog_content = "片づけるわよ！",
  ui_story_5038_50381302_1_dialog_content = "何ごとです！？",
  ui_story_5038_50381302_2_dialog_content = "暗鬼よ！暗鬼が甲板に上がってきたわ！",
  ui_story_5038_50381302_3_dialog_content = "全部後ろの船からよ！",
  ui_story_5038_50381302_4_dialog_content = "グア――！",
  ui_story_5038_50381302_5_dialog_content = "汚らわしい、散れ！",
  ui_story_5038_50381302_6_dialog_content = "グァ…",
  ui_story_5038_50381302_7_dialog_content = "数が多いのう…",
  ui_story_5038_50381302_8_dialog_content = "殿下、おさがりください。",
  ui_story_5038_50381302_9_dialog_content = "汚れ仕事はこのキュウにお任せを。",
  ui_story_5038_50381302_10_dialog_content = "全員、船尾に集まるのだ！",
  ui_story_5038_50381302_11_dialog_content = "暗鬼をここで食い止める！\n好き勝手はさせん！",
  ui_story_5038_50381302_12_dialog_content = "はい！",
  ui_story_5038_50381302_13_dialog_content = "これはどういうことじゃ？",
  ui_story_5038_50381302_14_dialog_content = "暗鬼を大量に乗せた船が、\n不意に衝突してくるなどと…",
  ui_story_5038_50381302_15_dialog_content = "この船は…",
  ui_story_5038_50381302_16_dialog_content = "濃霧で見通しが利かぬゆえ、\n波に乗って流されてきたのやもしれぬな。",
  ui_story_5038_50381302_17_dialog_content = "まずいぞ！帆柱を狙ってやがる！",
  ui_story_5038_50381302_18_dialog_content = "気を付けて！甲板もあちこちやられてる！",
  ui_story_5038_50381302_19_dialog_content = "困りましたねぇ…このままじゃあ、らちが明きません。\n何か策を考えないと。",
  ui_story_5038_50381302_20_dialog_content = "忌々しい暗鬼どもめ！",
  ui_story_5038_50381302_21_dialog_content = "キュウ、急ぐぞ！",
  ui_story_5038_50381302_22_dialog_content = "待たれよ。",
  ui_story_5038_50381302_23_dialog_content = "なんじゃ？",
  ui_story_5038_50381302_24_dialog_content = "このまま蜃風号の上で戦っては、\n船体を傷つけるだけだ。",
  ui_story_5038_50381302_25_dialog_content = "戦場を移さねばならん。",
  ui_story_5038_50381302_26_dialog_content = "戦場を移す？それはどういう…",
  ui_story_5038_50381302_27_dialog_content = "渡し板を出せ！向こうの船に移る！",
  ui_story_5038_50381302_28_dialog_content = "この火は、あの船で燃やさねばならん！",
  ui_story_5038_50381401_1_dialog_content = "シュウ殿、お主の身体では動けまい！\n蜃風号に残られよ！",
  ui_story_5038_50381401_2_dialog_content = "暗鬼どもの始末はわらわどもで引き受ける！",
  ui_story_5038_50381401_3_dialog_content = "わざわざケガをしに行く必要は無いと思いますがねぇ。",
  ui_story_5038_50381401_4_dialog_content = "案ずるな。",
  ui_story_5038_50381401_5_dialog_content = "貴公らの足を引っ張るようなら、\n最初からついて行ったりはせぬ。",
  ui_story_5038_50381401_6_dialog_content = "（間違いない、これは先代の蜃風号だ）",
  ui_story_5038_50381401_7_dialog_content = "（「羅針盤」は目の前！なんとしても…）",
  ui_story_5038_50381401_8_dialog_content = "（ご当主よ、約束は必ず果たしてみせるぞ）",
  ui_story_5038_50381401_9_dialog_content = "殿下、暗鬼に取り囲まれます。",
  ui_story_5038_50381401_10_dialog_content = "蜃風号に乗り込んできた以上の数です。",
  ui_story_5038_50381401_11_dialog_content = "都合がよいわ、この場でわらわが…",
  ui_story_5038_50381401_12_dialog_content = "お二人とも、退がっておられよ。",
  ui_story_5038_50381401_13_dialog_content = "けがをするぞ。",
  ui_story_5038_50381401_14_dialog_content = "シュウ殿、何を…",
  ui_story_5038_50381401_15_dialog_content = "<size=50>炎火焚尽、諸悪断滅！</size>",
  ui_story_5038_50381401_16_dialog_content = "殿下！",
  ui_story_5038_50381401_17_dialog_content = "グガアアアアア！！",
  ui_story_5038_50381401_18_dialog_content = "ほ、大した火勢じゃ！",
  ui_story_5038_50381401_19_dialog_content = "暗鬼どもがみな火に包まれてしもうた！",
  ui_story_5038_50381401_20_dialog_content = "霧も吹き飛んでしもうたわ…",
  ui_story_5038_50381401_21_dialog_content = "シュウ様が場を移すと言った理由が分かりました。",
  ui_story_5038_50381401_22_dialog_content = "この威力では…蜃風号の上で放つわけにはまいりませんね。",
  ui_story_5038_50381401_23_dialog_content = "この船は海の上を長らく漂流しておった。\n風に蝕まれ、波に打たれ…",
  ui_story_5038_50381401_24_dialog_content = "骨であった部分はすでに朽ち果て、\n残るは枯れはてた身体のみ…",
  ui_story_5038_50381401_25_dialog_content = "火を放てば、当然激しく燃え盛るであろうな。",
  ui_story_5038_50381401_26_dialog_content = "好機じゃ、火に乗じて、\n暗鬼どもに引導を渡してくれようぞ！",
  ui_story_5038_50381401_27_dialog_content = "疾く蜃風号を戻って助けねばならぬ！",
  ui_story_5038_50381401_28_dialog_content = "殿下、お気を付けを！\n甲板も火がついております。崩落のおそれがあるかと…",
  ui_story_5038_50381401_29_dialog_content = "む、確かにその通りじゃな…",
  ui_story_5038_50381401_30_dialog_content = "キュウ、互いに掴まって歩くとするか。",
  ui_story_5038_50381401_31_dialog_content = "いずれかの足下が崩れても、もう一方が支えられるじゃろう。",
  ui_story_5038_50381401_32_dialog_content = "お互いに…",
  ui_story_5038_50381401_33_dialog_content = "は、殿下のおおせのままに。",
  ui_story_5038_50381401_34_dialog_content = "それじゃ、僕がお二人の先導を務めましょうかねぇ。",
  ui_story_5038_50381401_35_dialog_content = "うむ、進むぞ。",
  ui_story_5038_50381401_36_dialog_content = "それがしは暗鬼の始末以外にも、\nやらねばならんことがある。",
  ui_story_5038_50381401_37_dialog_content = "この船でか…？\nいかようなことじゃ？",
  ui_story_5038_50381401_38_dialog_content = "それがしの目が確かならば、\nこれは先代の蜃風号だ。",
  ui_story_5038_50381401_39_dialog_content = "色々と因縁があるのでな。",
  ui_story_5038_50381401_40_dialog_content = "この船が、先代の…",
  ui_story_5038_50381401_41_dialog_content = "中に探し物がある。",
  ui_story_5038_50381401_42_dialog_content = "船が燃え尽きる前に、\n必ず持ち出さねばならん。",
  ui_story_5038_50381401_43_dialog_content = "さように重要なものなのか？",
  ui_story_5038_50381401_44_dialog_content = "うむ、我らを龍州まで送り届けてくれる。",
  ui_story_5038_50381401_45_dialog_content = "（「羅針盤」は長く捨て置かれていた…\n無事だとよいが…）",
  ui_story_5038_50381401_46_dialog_content = "（それにしても、情けないことだ）",
  ui_story_5038_50381401_47_dialog_content = "（広大な大陸を結ぶ航海が、\n1匹の魚だのみとは…）",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ…</color>",
  ui_story_5038_50381401_49_dialog_content = "む？",
  ui_story_5038_50381401_50_dialog_content = "なんぞ音が聞こえたな？",
  ui_story_5038_50381401_51_dialog_content = "暗鬼が隠れておるのか？",
  ui_story_5038_50381401_52_dialog_content = "いいえ、殿下。この音は…",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>タッ、タッ…</color>",
  ui_story_5038_50381401_54_dialog_content = "足音です。",
  ui_story_5038_50381401_55_dialog_content = "足音？わらわたち以外に誰かおるというのか？",
  ui_story_5038_50381401_56_dialog_content = "オマエ、カ。",
  ui_story_5038_50381401_57_dialog_content = "！！！",
  ui_story_5038_50381401_58_dialog_content = "いったい誰の声です！？",
  ui_story_5038_50381401_59_dialog_content = "話があるなら、出てきて…",
  ui_story_5038_50381401_60_dialog_content = "「束」――",
  ui_story_5038_50381401_61_dialog_content = "うっ…！？",
  ui_story_5038_50381401_62_dialog_content = "殿下！しっかりお掴まりください！",
  ui_story_5038_50381401_63_dialog_content = "いかん！",
  ui_story_5038_50381401_64_dialog_content = "シュウ殿が――",
  ui_story_5038_50381401_65_dialog_content = "ゴホ、ゴホッ…",
  ui_story_5038_50381401_66_dialog_content = "何者だ？",
  ui_story_5038_50381401_67_dialog_content = "オマエ、知ッテル。",
  ui_story_5038_50381401_68_dialog_content = "それがしはお主のことなど…",
  ui_story_5038_50381401_69_dialog_content = "…いや、待て、その尾は…！",
  ui_story_5038_50381401_70_dialog_content = "オマエ、船ニ、イタ。",
  ui_story_5038_50381401_71_dialog_content = "ミズチウオの尾…",
  ui_story_5038_50381401_72_dialog_content = "それはリン家の者の証だ。\n貴公、リンの家人か？",
  ui_story_5038_50381401_73_dialog_content = "オマエ、リン家、ナカマ。",
  ui_story_5038_50381401_74_dialog_content = "いや、リン家の者であるはずがない…",
  ui_story_5038_50381401_75_dialog_content = "あの時、船に乗っていたリン家の者は一人残らず…",
  ui_story_5038_50381401_76_dialog_content = "ならば、ここにあるものと言えば、リン家の「財産」…",
  ui_story_5038_50381401_77_dialog_content = "オマエノ、ナマエ…",
  ui_story_5038_50381401_78_dialog_content = "チュウ、シュウ。",
  ui_story_5038_50381401_79_dialog_content = "やはりそうか。お主は…",
  ui_story_5038_50381401_80_dialog_content = "リン家にとって最も重要な秘宝…",
  ui_story_5038_50381401_81_dialog_content = "「イヨウ」だな。",
  ui_story_5038_50381401_82_dialog_content = "あの童（わっぱ）、何者でしょうねぇ？\nシュウの旦那を傷めつけられるなんて…",
  ui_story_5038_50381401_83_dialog_content = "お気を付けを。只者ではない…",
  ui_story_5038_50381401_84_dialog_content = "年端も行かぬ子供のように見えるが…",
  ui_story_5038_50381401_85_dialog_content = "まさか…祟霊か？",
  ui_story_5038_50381401_86_dialog_content = "そのような姿になっているとは思わなんだな…",
  ui_story_5038_50381401_87_dialog_content = "なぜゆえそれがしを攻撃する？",
  ui_story_5038_50381401_88_dialog_content = "リン家、ユルサナイ。",
  ui_story_5038_50381401_89_dialog_content = "…やはり、恨まれていたか。",
  ui_story_5038_50381401_90_dialog_content = "閉じ込められていればそうもなるか…",
  ui_story_5038_50381401_91_dialog_content = "船、イルヤツ、ミンナ…",
  ui_story_5038_50381401_92_dialog_content = "ユルサナイ。",
  ui_story_5038_50381401_93_dialog_content = "それがしもリン家の者も、\nそなたが恨みを抱いているであろうことは予想していた。",
  ui_story_5038_50381401_94_dialog_content = "直接恨みをぶつけられる日が来るとは、\n思っておらんかったがな…",
  ui_story_5038_50381401_95_dialog_content = "船、イチバン、ユルサナイ。",
  ui_story_5038_50381401_96_dialog_content = "恨みたいだけ恨むがよい。\nそなたに許された当然の権利だ。",
  ui_story_5038_50381401_97_dialog_content = "前人の遺産を後人が受け継ぎ、\n前人の借りも後人が背負う。",
  ui_story_5038_50381401_98_dialog_content = "そして運の悪い者が、その板挟みに遭う。",
  ui_story_5038_50381401_99_dialog_content = "…ご当主よ、またお主に貸しが増えそうだな。",
  ui_story_5038_50381401_100_dialog_content = "オマエラ、ミンナ…",
  ui_story_5038_50381401_101_dialog_content = "海ノ、テキ。",
  ui_story_5038_50381401_102_dialog_content = "オマエラ、フネ…",
  ui_story_5038_50381401_103_dialog_content = "シズメ。",
  ui_story_5038_50381401_104_dialog_content = "うっ、足元が…！？",
  ui_story_5038_50381401_105_dialog_content = "待って！イヨウ！！",
  ui_story_5038_50381401_106_dialog_content = "む？リンセイの声じゃ！",
  ui_story_5038_50381401_107_dialog_content = "ふぅ…ふぅ…やっと追いついた！",
  ui_story_5038_50381401_108_dialog_content = "リン、セイ…",
  ui_story_5038_50381401_109_dialog_content = "これが「羅針盤」の姿…",
  ui_story_5038_50381401_110_dialog_content = "え？どうして皆がここに？\n何があったの？",
  ui_story_5038_50381401_111_dialog_content = "お三方、こんな所にいたんですか。",
  ui_story_5038_50381401_112_dialog_content = "何があったんですかねぇ？\nあの子は何者でしょう？",
  ui_story_5038_50381401_113_dialog_content = "その子は僕たちがずっと探してた「羅針盤」なんだ。",
  ui_story_5038_50381401_114_dialog_content = "「羅針盤」…？",
  ui_story_5038_50381401_115_dialog_content = "うーん、結局、人の身では天の意思は測れませんねぇ。\n僕の占いでは…",
  ui_story_5038_50381401_116_dialog_content = "いやいや、あの卦象、そういうことでしたか！",
  ui_story_5038_50381401_117_dialog_content = "どうも奇妙な結果でしてねぇ。\n「首鼠両端」、「猿猴取月」、「狡兎三窟」と出まして。",
  ui_story_5038_50381401_118_dialog_content = "ニセモノもホンモノも見方次第ってことですよ。\n何かの<color=#FFB400>代わり</color>を探せと言ってるんじゃないですかねぇ。",
  ui_story_5038_50381401_119_dialog_content = "なるほどなるほど、そんな意味だったんですねぇ！",
  ui_story_5038_50381401_120_dialog_content = "え？何の話？",
  ui_story_5038_50381401_121_dialog_content = "僕たちの航海の最初から最後まで、\nあの占いに予言されていたという事ですねぇ。",
  ui_story_5038_50381401_122_dialog_content = "始めの「首鼠両端」は、決断ができないと言う事。\n船長が「羅針盤」探しと龍州への航行との間で迷うことを指し…",
  ui_story_5038_50381401_123_dialog_content = "最後の「狡兎三窟」は、隠れるのがうまいウサギ…\n「羅針盤」が何かも、使い道も、ついでに行方も分からないという事ですねぇ。",
  ui_story_5038_50381401_124_dialog_content = "そして、真ん中の「猿猴取月」は、\n水に写った月に手を伸ばすサルの事…",
  ui_story_5038_50381401_125_dialog_content = "つまり、普通ならやるべきでない事をやり、道なき道を行く。\nそれで始めて物事に始末が付くと言う事ですねぇ。",
  ui_story_5038_50381401_126_dialog_content = "そして、3つ全てで暗示されていた「本物の代わり」とは他でもない…",
  ui_story_5038_50381401_127_dialog_content = "蜃風号のことだったということですねぇ。",
  ui_story_5038_50381401_128_dialog_content = "イヨウ、何をしてるの！？",
  ui_story_5038_50381401_129_dialog_content = "シュウさんを殺す気！？",
  ui_story_5038_50381401_130_dialog_content = "…",
  ui_story_5038_50381401_131_dialog_content = "それがしだけではない。\nこやつは蜃風号を沈めようとしておる。",
  ui_story_5038_50381401_132_dialog_content = "どうしてそんなことを…",
  ui_story_5038_50381401_133_dialog_content = "キミが小さな水槽の中で、\n辛い思いをしてきたのは知ってるよ。",
  ui_story_5038_50381401_134_dialog_content = "キミの心には不満とか、怒りとか、\n恨みがいっぱいってことも、ボクには分かる。",
  ui_story_5038_50381401_135_dialog_content = "でもね、人ってみんな違うんだ。\nみんながみんな、キミを傷つけようとしてるわけじゃない。",
  ui_story_5038_50381401_136_dialog_content = "本当に悪い人の罪を無実の人に\nつぐなわせようとするのは、間違ってる！",
  ui_story_5038_50381401_137_dialog_content = "オマエ、キテハ、イケナイ。",
  ui_story_5038_50381401_138_dialog_content = "どうして？",
  ui_story_5038_50381401_139_dialog_content = "キタラ、死ヌ。",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>バキン――！！！</color>",
  ui_story_5038_50381401_141_dialog_content = "うわわ！甲板が割れた！？",
  ui_story_5038_50381401_142_dialog_content = "待って、イヨウ！\nキミはほんとにこんなことがしたいの？",
  ui_story_5038_50381401_143_dialog_content = "ここにいるみんなは、何も悪いことなんかしてない！\nとくにボクを思いだしてよ！",
  ui_story_5038_50381401_144_dialog_content = "毎日ごはんをあげたでしょ、覚えてないの！？",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>バキン――！！！</color>",
  ui_story_5038_50381401_146_dialog_content = "どうして！？",
  ui_story_5038_50381401_X146_dialog_content = "あやつの耳には、もう誰の言葉も届かぬ。\nこのままでは、船上のすべての者の命が危うい。",
  ui_story_5038_50381401_X147_dialog_content = "まずは何とかして、あやつを止めねばならん。",
  ui_story_5038_50381401_147_dialog_content = "無駄だ、リンセイ。\nこやつの恨みはお主への好意よりはるかに大きいのだろう。",
  ui_story_5038_50381401_148_dialog_content = "食事を与えた程度の恩では、\n船上のすべての者の命を救うには足りぬと言う事か。",
  ui_story_5038_50381401_149_dialog_content = "でも…",
  ui_story_5038_50381401_150_dialog_content = "蜃風号を好きにはさせない。",
  ui_story_5038_50381401_151_dialog_content = "船長の許可なく狼藉（ろうぜき）を働こうなんて、\n許されると思うのかしら？",
  ui_story_5038_50381401_152_dialog_content = "そうじゃ！蜃風号に手を出すなどと、我らが許さんぞ！",
  ui_story_5038_50381401_153_dialog_content = "と～はいっても、子ども相手って言うのは、\nちとやりづらいですねぇ…",
  ui_story_5038_50381401_154_dialog_content = "あれは祟霊です。\nあなたのお爺様以上の歳でもおかしくありませんよ。",
  ui_story_5038_50381401_155_dialog_content = "攻撃してくる！",
  ui_story_5038_50381401_156_dialog_content = "皆、戦う準備を！",
  ui_story_5038_50381402_1_dialog_content = "ドケ…",
  ui_story_5038_50381402_2_dialog_content = "力がだいぶ弱くなってる！",
  ui_story_5038_50381402_3_dialog_content = "攻撃するだけで、かなり力を消耗するみたいだね。",
  ui_story_5038_50381402_4_dialog_content = "あやつは祟霊になって間もない。\n力をうまく操れておらぬのだろうな。",
  ui_story_5038_50381402_5_dialog_content = "やたらに攻撃をしかけ続けたせいで、\nかえって疲れ始めておる。",
  ui_story_5038_50381402_6_dialog_content = "最後のあがきも許さないわ。\n今のうちに抑える！",
  ui_story_5038_50381402_7_dialog_content = "分かった、手伝うよ！",
  ui_story_5038_50381402_8_dialog_content = "シズメ…",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>ドカン――！！！</color>",
  ui_story_5038_50381402_10_dialog_content = "ふ、船を攻撃し始めた！",
  ui_story_5038_50381402_11_dialog_content = "それに…ミズチウオの群れが集まりだしてる！",
  ui_story_5038_50381402_12_dialog_content = "リンセイ。",
  ui_story_5038_50381402_13_dialog_content = "分かってるよ！",
  ui_story_5038_50381402_14_dialog_content = "イヨウ、友だちだったキミがボクと同類になるなんて、\n思ってもいなかったよ。",
  ui_story_5038_50381402_15_dialog_content = "リン、セイ…",
  ui_story_5038_50381402_16_dialog_content = "言葉も覚えたんだね。",
  ui_story_5038_50381402_17_dialog_content = "ジャマ、スルナ…",
  ui_story_5038_50381402_18_dialog_content = "残念だけど、ゆっくり話す機会はなさそうだね。",
  ui_story_5038_50381402_19_dialog_content = "ドケ…",
  ui_story_5038_50381402_20_dialog_content = "そんなに偉ぶらないで、\nボクの方が祟霊としては先輩なんだよ。",
  ui_story_5038_50381402_21_dialog_content = "キミにはまだ出来ないことがたくさんある！",
  ui_story_5038_50381402_22_dialog_content = "ボクが先輩として教えてあげるよ。でも…",
  ui_story_5038_50381402_23_dialog_content = "まずはキミに勝ってからだ！",
  ui_story_5038_50381402_24_dialog_content = "（船長、今だ！）",
  ui_story_5038_50381402_25_dialog_content = "！！！",
  ui_story_5038_50381402_26_dialog_content = "私の船には誰も手を出させない。",
  ui_story_5038_50381402_27_dialog_content = "ウウ…ウウッ…！",
  ui_story_5038_50381402_28_dialog_content = "効いてますねぇ！急いで抑えますよ！",
  ui_story_5038_50381402_29_dialog_content = "分かっておる！左腕はわらわが！",
  ui_story_5038_50381402_30_dialog_content = "殿下、右腕は私が。",
  ui_story_5038_50381402_31_dialog_content = "ね、ねえ、そんな力いっぱい抑えないであげて…",
  ui_story_5038_50381402_32_dialog_content = "イヨウにはもう、力が残ってないんだよ。",
  ui_story_5038_50381402_33_dialog_content = "む？さようか？",
  ui_story_5038_50381402_34_dialog_content = "ヒィ…ヒィ…",
  ui_story_5038_50381402_35_dialog_content = "…お魚って鳴き声をあげないでしょ。\n苦しい時にどんな声を出したらいいかも、まだ知らないんだ…",
  ui_story_5038_50381402_36_dialog_content = "ふぅ――やっと勝てたね…",
  ui_story_5038_50381402_37_dialog_content = "これで羅針盤を「手に入れた」ってことになるのかな？",
  ui_story_5038_50381402_38_dialog_content = "左様。こやつこそが間違いなく「羅針盤」だ。",
  ui_story_5038_50381402_39_dialog_content = "祟霊となったとしても、\n「羅針盤」としての役割には変わりあるまい。",
  ui_story_5038_50381402_40_dialog_content = "じゃあ、これからどうするの？",
  ui_story_5038_50381402_41_dialog_content = "…",
  ui_story_5038_50381402_42_dialog_content = "…",
  ui_story_5038_50381402_43_dialog_content = "「羅針盤」として使うのであれば、\nこやつをもう一度蜃風号に閉じ込めねばならぬ。",
  ui_story_5038_50381402_44_dialog_content = "そして「遡上」の合図を出させるのだ。",
  ui_story_5038_50381402_45_dialog_content = "さすれば、ミズチウオの群れはヌシの号令で\n蜃風号の周りに集まり、船を龍州へと戻すであろう。",
  ui_story_5038_50381402_46_dialog_content = "その航海にはいかなる危険も伴わぬ。\nかつてそうであったようにな。",
  ui_story_5038_50381402_47_dialog_content = "…",
  ui_story_5038_50381402_48_dialog_content = "かような幼子を、\nどうしても船に押し込めねばならんのか？",
  ui_story_5038_50381402_49_dialog_content = "参りましたねぇ…船旅が順調っていうのは願ってもないことですが、\nどうにも方法が気に入りませんねぇ。",
  ui_story_5038_50381402_50_dialog_content = "それがしも、あやつの憎しみを目の当たりにした後では、\nあまりにしのびない。",
  ui_story_5038_50381402_51_dialog_content = "リン家の先祖から根を張る怨恨ではあるが、\n船を利用していたすべての者もまた、加担していたことに変わりはない。",
  ui_story_5038_50381402_52_dialog_content = "誰もが己の身勝手で、「羅針盤」はしょせん魚、\n恨みなど持つはずはないと思い込もうとしてきた。",
  ui_story_5038_50381402_53_dialog_content = "恨みが存在しなければ、罪も存在しない。\nやましく感じる必要もなくなるからな。",
  ui_story_5038_50381402_54_dialog_content = "結局、いざ恨みを抱いた者が目の前に現れた時、\nようやく悔いたところで、手遅れなのだ。",
  ui_story_5038_50381402_55_dialog_content = "…悔やんでおられるのか？",
  ui_story_5038_50381402_56_dialog_content = "「羅針盤」を閉じ込めるなど、\n間違っていると考えているように見受けられる。",
  ui_story_5038_50381402_57_dialog_content = "悔やんでいることなら山ほどある。",
  ui_story_5038_50381402_58_dialog_content = "賊どもを鏖殺（おうさつ）したことも、\n「羅針盤」に執着したことも、みな過ちであった。",
  ui_story_5038_50381402_59_dialog_content = "そもそも陸の上で片付けておくべきことを\n海の上に持ちこんだがゆえに、このような状況を招いたのだ。",
  ui_story_5038_50381402_60_dialog_content = "ならば、我らは…\nそれでも過ちを犯し続けなければならぬと？",
  ui_story_5038_50381402_61_dialog_content = "それがしの歳にもなると、\n命で罪を償えると言うなら、惜しくもない。",
  ui_story_5038_50381402_62_dialog_content = "だが、この船にはそれがし1人ではない。",
  ui_story_5038_50381402_63_dialog_content = "「羅針盤」の力なしに、\n蜃風号が龍州にたどり着くことができようか？",
  ui_story_5038_50381402_64_dialog_content = "…",
  ui_story_5038_50381402_65_dialog_content = "ずいぶんハデに衝突されましたからねぇ。\nあっちの蜃風号の具合も分からないですし…",
  ui_story_5038_50381402_66_dialog_content = "シュウさんの言ってること、分かるよ。\nボクもずっと、同じことを考えてたんだ。",
  ui_story_5038_50381402_67_dialog_content = "海の上じゃ、いろんなことが思うようにいかないよね。",
  ui_story_5038_50381402_68_dialog_content = "ボクはイヨウのこと、友だちだって思ってたんだ。\n自由にしてあげたいとも思ってる。けど…",
  ui_story_5038_50381402_69_dialog_content = "代償が大きすぎる…",
  ui_story_5038_50381402_70_dialog_content = "代償…",
  ui_story_5038_50381402_71_dialog_content = "（誰も何も言わなくなった）",
  ui_story_5038_50381402_72_dialog_content = "（いくつかの視線がぶつかり、\nそのわずかな動きが虚しさをさらに増大させる）",
  ui_story_5038_50381402_73_dialog_content = "（まるで全員が懺悔（ざんげ）してるみたいだ）",
  ui_story_5038_50381402_74_dialog_content = "（間違いだと分かっていても、そうするしかないから）",
  ui_story_5038_50381402_75_dialog_content = "そう浮かない顔をする必要はないわ。",
  ui_story_5038_50381402_76_dialog_content = "「羅針盤」が見つかって、目標は達成できた。\n喜ぶべきだわ。",
  ui_story_5038_50381402_77_dialog_content = "…船長殿、航海に望みができたこと、\n確かに喜ぶべきじゃが…",
  ui_story_5038_50381402_78_dialog_content = "それでも閉じ込めておくには…",
  ui_story_5038_50381402_79_dialog_content = "閉じ込める必要なんてあるかしら？",
  ui_story_5038_50381402_80_dialog_content = "何？",
  ui_story_5038_50381402_81_dialog_content = "それはどういう意味じゃ？",
  ui_story_5038_50381402_82_dialog_content = "「羅針盤」の力が無ければ、\n龍州にたどり着くことはできない…",
  ui_story_5038_50381402_83_dialog_content = "でも、使い方にはまだ選ぶ余地があると思うわ。",
  ui_story_5038_50381402_84_dialog_content = "リン家が代々採っていた方法が、\n皆の意にかなわないものなら…",
  ui_story_5038_50381402_85_dialog_content = "私は新しい方法を選んでみようと思うの。",
  ui_story_5038_50381402_86_dialog_content = "ほんとに？イヨウを閉じ込めずに済むの？",
  ui_story_5038_50381402_87_dialog_content = "…",
  ui_story_5038_50381402_88_dialog_content = "答えて。\n蜃風号の客人になってもらえるかしら？",
  ui_story_5038_50381402_89_dialog_content = "…イヤダ。",
  ui_story_5038_50381402_90_dialog_content = "コトワル。",
  ui_story_5038_50381402_91_dialog_content = "そう。\nそれなら、蜃風号とあなたとの縁はここまでということね。",
  ui_story_5038_50381402_92_dialog_content = "この船はもうすぐ沈むわ。\nあなたは早く、海に帰りなさい。",
  ui_story_5038_50381402_93_dialog_content = "イヨウを放してあげて。\n私たちは蜃風号に戻りましょう。",
  ui_story_5038_50381402_94_dialog_content = "そんな…それでいいんですか？",
  ui_story_5038_50381402_95_dialog_content = "一度放してしまったら、\nもう一度捕まえるというわけには行かないと思いますが…",
  ui_story_5038_50381402_96_dialog_content = "イヨウは魚だもの。\n船の上より海にいる方がいいに決まってるわ。",
  ui_story_5038_50381402_97_dialog_content = "霧も晴れたことだし、帆を張って出発しましょう。",
  ui_story_5038_50381402_98_dialog_content = "覚悟はできておられるのか？",
  ui_story_5038_50381402_99_dialog_content = "ええ。",
  ui_story_5038_50381402_100_dialog_content = "お止めになりますか？",
  ui_story_5038_50381402_101_dialog_content = "リン家のご当主に、\nリン家を守ると約束した。",
  ui_story_5038_50381402_102_dialog_content = "そして今、「羅針盤」はリン家の若き世代の者に渡った。\nそれがしたちの約束は果たされた。",
  ui_story_5038_50381402_103_dialog_content = "決断の重みを分かったうえのことであれば、\nそれがしは貴公の選択を尊重しよう。",
  ui_story_5038_50381402_104_dialog_content = "行くぞ。船長殿がもう決めたことじゃ。",
  ui_story_5038_50381402_105_dialog_content = "海のことは、船長殿の方がわらわたちより\nずっとよく分かっておる。",
  ui_story_5038_50381402_106_dialog_content = "はぁ…そうですねぇ。\n僕らが気をもんでも仕方のないことですか。",
  ui_story_5038_50381402_107_dialog_content = "さあさあ、行きますよ。\nPlayerNameの旦那も急ぎなすって…何をぼうっとしてるんです？",
  ui_story_5038_50381402_108_dialog_content = "うん…ミズチウオを見てるんだ。",
  ui_story_5038_50381402_109_dialog_content = "壮観だね…船の周りをずっとグルグル回ってる。",
  ui_story_5038_50381402_110_dialog_content = "船が沈むのを待ってるみたいに…",
  ui_story_5038_50381402_111_dialog_content = "何をしているのやら…\nそれなら蜃風号でも見られますよ。",
  ui_story_5038_50381402_112_dialog_content = "早く、足を動かしてください！",
  ui_story_5038_50381402_113_dialog_content = "ハハハ、そうだね…",
  ui_story_5038_50381402_114_dialog_content = "良かったね、イヨウ！\n君はもう自由だ！",
  ui_story_5038_50381402_115_dialog_content = "ジ、ユウ…",
  ui_story_5038_50381402_116_dialog_content = "分からない？\nキミのこと、もう閉じ込めないってさ。",
  ui_story_5038_50381402_117_dialog_content = "せっかく祟霊になれたんだ。\nちゃんと言葉を話す練習をするんだよ。",
  ui_story_5038_50381402_118_dialog_content = "でないと、おしゃべりする時大変だからね。",
  ui_story_5038_50381402_119_dialog_content = "トジコメ、ナイ？",
  ui_story_5038_50381402_120_dialog_content = "そうだよ。分からないかな？",
  ui_story_5038_50381402_121_dialog_content = "好きなところに行っていいってこと。",
  ui_story_5038_50381402_122_dialog_content = "…",
  ui_story_5038_50381402_123_dialog_content = "ボクはもう行くね。水は苦手なんだ。",
  ui_story_5038_50381402_124_dialog_content = "覚えておいて、\nリンセイはずっとイヨウの友だちだよ。",
  ui_story_5038_50381402_125_dialog_content = "バイバイ！",
  ui_story_5038_50381402_126_dialog_content = "船長！やっとお帰りになりましたか！",
  ui_story_5038_50381402_127_dialog_content = "ぶつかられた上に、暗鬼の襲撃を受けたもんで…\n蜃風号のそこかしこが穴だらけです。",
  ui_story_5038_50381402_128_dialog_content = "今、全力で直してはいますが…",
  ui_story_5038_50381402_129_dialog_content = "分かったわ。修理を続けて。\nそれと、すぐに帆を張って。",
  ui_story_5038_50381402_130_dialog_content = "今すぐ出発するわ。",
  ui_story_5038_50381402_131_dialog_content = "今すぐ？休みもなしですか？",
  ui_story_5038_50381402_132_dialog_content = "時間がないの。",
  ui_story_5038_50381402_133_dialog_content = "ミズチウオがもうすぐ遡上を始めるわ。\n私たちも付いていく。",
  ui_story_5038_50381402_134_dialog_content = "ミズチウオ？",
  ui_story_5038_50381402_135_dialog_content = "おお、まことじゃ！\nミズチウオがいっせいに動き出しておる！",
  ui_story_5038_50381402_136_dialog_content = "皆同じ方向を目指しておる！",
  ui_story_5038_50381402_137_dialog_content = "龍州に向かっているのよ。",
  ui_story_5038_50381402_138_dialog_content = "この海の中で、\nミズチウオほど故郷に帰りたがっているものはないわ。",
  ui_story_5038_50381402_139_dialog_content = "あ、そうか！",
  ui_story_5038_50381402_140_dialog_content = "イヨウを逃がせば、\nミズチウオがまた遡上を始める。",
  ui_story_5038_50381402_141_dialog_content = "群れを道案内にすれば、\n蜃風号も龍州へ向かう航路に戻れるってことだね！",
  ui_story_5038_50381402_142_dialog_content = "簡単な道理でしょう？\nでも、ミズチウオに付いていくのは簡単なことじゃないわよ。",
  ui_story_5038_50381402_143_dialog_content = "乗り切るには、船の皆の協力が必要になるわ。",
  ui_story_5038_50381402_144_dialog_content = "うん、もちろん協力するよ！",
  ui_story_5038_50381402_145_dialog_content = "やれやれ、船底の浸水が止まりませんねぇ。",
  ui_story_5038_50381402_146_dialog_content = "急いで人手を増やしませんと。",
  ui_story_5038_50381402_147_dialog_content = "人手なんて、もうないよ。\nみんな手いっぱいだ。",
  ui_story_5038_50381402_148_dialog_content = "強い波風の中で、\nボロボロの蜃風号を進めるのは簡単じゃないね…",
  ui_story_5038_50381402_149_dialog_content = "船底はまだ持ちそうかな？",
  ui_story_5038_50381402_150_dialog_content = "この前兎耳でふさいだすき間から、\nまた浸水が始まってますねぇ。",
  ui_story_5038_50381402_151_dialog_content = "全力でくみ出しても、水位が上がる一方のようで。",
  ui_story_5038_50381402_152_dialog_content = "浸水…どうすればいいんだろう…",
  ui_story_5038_50381402_153_dialog_content = "致し方ありませんねぇ。\nこれ以上誰にも手伝ってもらえないのでしたら…",
  ui_story_5038_50381402_154_dialog_content = "僕たちが手を速めるしかありません！",
  ui_story_5038_50381402_155_dialog_content = "もう両手に一つずつ桶を持っているので…",
  ui_story_5038_50381402_156_dialog_content = "口でもう1つくわえれば、\nもっと早く水をくみ出せるって計算ですねぇ！",
  ui_story_5038_50381402_157_dialog_content = "そ、そんなことできるの？",
  ui_story_5038_50381402_158_dialog_content = "できるできないじゃありませんよ！\n最後の正念場ですから、全力を尽くして当然ってことですねぇ！",
  ui_story_5038_50381402_159_dialog_content = "全速力で作業を進めていれば、怖さも感じませんよ！",
  ui_story_5038_50381402_160_dialog_content = "旦那はどいてください！\n僕の邪魔だけはしないで欲しい所ですねぇ！",
  ui_story_5038_50381402_161_dialog_content = "空の桶はどこです？僕に渡してください！",
  ui_story_5038_50381402_162_dialog_content = "PlayerName！",
  ui_story_5038_50381402_163_dialog_content = "こちらを手伝え！",
  ui_story_5038_50381402_164_dialog_content = "タンドウ！どうしたの！？",
  ui_story_5038_50381402_165_dialog_content = "帆を固定する巻き取り機が壊れてしもうた！\n今は人が引いて押さえるしかないのじゃ。",
  ui_story_5038_50381402_166_dialog_content = "わらわ1人で引っ張っておったが…",
  ui_story_5038_50381402_167_dialog_content = "風が強くなった、1人ではもう持たん！",
  ui_story_5038_50381402_168_dialog_content = "手伝うよ！",
  ui_story_5038_50381402_169_dialog_content = "こうやって引っ張ってればいいの？",
  ui_story_5038_50381402_170_dialog_content = "そうじゃ、そのままを保て。",
  ui_story_5038_50381402_171_dialog_content = "手が真っ赤になってるよ。大丈夫？",
  ui_story_5038_50381402_172_dialog_content = "案ずるな、日頃鍛えておらんかっただけじゃ。",
  ui_story_5038_50381402_173_dialog_content = "この程度の事ができぬなら、\nわらわはまことの役立たずじゃ。",
  ui_story_5038_50381402_174_dialog_content = "でも、あとどのくらい続くか分からないんだよ。\nこのままだと、手が…",
  ui_story_5038_50381402_175_dialog_content = "それがどうした？\n蜃風号もまだ持ちこたえておるではないか！",
  ui_story_5038_50381402_176_dialog_content = "この箱は捨てろ！",
  ui_story_5038_50381402_177_dialog_content = "はい！",
  ui_story_5038_50381402_178_dialog_content = "うーん、ものを捨てると気分がいいなぁ！",
  ui_story_5038_50381402_179_dialog_content = "こいつも捨てろ！",
  ui_story_5038_50381402_180_dialog_content = "これも全部？これって全部、布団でしょ…",
  ui_story_5038_50381402_181_dialog_content = "全部要らん！この状況で寝てる暇があるか！",
  ui_story_5038_50381402_182_dialog_content = "よーし、この箱も捨てちゃうよ！",
  ui_story_5038_50381402_183_dialog_content = "必要のねえもんは全部捨てろ！\nできる限り船の重量を減らすんだ。",
  ui_story_5038_50381402_184_dialog_content = "海と時間の取り合いだ！",
  ui_story_5038_50381402_185_dialog_content = "その通りね…",
  ui_story_5038_50381402_186_dialog_content = "捨てましょう。全部！",
  ui_story_5038_50381402_187_dialog_content = "家財道具も捨てろ！机もいすも、\n動かせるもんは全部海に投げ込め！",
  ui_story_5038_50381402_188_dialog_content = "（蜃風号がこんなに忙しかったことは、\nきっと今までなかっただろうな）",
  ui_story_5038_50381402_189_dialog_content = "（一人一人が、一つ一つの道具が、\n最大限に役目を果たしてる）",
  ui_story_5038_50381402_190_dialog_content = "（蜃風号の行きつく場所は2つに1つ…\n海の底か、それとも龍州か）",
  ui_story_5038_50381402_191_dialog_content = "（現実と理想のどちらが勝つか、皆で勝負してるんだ）",
  ui_story_5038_50381402_192_dialog_content = "（僕たちは今、地平線を見る日を待ちわびている。\nけれど、船は無情にも少しずつ沈み続けている…）",
  ui_story_5038_50381402_193_dialog_content = "（運命の宣告を、今か今かと待つように…）",
  ui_story_5038_50381402_194_dialog_content = "こりゃあいけません！\n貨物庫が完全に浸かってしまいましたねぇ。",
  ui_story_5038_50381402_195_dialog_content = "何か方法はないんでしょうか？",
  ui_story_5038_50381402_196_dialog_content = "完全に浸かっちまったら…",
  ui_story_5038_50381402_197_dialog_content = "方法なんてあるか！\n船倉が浸かっちまったら、次は…",
  ui_story_5038_50381402_198_dialog_content = "うわあ！甲板まで水があふれて来た！！",
  ui_story_5038_50381402_199_dialog_content = "どうしたらいいんだ。何か方法は…",
  ui_story_5038_50381402_200_dialog_content = "やっぱりダメなのか…？",
  ui_story_5038_50381402_201_dialog_content = "やるべきことをやるしかない…",
  ui_story_5038_50381402_202_dialog_content = "船長！船長！！",
  ui_story_5038_50381402_203_dialog_content = "どこですか？これから、どうしたら…",
  ui_story_5038_50381402_204_dialog_content = "慌てないで。甲板にしっかり立っていなさい。",
  ui_story_5038_50381402_205_dialog_content = "蜃風号は沈まないわ。",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>ドン、ドン、ドン――</color>",
  ui_story_5038_50381402_207_dialog_content = "何の音です！？",
  ui_story_5038_50381402_208_dialog_content = "何かが船底にぶつかるような…",
  ui_story_5038_50381402_209_dialog_content = "待って…何か船体が上がってる気がしない？",
  ui_story_5038_50381402_210_dialog_content = "おや、本当ですねぇ…\nいったい何が…？",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>バシャーン――！</color>",
  ui_story_5038_50381402_212_dialog_content = "と、飛んだ！？",
  ui_story_5038_50381402_213_dialog_content = "み、みんな、下だよ！お魚だ！\nミズチウオがたくさんいるよ！",
  ui_story_5038_50381402_214_dialog_content = "ミズチウオの群れが蜃風号を乗せて泳いでる！",
  ui_story_5038_50381402_215_dialog_content = "これは驚きました。\nずいぶん壮観ですねぇ。",
  ui_story_5038_50381402_216_dialog_content = "言ったでしょう？\nミズチウオは船より海にいるのがいいって。",
  ui_story_5038_50381402_217_dialog_content = "そっか！イヨウがボクたちを助けてくれてるんだ！",
  ui_story_5038_50381402_218_dialog_content = "イヨウ！そこにいるの！？",
  ui_story_5038_50381402_219_dialog_content = "ありがとう！！",
  ui_story_5038_50381402_220_dialog_content = "イヨウを放した時にこうなるって分かってたの？",
  ui_story_5038_50381402_221_dialog_content = "いいえ。海は測り知れないものよ。\n何が起こるかなんて、誰にも予想はつかないわ。",
  ui_story_5038_50381402_222_dialog_content = "ただ、私たちは一つ一つ目標を果たして、\nこの航海のためにやるべきことを全てやった。",
  ui_story_5038_50381402_223_dialog_content = "だから、必ず龍州にたどり着けると信じていただけ。",
  ui_story_5038_50381501_1_dialog_content = "シュウ殿は？",
  ui_story_5038_50381501_2_dialog_content = "ほら、早く旦那を呼んできてください。",
  ui_story_5038_50381501_3_dialog_content = "もう、分かったって。\nなんにも手伝わないのに、せかしてばっかりなんだから。",
  ui_story_5038_50381501_4_dialog_content = "リンセイ、何事だ？",
  ui_story_5038_50381501_5_dialog_content = "シュウさん、みんなが船の中にいたら、\n絶景を見逃しちゃうって言ってるよ。",
  ui_story_5038_50381501_6_dialog_content = "ほら見て。あれ、何だと思う？",
  ui_story_5038_50381501_7_dialog_content = "あれは…",
  ui_story_5038_50381501_8_dialog_content = "帰って来たのか…",
  ui_story_5038_50381501_9_dialog_content = "そうだよ、ボクたち、戻れたんだよ！\n龍州に帰ってきたんだ！",
  ui_story_5038_50381501_10_dialog_content = "懐かしいでしょ？",
  ui_story_5038_50381501_11_dialog_content = "龍州…",
  ui_story_5038_50381501_12_dialog_content = "数十年の生涯の中で、この地を\n「龍州」と呼ぶことは数えるほどしかなかった。",
  ui_story_5038_50381501_13_dialog_content = "今おぬしの口からその名を聞いて、\nこれほど懐かしさを覚えるとは思わなかったな。",
  ui_story_5038_50381501_14_dialog_content = "ずいぶん長く離れていたような気がする。",
  ui_story_5038_50381501_15_dialog_content = "その通りだよ。すっごく遠いところまで行って、\nたくさんのことを経験したんだ。",
  ui_story_5038_50381501_16_dialog_content = "その間に船が変わり、\nそれがしも車いすの身となった。",
  ui_story_5038_50381501_17_dialog_content = "かような有り様では、朝見も叶うまいな。",
  ui_story_5038_50381501_18_dialog_content = "天子様に会いたいの？",
  ui_story_5038_50381501_19_dialog_content = "この歳になると、昔のことばかり思い出されてかなわん。",
  ui_story_5038_50381501_20_dialog_content = "朝廷であろうと別の地であろうと、\n足を踏み入れたすべての地に思い入れがある。",
  ui_story_5038_50381501_21_dialog_content = "シュウさんの話って、\nいつも回りくどくてむずかしいね。",
  ui_story_5038_50381501_22_dialog_content = "とにかく…甲板で見るこの景色、きれいでしょ？",
  ui_story_5038_50381501_23_dialog_content = "ふむ、そうだな。実に美しい。",
  ui_story_5038_50381501_24_dialog_content = "見て、ミズチウオの群れが遠くへ泳いでいくよ！",
  ui_story_5038_50381501_25_dialog_content = "当然でしょ、ボクたちと一緒に\n陸に上がるわけにはいかないんだし。",
  ui_story_5038_50381501_26_dialog_content = "ボクたちを港まで送った後で、\n自分たちの行くべきところに行くんだよ。",
  ui_story_5038_50381501_27_dialog_content = "ずっと一緒にいた気がするから、\n何だか名残惜しいね。",
  ui_story_5038_50381501_28_dialog_content = "情が移ったって言うのかな。",
  ui_story_5038_50381501_29_dialog_content = "師匠が言ってたよ。別れはつらいものだって。",
  ui_story_5038_50381501_30_dialog_content = "でも…どうせ一緒にいられなくなるなら、\n元気よくお別れした方がいい。",
  ui_story_5038_50381501_31_dialog_content = "そうだね。船旅ももう終わりだ。\n別の道を行く時が来たんだね。",
  ui_story_5038_50381501_32_dialog_content = "ありがとう！また会おうね！",
  ui_story_5038_50381501_33_dialog_content = "ううっ…やっと戻ってこられた…",
  ui_story_5038_50381501_34_dialog_content = "ほんとだな…\nもう少しで海の魚のエサになるところだった…",
  ui_story_5038_50381501_35_dialog_content = "よかった…陸地を見たら安心したぞ。",
  ui_story_5038_50381501_36_dialog_content = "それもこれも船長のおかげね。\n船長がいなかったら、船はとっくに何度も沈んでたでしょうから。",
  ui_story_5038_50381501_37_dialog_content = "そりゃそうだろ！俺たちの船長は最高だ！",
  ui_story_5038_50381501_38_dialog_content = "考えてもみろよ、\n船長の命令で、俺たちが何を成し遂げたと思う？",
  ui_story_5038_50381501_39_dialog_content = "リン家の航路を復活させたんだぞ！",
  ui_story_5038_50381501_40_dialog_content = "あ！船長！",
  ui_story_5038_50381501_41_dialog_content = "船長、早くこちらへ！\nみんなで船長のことを讃えていたところです！",
  ui_story_5038_50381501_42_dialog_content = "あなたたち…",
  ui_story_5038_50381501_43_dialog_content = "こんなところで集まって何をしているの？\n急いで持ち場に戻りなさい。",
  ui_story_5038_50381501_44_dialog_content = "もうすぐ着岸よ。\n最後の最後で失敗なんて許されないわ。",
  ui_story_5038_50381501_45_dialog_content = "おい、船長のお達しだ！\nヘマするんじゃねえぞ、分かったか！",
  ui_story_5038_50381501_46_dialog_content = "おう！！",
  ui_story_5038_50381501_47_dialog_content = "な、何か緊張してきた…",
  ui_story_5038_50381501_48_dialog_content = "船を下りたら、どうすればいいんだろう？",
  ui_story_5038_50381501_49_dialog_content = "緊張する必要なんかありませんよ。\n僕たちについてくればいいんです。",
  ui_story_5038_50381501_50_dialog_content = "海で大波も嵐も乗り越えて来たって言うのに、\n陸の何が怖いって言うんですかねぇ？",
  ui_story_5038_50381501_51_dialog_content = "でも…まったく知らない場所だし…",
  ui_story_5038_50381501_52_dialog_content = "頼れるものもないし、僕一人じゃ…",
  ui_story_5038_50381501_53_dialog_content = "頼れるものがない？\nわらわたちがおるではないか。",
  ui_story_5038_50381501_54_dialog_content = "まったくですねぇ。",
  ui_story_5038_50381501_55_dialog_content = "龍州じゃあ、僕は情報通として知られてるんですよ。\n食べ物も寝る場所も、任せてくださいと言ったところです。",
  ui_story_5038_50381501_56_dialog_content = "さて、荷物を片づけるとするか。",
  ui_story_5038_50381501_57_dialog_content = "船長殿が船を下りる支度をせいと言っておるぞ！",
  ui_story_5038_50381501_58_dialog_content = "サンザシアメ～！",
  ui_story_5038_50381501_59_dialog_content = "サンザシアメはいらんかね～！",
  ui_story_5038_50381501_60_dialog_content = "いくらですか？",
  ui_story_5038_50381501_61_dialog_content = "あっちに飴細工があるぞ！",
  ui_story_5038_50381501_62_dialog_content = "お？元宵団子の匂いがしないか？",
  ui_story_5038_50381501_63_dialog_content = "うわぁ、にぎやかだね！",
  ui_story_5038_50381501_64_dialog_content = "人でいっぱいだ！",
  ui_story_5038_50381501_65_dialog_content = "どうじゃ？楽しいであろう？",
  ui_story_5038_50381501_66_dialog_content = "そ、そうだね。\n龍州の街って、いつもこんなに人でいっぱいなの？",
  ui_story_5038_50381501_67_dialog_content = "そうでもないのう。\n今はちょうど「春新節」の終わりが近いからの。",
  ui_story_5038_50381501_68_dialog_content = "龍州が一番にぎわう時じゃ。\n美味なものや面白きものが街にあふれる。",
  ui_story_5038_50381501_69_dialog_content = "あれは「サンザシアメ」じゃな。\n甘酸っぱく美味じゃぞ。",
  ui_story_5038_50381501_70_dialog_content = "あの屋台に並んでおるのは「飴細工」じゃな、飴を吹いて作る。\n見るだけで食べられはせんがな。",
  ui_story_5038_50381501_71_dialog_content = "それから、あの大鍋の中身は「元宵団子」。\n祝日に食べるものじゃな。",
  ui_story_5038_50381501_72_dialog_content = "そうなんだ、色々あるんだね！",
  ui_story_5038_50381501_73_dialog_content = "何か知りたいことがあれば、\n何でも聞くがよいぞ。",
  ui_story_5038_50381501_74_dialog_content = "そうだなぁ…",
  ui_story_5038_50381501_75_dialog_content = "あそこでむしろに座って、木の棒を振ってるのは…",
  ui_story_5038_50381501_76_dialog_content = "ありゃあロクなもんじゃ有りません。\n銭をだましとられるだけですねぇ。",
  ui_story_5038_50381501_77_dialog_content = "だます？",
  ui_story_5038_50381501_78_dialog_content = "あれは「算命」…ま、占いですねぇ。\n全くよろしくない。",
  ui_story_5038_50381501_79_dialog_content = "神だ天だ、運勢の吉凶を占うだなんて言いますがねぇ…",
  ui_story_5038_50381501_80_dialog_content = "実際には、適当に縁起のいいことを言って、\n金を巻き上げてるだけです。",
  ui_story_5038_50381501_81_dialog_content = "そんなことしてるのに、捕まったりしないの？",
  ui_story_5038_50381501_82_dialog_content = "まぁ、人を煙に巻いたりすることは得意ですし、\n悪知恵も働くやからですからねぇ。",
  ui_story_5038_50381501_83_dialog_content = "とにかく、信じないことですねぇ。\n運勢が知りたきゃあ、僕が占って差し上げましょう！",
  ui_story_5038_50381501_84_dialog_content = "君が…？",
  ui_story_5038_50381501_85_dialog_content = "たった今、自分で占いは信用するなって言ってなかった？",
  ui_story_5038_50381501_86_dialog_content = "万事、人によりけりですねぇ。\n簡単に白黒がついたりはしませんので。",
  ui_story_5038_50381501_87_dialog_content = "ふむ、「同業者は敵」とはよく言ったものじゃのう。",
  ui_story_5038_50381501_88_dialog_content = "PlayerName、真に受けてはいかんぞ。",
  ui_story_5038_50381501_89_dialog_content = "さあさあ、どいてどいて。",
  ui_story_5038_50381501_90_dialog_content = "車いすが通るよ、道をゆずってくれない？",
  ui_story_5038_50381501_91_dialog_content = "リンセイ、そう急くな。\n他人様の迷惑になるであろう。",
  ui_story_5038_50381501_92_dialog_content = "そんなのだめだよ。やっと帰ってきたんだ。\n大手を振って歩かなきゃ！",
  ui_story_5038_50381501_93_dialog_content = "それにしても船長、こんな大人数でどこに行くの？",
  ui_story_5038_50381501_94_dialog_content = "蜃風号はリン家の商船。\n港に帰ったなら、当然リン家の屋敷に戻るのよ。",
  ui_story_5038_50381501_95_dialog_content = "お客様方も、よろしければご一緒にどうぞ。",
  ui_story_5038_50381501_96_dialog_content = "春新節のお客様は多ければ多いほど、\n当主も喜ぶでしょう。",
  ui_story_5038_50381501_97_dialog_content = "シュウさん、ボクたちも行こうよ。",
  ui_story_5038_50381501_98_dialog_content = "お腹も空いちゃったしさ。",
  ui_story_5038_50381501_99_dialog_content = "無論だ。\n例え招かれておらずとも、行かねばならぬ。",
  ui_story_5038_50381501_100_dialog_content = "リン家のご当主は\nそれがしにそれは多くの借りを作ったからな。",
  ui_story_5038_50381501_101_dialog_content = "シュウ様、めでたい春新節の時期に\n取り立てはご遠慮いただければ。",
  ui_story_5038_50381501_102_dialog_content = "それに、かつて大将軍だったほどの方にお返しができる力など、\n今のリン家にはございません。",
  ui_story_5038_50381501_103_dialog_content = "それでよいのだ。",
  ui_story_5038_50381501_104_dialog_content = "貸しを作ったままでな。\nそして生涯、共に己を恥じて行くのだ。",
  ui_story_5038_50381501_105_dialog_content = "戻りました！\n蜃風号の者たちが戻ってきましたよ！",
  ui_story_5038_50381501_106_dialog_content = "いやあ、まったく大変でしたでしょう！\nさあ、早く中へ！",
  ui_story_5038_50381501_107_dialog_content = "皆さん、お疲れでしょう？",
  ui_story_5038_50381501_108_dialog_content = "…ここがリン家？",
  ui_story_5038_50381501_109_dialog_content = "蜃風号ほどの大船を持ってるのに、\nお屋敷はそんなに大きくないんだね…",
  ui_story_5038_50381501_110_dialog_content = "まぁ、落ちぶれてしまったと言いますかねぇ。",
  ui_story_5038_50381501_111_dialog_content = "昔の屋敷はたいそう大きかったそうですが。",
  ui_story_5038_50381501_112_dialog_content = "屋敷など広うても良きことはないぞ。\n物寂しいだけじゃ。",
  ui_story_5038_50381501_113_dialog_content = "それに、この方が年越しはにぎやかになりそうじゃ！",
  ui_story_5038_50381501_114_dialog_content = "よく戻った。ささ、早く中に入るがいい。",
  ui_story_5038_50381501_115_dialog_content = "いつまでも門前でごあいさつと言うわけには行かん。",
  ui_story_5038_50381501_116_dialog_content = "あ、もしかして…",
  ui_story_5038_50381501_117_dialog_content = "当主様、なぜお出迎えなど？",
  ui_story_5038_50381501_118_dialog_content = "蜃風号が帰って来たのだぞ、\n大人しく座っておられると思うか？",
  ui_story_5038_50381501_119_dialog_content = "ここにいるのはリン家の功労者と貴賓ばかりだ。\n港まで迎えに行かれなかった無礼はご容赦いただきたい。",
  ui_story_5038_50381501_120_dialog_content = "いかにも。宴を設け、\n百里先まで迎えに来るべきだったところだ。",
  ui_story_5038_50381501_121_dialog_content = "ご当主が屋敷でゆるりと過ごしておられるのも、\n我らのおかげなのだからな。",
  ui_story_5038_50381501_122_dialog_content = "シュウ大兄！戻られたか！",
  ui_story_5038_50381501_123_dialog_content = "その足は…",
  ui_story_5038_50381501_124_dialog_content = "大事ない。",
  ui_story_5038_50381501_125_dialog_content = "ただ思えば、朝廷のために戦場を駆けめぐっていた時でさえ、\n小さな傷をつくったに過ぎなかったが…",
  ui_story_5038_50381501_126_dialog_content = "リン家のためには両足を折ったとあっては…",
  ui_story_5038_50381501_127_dialog_content = "お主の「面子」は天子以上と言うことになるな。",
  ui_story_5038_50381501_128_dialog_content = "そのような恐れ多き話、\n私にはどう答えてよいかもわからぬぞ…",
  ui_story_5038_50381501_129_dialog_content = "どうか屋敷で養生なされよ。\n名医も探してさしあげよう、治せるものもおるやもしれん。",
  ui_story_5038_50381501_130_dialog_content = "それには及ばぬ。車いすが気に入っていてな。",
  ui_story_5038_50381501_131_dialog_content = "もし本当にそれがしの足を治せる者が現れでもしたら、\nリンセイの面子が丸つぶれになるからな。",
  ui_story_5038_50381501_132_dialog_content = "あり得ないよ！",
  ui_story_5038_50381501_133_dialog_content = "シュウさんの足は治せない。\n誰が診たって同じだよ！",
  ui_story_5038_50381501_134_dialog_content = "な、なんということを申すのだ！？",
  ui_story_5038_50381501_135_dialog_content = "ふふ、構わぬさ。\nリンセイはまっすぐな性格なのだ。",
  ui_story_5038_50381501_136_dialog_content = "今度の旅では実にさまざまなことを経験したが…",
  ui_story_5038_50381501_137_dialog_content = "リン…「羅針盤」は結局、守りきれなんだ。",
  ui_story_5038_50381501_138_dialog_content = "大兄…",
  ui_story_5038_50381501_139_dialog_content = "そのようなことを申されるな。\nこちらの面目が立たないではないか。",
  ui_story_5038_50381501_140_dialog_content = "あなたが戻って来ただけでもう十分だ。",
  ui_story_5038_50381501_141_dialog_content = "家業を守れず、友まで巻き込んだのは、\n全てこのリンの不徳のいたすところ。",
  ui_story_5038_50381501_142_dialog_content = "シュウ大兄、そして各位に心からお詫びを申し上げる。",
  ui_story_5038_50381501_143_dialog_content = "よせよせ。",
  ui_story_5038_50381501_144_dialog_content = "こちらとて手柄は上げておらぬのだ。\n「羅針盤」を守れなかったのだからな。このことで貸し借りはなしとしよう。",
  ui_story_5038_50381501_145_dialog_content = "それより、リン家にはよき後継者がいるようだな。\n「羅針盤」に頼らず海を渡ることができるとは。",
  ui_story_5038_50381501_146_dialog_content = "感謝も詫びも、その者に申すがよい。",
  ui_story_5038_50381501_147_dialog_content = "その通りだな。\n「羅針盤」なしに帰航するとは…",
  ui_story_5038_50381501_148_dialog_content = "ユエ、そなたはまことに見込みがある。",
  ui_story_5038_50381501_149_dialog_content = "それについては、\nお詫びすることがございます。",
  ui_story_5038_50381501_150_dialog_content = "「羅針盤」は見つかったのです。\nただ、放してやりました。",
  ui_story_5038_50381501_151_dialog_content = "放した…？",
  ui_story_5038_50381501_152_dialog_content = "「羅針盤」を利用することはよくないと考え、\nそのような決断をいたしました。",
  ui_story_5038_50381501_153_dialog_content = "決して悔やんでも恥じてもおりませんが、\nリン家の宝が私の手によって失われたことは間違いございません。",
  ui_story_5038_50381501_154_dialog_content = "したがって、ここにお詫び申し上げます。",
  ui_story_5038_50381501_155_dialog_content = "ハハハ、それは詫びとは言わんな。\n私を責めているのだろう。",
  ui_story_5038_50381501_156_dialog_content = "遠回しに痛いところを突く語り口は、\n大兄に学んだか？",
  ui_story_5038_50381501_157_dialog_content = "…そのようなつもりはございません。",
  ui_story_5038_50381501_158_dialog_content = "もともと宝と言うほど立派なものでは無い。\n海を渡るために、やむなく考え出された策にすぎん。",
  ui_story_5038_50381501_159_dialog_content = "あれに頼らず航海できるというなら、\nその方が喜ばしいことではないか。",
  ui_story_5038_50381501_160_dialog_content = "ご寛恕に感謝いたします。",
  ui_story_5038_50381501_161_dialog_content = "まったく、何をかしこまっておるのだ。",
  ui_story_5038_50381501_162_dialog_content = "リン家のために航路を拓いたのだ。\nしばらくすれば、当主と呼ばれているのはそなたかもしれん。",
  ui_story_5038_50381501_163_dialog_content = "！？",
  ui_story_5038_50381501_164_dialog_content = "当主様、お褒めいただいているにしても、\nあまりにも重いお言葉…",
  ui_story_5038_50381501_165_dialog_content = "重くはないさ。当然のことだ。",
  ui_story_5038_50381501_166_dialog_content = "己の出自にこだわることはない。\nすべて過去のことだ。",
  ui_story_5038_50381501_167_dialog_content = "リン家に尽くす者は、すべてリン家の一員だ。",
  ui_story_5038_50381501_168_dialog_content = "そのお言葉、心に刻んでおきます。",
  ui_story_5038_50381501_169_dialog_content = "さあさあ、立ち話が長くなりすぎた。",
  ui_story_5038_50381501_170_dialog_content = "外は冷える。早く中に入られよ。\n料理も酒も存分に楽しまれるがよい。",
  ui_story_5038_50381501_171_dialog_content = "そうですよ、当主様がそうおっしゃるのですし…",
  ui_story_5038_50381501_172_dialog_content = "お話はまた中に入ってからにいたしましょう！",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ、タッ…</color>",
  ui_story_5038_50381501_174_dialog_content = "ぼ、僕も入っていいのかな？",
  ui_story_5038_50381501_175_dialog_content = "当然でしょう。\n他に行くところがあるの？",
  ui_story_5038_50381501_176_dialog_content = "いや、ないけど…",
  ui_story_5038_50381501_177_dialog_content = "リン家の人たちとは見ず知らずだし、\nいきなりご馳走になるのは、どうかなと思って…",
  ui_story_5038_50381501_178_dialog_content = "そんなことはないわ。\nあなたたちは皆、蜃風号の危機を救ってくれたでしょう。",
  ui_story_5038_50381501_179_dialog_content = "他のお客様方はもう中で食べ始めてるようだけど？",
  ui_story_5038_50381501_180_dialog_content = "うまい料理にうまい酒、こりゃたまりませんねぇ！\nへへへ、急いでいただきませんと！",
  ui_story_5038_50381501_181_dialog_content = "これほど富貴な一門の出す品じゃ、素晴らしいに違いあるまい！\nキュウ、早う味を見るとしよう！",
  ui_story_5038_50381501_182_dialog_content = "殿下、しきいにお気を付けください！",
  ui_story_5038_50381501_183_dialog_content = "あ、みんないつの間に…",
  ui_story_5038_50381501_184_dialog_content = "言ったでしょう。\n心配することはないの。",
  ui_story_5038_50381501_185_dialog_content = "龍州にいる間は、リン家に泊まればいいわ。",
  ui_story_5038_50381501_186_dialog_content = "蜃風号の次の航海で、アストラまで返してあげるから。",
  ui_story_5038_50381501_187_dialog_content = "リン家に泊まる？さすがに迷惑じゃ…？",
  ui_story_5038_50381501_188_dialog_content = "龍州式の遠慮なんか覚えなくていいのよ。",
  ui_story_5038_50381501_189_dialog_content = "早く中に入りましょう。\n料理がなくなってしまうわ。",
  ui_story_5038_50381501_190_dialog_content = "（龍州は人であふれ、とてもにぎやかな所だ）",
  ui_story_5038_50381501_191_dialog_content = "（この楽しげな空気に囲まれていると、\nさみしさを感じる暇もない）",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>数日後</color>",
  ui_story_5038_50381501_193_dialog_content = "蜃風号？今からですか？",
  ui_story_5038_50381501_194_dialog_content = "そうだよ。ユエが皆を呼んでるんだ。\nあとは君だけだよ。",
  ui_story_5038_50381501_195_dialog_content = "僕は海に出たいわけじゃないんですがねぇ。\n船で何をするってんです？",
  ui_story_5038_50381501_196_dialog_content = "安心して、航海に出るわけじゃないって。\nアストラまで連れ去られたりはしないよ。",
  ui_story_5038_50381501_197_dialog_content = "具体的なことは僕も聞いてないんだ。\n行けば分かるよ！",
  ui_story_5038_50381501_198_dialog_content = "いいでしょう、港も遠いわけじゃあないですしねぇ。\nおともしますよ。",
  ui_story_5038_50381501_199_dialog_content = "そうこなくっちゃ！",
  ui_story_5038_50381501_200_dialog_content = "ところで、PlayerNameの旦那。\nどうです？龍州は？",
  ui_story_5038_50381501_201_dialog_content = "まだちょっと慣れないかな。\n地元の人と話したりするのは、まだ気が引けちゃうよ。",
  ui_story_5038_50381501_202_dialog_content = "それに、遊ぶにしても\nどこに行けばいいのかよく知らないし…",
  ui_story_5038_50381501_203_dialog_content = "おやおや、それはリン家の手抜かりですねぇ。",
  ui_story_5038_50381501_204_dialog_content = "僕を訪ねていただければ、\n面白いところをご案内しますよ。",
  ui_story_5038_50381501_205_dialog_content = "アハハ、そうする！",
  ui_story_5038_50381501_206_dialog_content = "あ、そうだ。\nそういえば、おかしなことがあって。",
  ui_story_5038_50381501_207_dialog_content = "おかしなこと？",
  ui_story_5038_50381501_208_dialog_content = "龍州宛ての手紙を預かってるんだけど…",
  ui_story_5038_50381501_209_dialog_content = "ここ数日ずっと探したのに、\n宛名の住所が見つからないんだ。",
  ui_story_5038_50381501_210_dialog_content = "で、昨日手紙をしまおうとした時、\nうっかり水をこぼしちゃって…",
  ui_story_5038_50381501_211_dialog_content = "封ろうが濡れて、\n<color=#FFB400>紅色の画仙紙</color>が封筒の中から飛び出してきたんだ。",
  ui_story_5038_50381501_212_dialog_content = "紅色の…？",
  ui_story_5038_50381501_213_dialog_content = "うん。チョウの形に切り抜かれてて、\nあっという間に飛んで行っちゃったんだ。",
  ui_story_5038_50381501_214_dialog_content = "封筒の中には他に何も入ってなかったんだ。\nこれって、手紙を届けたことになるのかな？",
  ui_story_5038_50381501_215_dialog_content = "なぁるほど…",
  ui_story_5038_50381501_216_dialog_content = "テンカン、どういうことか分かる？",
  ui_story_5038_50381501_217_dialog_content = "へっへっへ、なかなか面白いですねぇ。",
  ui_story_5038_50381501_218_dialog_content = "手紙に関しては気にしないことです。\n出し主の願いはもうかなってるでしょうねぇ。",
  ui_story_5038_50381501_X218_dialog_content = "チョウは花を恋しがるものです。\n自分で受取人のところまで飛んでいきますよ。",
  ui_story_5038_50381501_219_dialog_content = "まぁ、それで話は終いって事でしょう。",
  ui_story_5038_50381501_220_dialog_content = "え？届けたってことでいいの？",
  ui_story_5038_50381501_221_dialog_content = "そりゃあそうです。",
  ui_story_5038_50381501_X221_dialog_content = "それにしても、海を渡って、とは…",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>禍福一如とはいいますがねぇ…\nそれで、あんな危険な航海で九死に一生を得られたワケですか…</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>…となると、この次は…</size>",
  ui_story_5038_50381501_X224_dialog_content = "今、何か言った？禍福一如？",
  ui_story_5038_50381501_X225_dialog_content = "いえいえ、ただの独り言ですよ。",
  ui_story_5038_50381501_222_dialog_content = "お、着きましたねぇ。",
  ui_story_5038_50381501_223_dialog_content = "PlayerNameの旦那、急ぎましょうか。",
  ui_story_5038_50381501_224_dialog_content = "舷側の板はしっかり打ち付けたか？",
  ui_story_5038_50381501_225_dialog_content = "ああ。まだだいぶ釘が残ってるが、誰か要るか？",
  ui_story_5038_50381501_226_dialog_content = "おや、最後の2人のご到着じゃな。",
  ui_story_5038_50381501_227_dialog_content = "さあさあ、待ったんだよ。",
  ui_story_5038_50381501_228_dialog_content = "船長、みんなそろったよ！",
  ui_story_5038_50381501_229_dialog_content = "揃ったようね？",
  ui_story_5038_50381501_230_dialog_content = "では、始めましょう。",
  ui_story_5038_50381501_231_dialog_content = "船長、もったいぶって、何を始めるんです？",
  ui_story_5038_50381501_232_dialog_content = "皆とは多くの困難を一緒に乗り越えてきたわ。",
  ui_story_5038_50381501_233_dialog_content = "だから、これから起こることも、\n一緒に見てもらいたいの。",
  ui_story_5038_50381501_234_dialog_content = "え？これから起こること？",
  ui_story_5038_50381501_235_dialog_content = "船長、報告します！",
  ui_story_5038_50381501_236_dialog_content = "修理作業、完了しました。\n点検も終わっています。",
  ui_story_5038_50381501_237_dialog_content = "これで蜃風号は新品同然です！",
  ui_story_5038_50381501_238_dialog_content = "<size=45>おおおおおお！！！</size>",
  ui_story_5038_50381501_239_dialog_content = "あ！蜃風号の修理が終わったの！？",
  ui_story_5038_50381501_240_dialog_content = "そうよ、やっと。",
  ui_story_5038_50381501_241_dialog_content = "これで今度の航海は、本当に終わったと言えるわ。",
  ui_story_5038_50381501_242_dialog_content = "航海の中、壊れ続け、修理し続けだった蜃風号が、\nようやっと元の姿に戻ったか。",
  ui_story_5038_50381501_243_dialog_content = "航海が果たされたな。",
  ui_story_5038_50381501_244_dialog_content = "見事じゃな！傷のない蜃風号がいかような姿じゃったか、\nほとんど忘れておったわ。",
  ui_story_5038_50381501_245_dialog_content = "どこもかしこもまっさらで、補修の痕もなしじゃあ、\n何だか別モノみたいですねぇ。",
  ui_story_5038_50381501_246_dialog_content = "見学はもう少し待ってもらえるかしら。",
  ui_story_5038_50381501_247_dialog_content = "もう一つ、皆と一緒に\nやらなければならないことがあるの。",
  ui_story_5038_50381501_248_dialog_content = "一緒にやらなきゃいけないこと？",
  ui_story_5038_50381501_249_dialog_content = "こっちの職人は、満足のいく作品ができた時、\n自分の名前をそこに刻むの。",
  ui_story_5038_50381501_250_dialog_content = "航海の間、私たちは何度も蜃風号を修理してきた。\nだから、ここにいる全員が蜃風を造った職人と言えるわ。",
  ui_story_5038_50381501_251_dialog_content = "だから、新しくなった蜃風号を、\n私たち全員の名前で飾りましょう。",
  ui_story_5038_50381501_252_dialog_content = "船の顔たる「兎耳」にね。",
  ui_story_5038_50381501_253_dialog_content = "ふむ、面白い！",
  ui_story_5038_50381501_254_dialog_content = "そりゃあいい案ですねぇ。",
  ui_story_5038_50381501_255_dialog_content = "ぼ、ボク、字がへただから…\nみんな、笑わないでよ！",
  ui_story_5038_50381501_256_dialog_content = "乗り気みたいね、よかったわ。",
  ui_story_5038_50381501_257_dialog_content = "では、まずは異国からの友人にお願いするわ。",
  ui_story_5038_50381501_258_dialog_content = "え？僕？",
  ui_story_5038_50381501_259_dialog_content = "ええ。龍州のおもてなしでは、\n常に客人が優先なの。",
  ui_story_5038_50381501_260_dialog_content = "さあ、この彫刻刀で好きなところに名前を刻んで。",
  ui_story_5038_50381501_261_dialog_content = "そ、そんな…なんだか悪いなぁ。",
  ui_story_5038_50381501_262_dialog_content = "それに、刻んだとしても、みんな読めないと思うし…",
  ui_story_5038_50381501_263_dialog_content = "読めなくったっていいじゃない。\nその方が字のうまいへたはバレないしね！",
  ui_story_5038_50381501_264_dialog_content = "先に選べるとは良かったのう。\n目立つところに刻むがよいぞ。",
  ui_story_5038_50381501_265_dialog_content = "そうですねぇ。\n何を迷う必要があるんです？",
  ui_story_5038_50381501_266_dialog_content = "でも…",
  ui_story_5038_50381501_267_dialog_content = "分かった…じゃあ、遠慮なく…",
  ui_story_5038_50381501_268_dialog_content = "さあ、どうぞ。",
  ui_story_5038_50381501_269_dialog_content = "（彫刻刀をしっかり握って…\n力を入れすぎないように…）",
  ui_story_5038_50381501_270_dialog_content = "（やっぱり一番上かな）",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "そうそう、そう来ないとねぇ！\n素敵じゃあありませんか。",
  ui_story_5038_50381501_273_dialog_content = "もう少し大きくてもよかったのじゃぞ。\nそれでは目立たんではないか。",
  ui_story_5038_50381501_274_dialog_content = "（海には何の跡も残らない）",
  ui_story_5038_50381501_275_dialog_content = "（穏やかな潮の流れも、激しい波も、\n結局はその時限り）",
  ui_story_5038_50381501_276_dialog_content = "（それでも人はどうにかして\n海に自分の痕跡を残そうとする）",
  ui_story_5038_50381501_277_dialog_content = "（今、僕が名前を刻んだように…）",
  ui_story_5038_50381501_278_dialog_content = "（刻まれた名前が蜃風号と共に大洋をまたにかけ、\n2つの大陸を往復し続ける）",
  ui_story_5038_50381501_279_dialog_content = "（海が何か変わるわけじゃない）",
  ui_story_5038_50381501_280_dialog_content = "（それでも誰かの心の中で、\n僕の名前は海と共にあり続けるんだ）",
  ui_story_5038_50381501_281_dialog_content = "PlayerName",
  ui_story_5038_50381501_282_dialog_content = "つづく"
}
return config
